import type { ApiOperation } from '../common/types';

export const catalogSource = {"url":"https://docs.famulor.io/api-reference/openapi.json","sha256":"398d4fa370eec1b7e4b4ab754515f44cb3c0cd4a73009e622d0dd8ca5cc14f53","count":423};

export const operations: ApiOperation[] = [
  {"id":"actOnLoopRecall","method":"POST","path":"/loop/recalls/{id}/actions","summary":"Act on a personal Loop Recall item","description":"Calls the requester, asks a selected assistant to connect the caller or arrange an appointment, or marks the authenticated member's Recall item as resolved. The item must be assigned to that member. Requires a user-owned credential with `loop:write`.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}],"body":{"required":true}},
  {"id":"addCustomDomain","method":"POST","path":"/custom-domain","summary":"Add custom domain","description":"Attaches a hostname to the platform and returns the exact ownership and routing records to configure. When the hostname is the apex or its `www` sibling, the companion host is also attached with a 308 redirect to the canonical domain. A workspace can have one custom domain. **Required scope:** `settings:write` or `assistants:write`. Requires workspace owner/admin role and the Whitelabel entitlement. **Requires the white-label entitlement** (plan add-on `whitelabel`, or a workspace override). Workspaces without it get `403 whitelabel_not_in_plan`, and only workspace owners and admins may call it.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"domain","required":true,"type":"string","description":"Hostname only; do not include a protocol or path."}]}},
  {"id":"addKnowledgeDocument","method":"POST","path":"/knowledge-bases/{id}/documents","summary":"Add or retry a document","description":"Add a document using exactly one of `content` (raw text; `name` required) or `url` (file URL, max 20 MB). Alternatively, provide `document_id` alone to retry an existing document synchronously, without creating or renaming one. For a cloud drive document, retry downloads the current remote version of only that file, even when unchanged, charges normal sync credits, preserves the previous index on failure and never imports or deletes other files. The workspace must retain cloud drive sync access and no sync may already be running. Discovery is bounded to 500 files; a target beyond that listing limit returns 422. Other source types retry their retained file or website; a purged upload without a remote source cannot be retried. Creation returns 201 with the final document, including status `error` when ingestion fails. Retry returns 200 with processing counts; failures return a non-2xx error with a safe customer message. **Required scope:** `knowledge:write` and a workspace role allowed to write (unrestricted keys retain full scope access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}],"body":{"required":true,"description":"Create a document from exactly one of content or url, or retry an existing document by supplying document_id alone. All operations process synchronously. Creation returns a document (201); retry returns processing counts (200)."}},
  {"id":"addLeads","method":"POST","path":"/campaigns/{id}/leads","summary":"Add leads","description":"Adds one lead (body = a single lead object; `data` in the response is the created lead) or many (body = an array of lead objects, max 1000; `data` is the array of created leads and `meta` reports `created`, `dnc_flagged` and `invalid` rows). Phone numbers are normalized to E.164. Optional email addresses are validated and normalized; an existing contact with the same phone or email causes a conflict instead of being silently merged. Numbers on your Do-Not-Call list are created with status `do_not_call` — the dialer never calls them. **Required scope:** `leads:write` (keys without scope restrictions have full access).","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."}],"body":{"required":true}},
  {"id":"addSuppressionEntry","method":"POST","path":"/suppression-list","summary":"Add a suppression entry","description":"Records a marketing opt-out for a contact identified by contact ID, phone, or email. The current workspace consent mode determines whether the resulting scope is universal or limited to the originating channel. **Required scope:** `suppression:write`.","tag":"Suppression","parameters":[],"body":{"required":true}},
  {"id":"archiveTool","method":"DELETE","path":"/tools/{id}","summary":"Archive an unused tool","description":"Archive an unused tool. Active assignments return `409 tool_in_use`; disabling remains available at any time. Pass the current revision as `expected_revision` or `If-Match`. **Required scope:** `assistants:write`.","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Tool ID."},{"name":"expected_revision","in":"query","required":false,"type":"integer","minimum":1},{"name":"If-Match","in":"header","required":false,"type":"string"}]},
  {"id":"askMilian","method":"POST","path":"/milian/ask","summary":"Ask Milian","description":"Ask Milian for answers, analysis, and recommendations. Requires milian:write and explicit user approval of additional workspace credits before every question. Usage is billed at the same rates as the dashboard. Milian reads only data permitted by the credential's other scopes and OAuth tool-group grants; it cannot change workspace resources. Questions are standalone, are not added to dashboard chat history, and every new call (including a retry or follow-up) can incur additional credits. Do not retry automatically. Read-only workspace roles cannot start paid questions.","tag":"Milian","parameters":[],"body":{"required":true,"fields":[{"name":"question","required":true,"type":"string","description":"The approved question and necessary context. Must contain non-whitespace text.","minLength":1,"maxLength":12000},{"name":"confirmed","required":true,"type":"boolean","description":"True only after the user explicitly approves additional Milian credits for this question. No default approval.","enum":[true]},{"name":"locale","required":false,"type":"string","description":"Fallback response language.","enum":["en","de","fr","es"]}]}},
  {"id":"assignLeadsToCampaign","method":"POST","path":"/campaigns/{id}/leads/assign","summary":"Assign leads to a campaign","description":"Assign leads to a campaign from a saved segment (`segment_id`) OR explicit `lead_ids`; provide exactly one. Unassigned contacts are moved into this campaign. Contacts already in this campaign or currently queued/calling are skipped. A contact assigned to another campaign returns a conflict before any assignments; remove it from that campaign first. Contacts are never duplicated. The compatibility field `copied` is always 0.\n\n**Required scope:** `leads:write` (`campaigns:write` and legacy `calls:write` are also accepted; unrestricted keys have full access).","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."}],"body":{"required":true,"description":"Provide exactly one of `lead_ids` or `segment_id`.","fields":[{"name":"lead_ids","required":false,"type":"array","description":"Explicit lead IDs to assign — use this OR segment_id, not both.","items":{"type":"string","format":"uuid"}},{"name":"segment_id","required":false,"type":"string","description":"Segment whose current matches are assigned — use this OR lead_ids, not both.","format":"uuid"}]}},
  {"id":"buyPhoneNumber","method":"POST","path":"/phone-numbers","summary":"Buy a phone number","description":"Starts a payment-confirmed marketplace purchase. The response is pending and includes `checkout_url`. Open this URL to review and confirm payment; it may open an authenticated in-app checkout or a hosted payment page. Routing and call access are provisioned only after verified payment. Failed, expired, or unpaid purchases release the held number. Requires a user-scoped API key. Pick a number from `GET /phone-numbers/available` first and pass its short-lived `purchase_token` unchanged. **Required scope:** `phone_numbers:write`.","tag":"Phone Numbers","parameters":[],"body":{"required":true,"fields":[{"name":"number","required":true,"type":"string","description":"The exact E.164 number returned by `GET /phone-numbers/available`."},{"name":"country","required":true,"type":"string","description":"ISO-2 country code, e.g. `DE`."},{"name":"type","required":false,"type":"string","description":"Number type of the offer. Pass the `type` returned with the number by `GET /phone-numbers/available`; defaults to `local` when omitted.","enum":["local","mobile","national"],"default":"local"},{"name":"purchase_token","required":false,"type":"string","description":"The short-lived token returned with the exact number by `GET /phone-numbers/available`; pass it unchanged. Required for workspaces that buy numbers from a reseller. Otherwise optional, but when sent it must match the number, country and type."},{"name":"assistant_id","required":false,"type":"string","description":"Optionally assign an assistant that does not already have an inbound phone number. Pending number reservations also count. An existing assignment returns HTTP 409; omit this field or set it to null to assign an assistant later.","format":"uuid"}]}},
  {"id":"callTranslationSpeaker","method":"POST","path":"/translation-sessions/{id}/call","summary":"Call a translation participant","description":"Request a callback for either speaker. Reuse the same Idempotency-Key UUID when retrying an uncertain response; a new key creates a new attempt. A connected phone participant uses the browser as a live-text observer. Requires calls:write and a credential belonging to the room host. Workspace roles, credits, assistant and calling limits apply.","tag":"Translation","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"Idempotency-Key","in":"header","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"side","required":true,"type":"integer","enum":[1,2]},{"name":"phone_number","required":true,"type":"string","description":"International E.164 telephone number."},{"name":"phone_number_id","required":false,"type":"string","format":"uuid"}]}},
  {"id":"cancelBooking","method":"POST","path":"/bookings/{id}/cancel","summary":"Cancel a booking","description":"Cancel a confirmed booking. Sends a `METHOD:CANCEL` ICS email to the invitee and removes the pushed external calendar event (both best-effort). Idempotent for already-cancelled bookings; bookings that already started return `400`.\n\n**Required scope:** `bookings:write` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Booking ID"}]},
  {"id":"cancelScheduledCallback","method":"PATCH","path":"/scheduled-callbacks/{id}","summary":"Cancel a scheduled callback","description":"Cancels a `pending` or `dialing` callback so it will not be dialed. Body must be `{ \"status\": \"cancelled\" }`. **Required scope:** `calls:write`.","tag":"Callbacks","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"status","required":true,"type":"string","enum":["cancelled"]}]}},
  {"id":"completeMessengerFacebookLogin","method":"POST","path":"/messenger/facebook-login","summary":"Complete Messenger Facebook Login","description":"Subscribe a Facebook Page to the platform Meta app and create a Messenger connector. **Required scope:** `assistants:write`. Provide `page_access_token` or `access_token` + `page_id`.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"assistant_id","required":true,"type":"string","format":"uuid"},{"name":"page_id","required":true,"type":"string"},{"name":"page_access_token","required":false,"type":"string"},{"name":"access_token","required":false,"type":"string"},{"name":"name","required":false,"type":"string"}]}},
  {"id":"completeWhatsAppEmbeddedSignup","method":"POST","path":"/whatsapp/embedded-signup","summary":"Complete WhatsApp Embedded Signup","description":"Exchange the Meta popup code, subscribe WABA, register the phone (Cloud path) or skip registration and request Business-app sync (Coexistence), then create a connector. **Required scope:** `assistants:write`. Code TTL ~30s. `phone_number_id` may be omitted on Coexistence — the server discovers it from the WABA.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"code","required":true,"type":"string"},{"name":"waba_id","required":true,"type":"string"},{"name":"phone_number_id","required":false,"type":"string"},{"name":"assistant_id","required":true,"type":"string","format":"uuid"},{"name":"name","required":false,"type":"string"},{"name":"display_phone_number","required":false,"type":"string"},{"name":"phone_number_row_id","required":false,"type":"string","format":"uuid"},{"name":"whatsapp_text_enabled","required":false,"type":"boolean"},{"name":"whatsapp_voice_enabled","required":false,"type":"boolean"},{"name":"whatsapp_outbound_voice_enabled","required":false,"type":"boolean"},{"name":"whatsapp_coexistence","required":false,"type":"boolean","description":"True to complete Embedded Signup with Coexistence (WhatsApp Business app stays on the number). Skips phone registration and requests contact plus history sync."}]}},
  {"id":"confirmSubscriptionPaymentChange","method":"POST","path":"/billing/subscription-change/confirm","summary":"Confirm subscription change","description":"Applies a reviewed existing subscription change only after explicit approval. May charge the chosen saved card and select it for future renewals. References are bound to the workspace, user and exact selection. The amount is verified again; an increase, currency change, stale reference or changed subscription requires a new review. A lower refreshed amount is allowed. No card is required for a change with no payment due. Pending payments do not grant upgrades; open the returned app billing link to complete payment. Requires a user-owned credential with billing:write scope and owner, admin or billing access in the active workspace. API Access must be enabled.","tag":"Billing","parameters":[],"body":{"required":true,"fields":[{"name":"review_ref","required":true,"type":"string","maxLength":16000},{"name":"payment_method_ref","required":false,"type":"string","description":"Reference from the same review, required when payment is due. Omit when no payment is due.","maxLength":4000},{"name":"confirm","required":true,"type":"boolean","description":"Explicit approval of the reviewed selection, amount, currency and selected card. The selected card also becomes the subscription renewal method.","enum":[true]}]}},
  {"id":"createAcuityOauthUrl","method":"POST","path":"/integrations/acuity/oauth-url","summary":"Start Acuity OAuth","description":"Creates a short-lived Acuity Scheduling OAuth authorization URL. Open the returned URL in a browser. After consent, Acuity redirects to the platform callback and the account appears in the connections endpoint. Pass `integration_id` to reconnect an existing Acuity integration. The credential must be user-bound and belong to a current workspace owner/admin (or platform admin); service-account credentials cannot complete the interactive OAuth callback. **Required scope:** `integrations:write`.","tag":"Integrations","parameters":[],"body":{"required":false,"fields":[{"name":"integration_id","required":false,"type":"string","description":"Optional existing Acuity integration to reconnect.","format":"uuid"}]}},
  {"id":"createApiKey","method":"POST","path":"/api-keys","summary":"Create an API key","description":"Mints a new self-service API key for the calling workspace. `scopes` must be a subset of the calling credential's own scopes — a key can never mint another key with broader access than itself (a caller with unrestricted access, i.e. no scopes or `*`, may grant any scope, and an omitted `scopes` defaults to its own scopes). A new key cannot outlive a finite calling credential. Requires the calling credential to be a workspace owner/admin (service-account keys always qualify). The plaintext key is returned exactly once and cannot be retrieved again. **Required scope:** `settings:write`.","tag":"API Keys","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","maxLength":100},{"name":"scopes","required":false,"type":"array","description":"Must be a subset of the calling credential's own scopes — a key can never mint another key with broader access than itself. Omitted defaults to the calling credential's own scopes (or, if the credential itself has unrestricted access, every scope).","items":{"type":"string"}},{"name":"expires_in_days","required":false,"type":"integer","description":"Requested lifetime. Omitted inherits a finite calling credential's expiry, or means no expiry when the caller itself does not expire.","minimum":1,"maximum":365}]}},
  {"id":"createAssistant","method":"POST","path":"/assistants","summary":"Create an assistant","description":"Creates an assistant. Provide `name`, or pass a visible catalog `template_id` to resolve its prompt, greeting, language, variables and optional Flow JSON server-side. Explicit request fields override the template seed. Default agent type is **Single prompt** (`flow_json` omitted or `null` — uses `system_prompt` + greeting). For **Conversational flow**, pass a Flow JSON v1 object in `flow_json` (typically a Start→Agent→End seed). Model fields are validated against the platform model catalog, the workspace assistant limit is enforced, and non-trivial flows may require the Flow Builder feature. Pipeline and Half-cascade assistants are checked against the languages their voice can speak: a request whose voice can't speak the primary language, a secondary language or a language with its own voice returns `400 invalid_request`. Without `tts_voice`, a default voice that speaks the primary language is chosen. **Required scope:** `assistants:write` (keys without scope restrictions have full access).","tag":"Assistants","parameters":[],"body":{"required":true}},
  {"id":"createAssistantAutomation","method":"POST","path":"/assistants/{id}/automations","summary":"Create and connect an assistant automation","description":"Create a draft automation and securely connect it across voice, web chat, messaging, and email conversations. Credentials and assignment are handled automatically. Requires both `assistants:write` and `automations:write`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}],"body":{"required":true,"fields":[{"name":"name","required":false,"type":"string","maxLength":200},{"name":"tool_description","required":true,"type":"string","description":"Explain exactly when the assistant should run this automation.","minLength":10,"maxLength":1000}]}},
  {"id":"createAssistantTest","method":"POST","path":"/assistants/{id}/tests","summary":"Create simulation test","description":"Create a simulation test. **Required scope:** `assistants:write`. Requires the Simulations feature in the workspace plan.","tag":"Simulations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string"},{"name":"persona","required":false,"type":"string"},{"name":"script","required":false,"type":"string"},{"name":"success_criteria","required":false,"type":"array","items":{"type":"object"}},{"name":"max_turns","required":false,"type":"integer","minimum":1,"maximum":20},{"name":"is_active","required":false,"type":"boolean"}]}},
  {"id":"createAssistantTestFromCall","method":"POST","path":"/assistants/{id}/tests/from-call","summary":"Create simulation test from call","description":"Create a simulation test from an existing call transcript and analysis. **Required scope:** `assistants:write`. Requires the Simulations feature in the workspace plan.","tag":"Simulations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"call_id","required":true,"type":"string","description":"Call in the same workspace to turn into a regression test.","format":"uuid"}]}},
  {"id":"createAudienceContact","method":"POST","path":"/leads","summary":"Create an Audience contact","description":"Create an unassigned Audience contact, or merge user-defined tags and missing identity fields into an existing contact with the same phone or email. **Required scope:** `leads:write` (legacy `calls:write` is also accepted).","tag":"Leads","parameters":[],"body":{"required":true}},
  {"id":"createAutomation","method":"POST","path":"/automations","summary":"Create automation","description":"Create a native automation graph. The `conversation.started` trigger covers messaging and web chat, including widget previews. Set `trigger.platform` to `web_widget` to select web chat; submitted form fields are in `data.preform.values` and assistant input variables in `data.input_variables`. Optional `tags` (`string[]`). Binding `trigger.assistant_id` on an active `call.completed` automation updates the assistant webhook delivery mode. Graph actions may include `app.execute` (run an action in an app connected under Apps); triggers may use `app.event` (an event from a connected app). Reads always return these ids. **Required scope:** `automations:write` or `calls:write`.","tag":"Automations","parameters":[]},
  {"id":"createAutomationConnection","method":"POST","path":"/automations/connections","summary":"Create automation connection","description":"Store a reusable workspace credential. `kind` is `api` (provider REST API — e.g. Airtable PAT, HubSpot Private App token, SMTP host/user/password, Apps connected account) or `mcp` (remote MCP endpoint). App connections (`provider=connected_app`) are created in the app under **Automations → Connections → Add Connection → Browse apps** (OAuth sign-in with the app); their `config.toolkit` names the connected app (secrets never returned). `credentials` values are AES-256-GCM encrypted at rest. For `provider=smtp`, Test Connection verifies the relay and sends a test email to the calling admin. **Required scope:** `automations:write` or `calls:write`.","tag":"Automations","parameters":[]},
  {"id":"createBillingPortalLink","method":"POST","path":"/billing/portal","summary":"Create billing management link","description":"Creates a short-lived, one-time billing link on the current platform domain for invoice history, payment methods, and cancellation. This recovery operation remains available with a valid credential when API Access is paused after a failed plan payment. The credential's current workspace role must be `owner`, `admin`, or `billing`. Plan changes are disabled in the portal; use the app plan page or the subscription-change review and confirmation operations. No payment-provider identifiers are returned. **Required scope:** `billing:write`; `billing:read` is insufficient (keys without scope restrictions have full access).","tag":"Billing","parameters":[]},
  {"id":"createBooking","method":"POST","path":"/bookings","summary":"Create a booking","description":"Book a free start time of an event type for an invitee. `start` must come from `GET /booking-event-types/{id}/slots`, unless `allow_outside_availability` is true (staff override: any future time within 2 years that does not overlap a confirmed booking of the same event type); otherwise a slot that is no longer free returns `409`. The invitee receives the confirmation email with a calendar invitation (when an email address is given), and the event type's webhook and automations fire. Stored `source` is `api`.\n\nThere is no idempotency key: retrying the same request for the same slot returns `409` via the database's overlap constraint.\n\nA `503` here can mean either request protection is temporarily unavailable (`internal_error`) or the availability engine itself failed to load (`service_unavailable`, message \"Could not load availability\").\n\n**Required scope:** `bookings:write` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[],"body":{"required":true,"fields":[{"name":"event_type_id","required":true,"type":"string","description":"Event type ID.","format":"uuid"},{"name":"start","required":true,"type":"string","description":"Start time in ISO 8601 UTC — must be a value returned by List free slots, unless allow_outside_availability is set.","format":"date-time"},{"name":"name","required":true,"type":"string","description":"Invitee name.","minLength":1,"maxLength":128},{"name":"email","required":false,"type":"string","description":"Invitee email — required when the event type requires it (e.g. a Google Meet/Teams location)."},{"name":"phone","required":false,"type":"string","description":"International format, e.g. +4915123456789. Required when the event type requires it."},{"name":"notes","required":false,"type":"string","description":"Notes attached to the booking.","maxLength":2000},{"name":"answers","required":false,"type":"object","description":"Answers to the event type's custom booking questions, keyed by BookingField.id."},{"name":"timezone","required":false,"type":"string","description":"IANA time zone used for the invitee's confirmation email and calendar invite; does not affect how `start` is parsed. Default the workspace time zone."},{"name":"hour_cycle","required":false,"type":"string","description":"Time format used in the invitee's confirmation email; default 24h.","enum":["12h","24h"]},{"name":"allow_outside_availability","required":false,"type":"boolean","description":"Set true to book outside the event type's open times (staff override). Any future time within the next 2 years is accepted; the time must not overlap another confirmed booking of the same event type. Guests on the public booking page only ever see open times.","default":false}]}},
  {"id":"createBookingEventType","method":"POST","path":"/booking-event-types","summary":"Create a booking event type","description":"Create an event type. The slug is **unique within the workspace** and becomes the public booking page URL `/book/{workspace}/{slug}`. Requires an admin-level credential; requires Calendar integrations in the workspace plan.\n\n**Required scope:** `bookings:write` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","maxLength":128},{"name":"slug","required":true,"type":"string"},{"name":"duration_min","required":true,"type":"integer","minimum":5,"maximum":480},{"name":"timezone","required":true,"type":"string"},{"name":"availability","required":true,"type":"object"},{"name":"description","required":false,"type":"string","maxLength":2000},{"name":"buffer_before_min","required":false,"type":"integer","default":0},{"name":"buffer_after_min","required":false,"type":"integer","default":0},{"name":"min_notice_min","required":false,"type":"integer","default":60},{"name":"max_days_ahead","required":false,"type":"integer","default":30},{"name":"slot_increment_min","required":false,"type":"integer"},{"name":"reminder_hours","required":false,"type":"integer"},{"name":"is_active","required":false,"type":"boolean","default":true},{"name":"booking_fields","required":false,"type":"array","description":"Custom booking questions, in display order. Name is always required; email_required and phone_required control the system contact fields.","items":{"type":"object","description":"A custom booking question asked on the public booking page. Answers are keyed by `id` on a booking's `answers` object and can be prefilled on the public booking page via the matching URL parameter."}},{"name":"phone_required","required":false,"type":"boolean","description":"Require the visitor's phone number (E.164) to book. When false (default), phone is still asked but optional.","default":false},{"name":"email_required","required":false,"type":"boolean","description":"Whether an invitee email is required. Google Meet and Microsoft Teams always require a valid email.","default":true},{"name":"sender_email_address_id","required":false,"type":"string","description":"Active verified email address belonging to this workspace. Null uses automatic workspace or inherited reseller SMTP, then the platform identity for eligible workspaces.","format":"uuid"},{"name":"confirmation_email_subject","required":false,"type":"string","description":"Custom initial confirmation subject; empty uses the standard subject. Supports the same booking variables as the message.","maxLength":200},{"name":"confirmation_email_body","required":false,"type":"string","description":"Custom plain-text confirmation. Supported variables are returned by GET /booking-email-templates. Blank/null restores the localized standard message.","maxLength":10000},{"name":"email_templates","required":false,"type":"object","description":"Complete replacement of the six additional guest/host email templates. Omit to preserve saved values; null or {} restores all six defaults. Confirmation uses the existing confirmation subject/body fields. GET /booking-email-templates returns standard templates and supported variables."},{"name":"email_locale","required":false,"type":"string","description":"Language of the standard booking email texts (guest and host) for this event type. null (default) uses each recipient's language. Custom subject/body text is sent as written.","enum":["en","de","fr","es",null]},{"name":"guest_emails_enabled","required":false,"type":"boolean","description":"Send emails to the invitee. false = no confirmation, cancellation, reschedule or reminder emails to guests and no invitations from the connected calendar (the guest is not added as an attendee); host notifications still send.","default":true},{"name":"hour_cycle","required":false,"type":"string","description":"Time format for the weekly availability editor and host emails. Availability values remain HH:mm. Guest emails follow the guest's saved booking-page preference, falling back to this format for older bookings.","enum":["12h","24h"],"default":"24h"}]}},
  {"id":"createCalendlyOauthUrl","method":"POST","path":"/integrations/calendly/oauth-url","summary":"Start Calendly OAuth","description":"Creates a short-lived Calendly OAuth 2.1 authorization URL with PKCE S256. Open the returned URL in a browser. After consent, Calendly redirects to the platform callback and the account appears in the connections endpoint. Pass `integration_id` to reconnect a legacy PAT-backed integration. The credential must be user-owned and belong to a workspace owner or admin; workspace service-account credentials get `403`. **Required scope:** `integrations:write`.","tag":"Integrations","parameters":[],"body":{"required":false,"fields":[{"name":"integration_id","required":false,"type":"string","description":"Optional existing Calendly integration to reconnect.","format":"uuid"}]}},
  {"id":"createCall","method":"POST","path":"/calls","summary":"Start an outbound call","description":"Places an outbound call: the assistant must be active and needs an outbound-capable phone number (assigned to it, or passed via `phone_number_id`). Returns the created call immediately (status `queued`) — poll `GET /calls/{id}` or use the assistant's webhook for the result and provider-neutral `failure` guidance. Destinations that are not allowed return `403 destination_forbidden`. **Required scope:** `calls:write` (keys without scope restrictions have full access).","tag":"Calls","parameters":[],"body":{"required":true,"fields":[{"name":"assistant_id","required":true,"type":"string","description":"Assistant that runs the call. Must be active.","format":"uuid"},{"name":"to_number","required":true,"type":"string","description":"Destination in E.164 format, e.g. `+4930123456`."},{"name":"lead","required":false,"type":"object","description":"Contact context. Custom fields follow the assistant contact-field access settings and do not fill same-named manual variables; use variables for explicit scenario inputs."},{"name":"phone_number_id","required":false,"type":"string","description":"Optional explicit caller ID (one of your phone numbers). Defaults to the number assigned to the assistant.","format":"uuid"},{"name":"variables","required":false,"type":"object","description":"Explicit per-call values. Strings are limited to 2000 characters; numbers and booleans become text. Values are sanitized before use. Does not edit assistant definitions or contact fields; durable retention follows the configured variable memory policy."}]}},
  {"id":"createCallerId","method":"POST","path":"/caller-ids","summary":"Start caller ID verification","description":"**Required scope:** `phone_numbers:write` or `calls:write`.","tag":"Caller IDs","parameters":[],"body":{"required":true,"fields":[{"name":"number","required":true,"type":"string"},{"name":"friendly_name","required":false,"type":"string"}]}},
  {"id":"createCampaign","method":"POST","path":"/campaigns","summary":"Create a campaign","description":"Creates a campaign in status `draft`. Dialer settings (concurrency, retries, calling windows, AMD/voicemail behavior) can be set right away. The plan's campaign limit is enforced (archived campaigns do not count). **Required scope:** `campaigns:write` (keys without scope restrictions have full access).","tag":"Campaigns","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string"},{"name":"assistant_id","required":false,"type":"string","description":"Assistant that runs the calls. Must belong to your workspace.","format":"uuid"},{"name":"channel","required":false,"type":"string","enum":["phone_call","whatsapp_template","whatsapp_call","sms"]},{"name":"channel_config","required":false,"type":"object"},{"name":"follow_up_config","required":false,"type":"object","description":"Optional voice follow-up after retries are exhausted. `channel` is `off` | `whatsapp_template` | `sms` | `email`. Email is follow-up only and uses `subject`, `message`, and `variable_mapping`; it sends from the campaign assistant address."},{"name":"scheduled_start_at","required":false,"type":"string","format":"date-time"},{"name":"concurrency","required":false,"type":"integer","description":"Maximum parallel voice calls for this campaign. Must fit the workspace's effective Concurrent Lines allowance, including add-ons. Calls across campaigns share that workspace allowance.","minimum":1,"maximum":2147483647},{"name":"retry_max","required":false,"type":"integer","minimum":0},{"name":"retry_delay_minutes","required":false,"type":"integer","minimum":1},{"name":"calling_windows","required":false,"type":"object","description":"Allowed calling windows per weekday, local to the campaign `timezone`. Keys: `mon`–`sun`; each value is an array of `[\"HH:MM\", \"HH:MM\"]` start/end pairs (24h). An empty array or missing key blocks the whole day."},{"name":"timezone","required":false,"type":"string","description":"IANA timezone, e.g. `Europe/Berlin`."},{"name":"amd_enabled","required":false,"type":"boolean"},{"name":"voicemail_action","required":false,"type":"string","enum":["hangup","drop_message"]},{"name":"voicemail_message","required":false,"type":"string","description":"Required when `voicemail_action` is `drop_message`."},{"name":"amd_mode","required":false,"type":"string","description":"Answering-machine detection sensitivity when AMD is enabled.","enum":["conservative","aggressive"]},{"name":"ivr_navigation","required":false,"type":"boolean","description":"Allow navigating phone menus. Enabling requires workspace Beta features."}]}},
  {"id":"createCarrierConnection","method":"POST","path":"/carrier-connections","summary":"Create a carrier connection","description":"Validates carrier credentials and stores secrets encrypted. Provider routing is configured on the first number import. **Required scope:** `sip_trunks:write`.","tag":"Carrier Connections","parameters":[],"body":{"required":true,"fields":[{"name":"carrier","required":true,"type":"string","enum":["twilio","telnyx","vonage"]},{"name":"name","required":true,"type":"string","minLength":1,"maxLength":80},{"name":"account_sid","required":false,"type":"string","description":"Required for Twilio."},{"name":"auth_token","required":false,"type":"string","description":"Required for Twilio; stored encrypted.","writeOnly":true},{"name":"api_key","required":false,"type":"string","description":"Required for Telnyx and Vonage. Telnyx keys start with KEY."},{"name":"api_secret","required":false,"type":"string","description":"Required for Vonage; stored encrypted.","writeOnly":true},{"name":"sip_region","required":false,"type":"string","enum":["global","eu","us","uk","india","japan","aus","sa"],"default":"global"}]}},
  {"id":"createCrawlSource","method":"POST","path":"/knowledge-bases/{id}/crawl-sources","summary":"Create a crawl source","description":"Register a website as a crawl source for a knowledge base. You can provide an optional custom `name`; when omitted, the source receives a URL-based display name that can be edited later. The crawler fetches pages under `root_url` (same host only, static HTML — no JavaScript rendering, max 2 MB per page), indexes them as documents and charges credits per crawled page. Trigger a crawl with `POST /knowledge-bases/{id}/crawl-sources/{sourceId}/run`, or enable `auto_sync` for periodic re-crawls. **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}],"body":{"required":true,"fields":[{"name":"name","required":false,"type":"string","description":"Optional custom display name shown for this source. If omitted, a URL-based name is assigned and can be edited later.","minLength":1,"maxLength":128},{"name":"root_url","required":true,"type":"string","description":"Root URL to crawl (http/https)."},{"name":"include_paths","required":false,"type":"array","description":"Optional paths to restrict crawling (e.g. [\"/docs\"]). Empty = whole host. End an entry with $ to match only that exact page (for example /impressum$); without $ it is a prefix.","items":{"type":"string"}},{"name":"exclude_paths","required":false,"type":"array","description":"Optional paths to skip (e.g. [\"/admin\"]). Max 200 per source, 500 per knowledge base. End an entry with $ to match only that exact page (for example /impressum$); without $ it is a prefix.","items":{"type":"string"}},{"name":"max_pages","required":false,"type":"integer","description":"Maximum pages per run. Default 50.","minimum":1,"maximum":500},{"name":"auto_sync","required":false,"type":"boolean","description":"Re-crawl automatically on a schedule. Default false."},{"name":"sync_interval_hours","required":false,"type":"integer","description":"Hours between auto-sync crawls. Default 24. Common values: 24 = daily, 168 = weekly, 720 = monthly, 2160 = every 3 months, 4320 = every 6 months.","minimum":1}]}},
  {"id":"createCrmSync","method":"POST","path":"/crm-syncs","summary":"Create CRM sync","description":"Create a recurring CRM sync using an existing API connection. Direction can import CRM records into Audience, push Audience contacts to the CRM, or both on the same schedule. Combined {{field}} expressions are import-only; outbound needs a 1:1 phone or email mapping. The provider is resolved from the tenant-scoped connection and cannot be supplied by the caller. Requires `automations:write` or `calls:write`.","tag":"Automations","parameters":[],"body":{"required":true,"fields":[{"name":"connection_id","required":true,"type":"string","format":"uuid"},{"name":"name","required":true,"type":"string","minLength":1,"maxLength":128},{"name":"object_type","required":true,"type":"string","minLength":1,"maxLength":128},{"name":"selection","required":false,"type":"object","description":"Provider-neutral source selection. Discovered list/view/filter IDs use `sourceId`. Set `default_phone_country` to a supported ISO-2 code (for example `DE`) to normalize national phone numbers; international `+`/`00` values take priority. Required provider fields are derived from the mapping."},{"name":"field_mapping","required":true,"type":"object","description":"External source to Audience target. A bare key keeps legacy 1:1 behavior. To combine fields or fixed text, use non-evaluated `{{field}}` tokens in one source expression, for example `{{salutation}} {{firstName}} {{lastName}}` or `+49{{phone}}`. Destinations include channel identities such as `channel.telegram.username` or `channel.whatsapp.user_id`. At least one target must be `phone` or `email`, and each target appears once."},{"name":"interval_minutes","required":false,"type":"integer","minimum":60,"maximum":10080,"default":60},{"name":"null_policy","required":false,"type":"string","enum":["ignore","clear"],"default":"ignore"},{"name":"removal_policy","required":false,"type":"string","enum":["deactivate_membership","keep"],"default":"deactivate_membership"},{"name":"conflict_policy","required":false,"type":"string","enum":["review","skip"],"default":"review"},{"name":"direction","required":false,"type":"string","description":"inbound imports CRM records into Audience. outbound pushes Audience contacts to the CRM. bidirectional runs inbound first, then outbound, on the same schedule.","enum":["inbound","outbound","bidirectional"],"default":"inbound"},{"name":"outbound_create","required":false,"type":"boolean","description":"When direction includes outbound, create CRM records for unlinked Audience contacts. Defaults to true for outbound-only syncs.","default":false}]}},
  {"id":"createDashboard","method":"POST","path":"/dashboards","summary":"Create a custom dashboard","description":"Creates a dashboard in the API key's workspace. **Required scope:** `dashboards:write` or `calls:write`.","tag":"Dashboards","parameters":[],"body":{"required":true,"description":"Create requires name. PATCH accepts name, sort_order, show_default_sections, and/or hidden_default_sections.","fields":[{"name":"name","required":false,"type":"string","minLength":1,"maxLength":120},{"name":"sort_order","required":false,"type":"integer","minimum":0,"maximum":1000000},{"name":"show_default_sections","required":false,"type":"boolean","description":"Set false for a blank canvas or true to restore the built-in overview."},{"name":"hidden_default_sections","required":false,"type":"array","description":"Complete list of built-in cards to hide individually; send an empty array to restore all.","items":{"type":"string","enum":["filter_bar","kpi_conversations","kpi_completion_rate","kpi_average_duration","kpi_success_rate","kpi_conversation_spend","call_activity","outcome_mix","assistant_performance","post_call_intelligence","campaign_funnel","module_assistants","module_campaigns","module_audience","module_booking","module_knowledge","module_simulations","module_live_monitoring","module_tools","module_phone_numbers","recent_calls"]}}]}},
  {"id":"createDashboardWidget","method":"POST","path":"/dashboards/{id}/widgets","summary":"Create or attach a dashboard widget","description":"Create and attach a widget, or provide `widget_id` to attach an existing reusable widget. **Required scope:** `dashboards:write` or `calls:write`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."}],"body":{"required":true,"description":"POST: provide widget_id to attach an existing reusable widget, or name to create one. PATCH: only provided fields change.","fields":[{"name":"widget_id","required":false,"type":"string","format":"uuid"},{"name":"name","required":false,"type":"string","minLength":1,"maxLength":120},{"name":"widget_type","required":false,"type":"string","enum":["statistic","chart","table"]},{"name":"data_table","required":false,"type":"string","enum":["calls","campaigns","assistants","phone_numbers","conversions","leads","knowledge_bases","bookings","tools","simulations"]},{"name":"aggregation","required":false,"type":"string","enum":["count","sum","avg","max","min"]},{"name":"column_name","required":false,"type":"string"},{"name":"compare_previous_period","required":false,"type":"boolean"},{"name":"rate_range","required":false,"type":"string","enum":["7d","14d","30d","90d"]},{"name":"table_columns","required":false,"type":"array","items":{"type":"string"}},{"name":"assistant_id","required":false,"type":"string"},{"name":"visualization","required":false,"type":"string","enum":["auto","number","line","area","bar","stacked_bar","donut","pie","funnel","heatmap","table","leaderboard"]},{"name":"group_by","required":false,"type":"string"},{"name":"campaign_id","required":false,"type":"string","format":"uuid"},{"name":"show_legend","required":false,"type":"boolean"},{"name":"show_values","required":false,"type":"boolean"},{"name":"description","required":false,"type":"string"},{"name":"conditions","required":false,"type":"array","items":{"type":"object"}},{"name":"sort_order","required":false,"type":"integer","minimum":0},{"name":"grid_w","required":false,"type":"integer","minimum":3,"maximum":12},{"name":"grid_h","required":false,"type":"integer","minimum":1,"maximum":4}]}},
  {"id":"createDriveSource","method":"POST","path":"/knowledge-bases/{id}/drive-sources","summary":"Create a cloud drive source","description":"Register a Google Drive, OneDrive, Box, Dropbox, or SharePoint folder as a sync source for a knowledge base, using an existing app connection (Automations → Connections). You can provide an optional custom `name`; when omitted, the remote folder name or ID becomes the initial display name and can be edited later. The sync lists files under `folder_id` (optionally recursive), indexes them as documents and charges credits per new/changed file. Trigger a sync with `POST /knowledge-bases/{id}/drive-sources/{sourceId}/run`, or enable `auto_sync` for periodic re-syncs. **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}],"body":{"required":true,"fields":[{"name":"name","required":false,"type":"string","description":"Optional custom display name shown for this source. If omitted, `folder_name` or `folder_id` is used initially and can be edited later.","minLength":1,"maxLength":128},{"name":"provider","required":true,"type":"string","description":"Cloud drive provider.","enum":["googledrive","one_drive","box","dropbox","sharepoint_graph"]},{"name":"connection_id","required":true,"type":"string","description":"App connection ID — a connection under Automations → Connections whose toolkit matches `provider`.","format":"uuid"},{"name":"folder_id","required":true,"type":"string","description":"Remote folder ID to sync."},{"name":"folder_name","required":false,"type":"string","description":"Optional remote folder name captured from the connected drive. This is provider metadata, not the editable source `name`."},{"name":"drive_id","required":false,"type":"string","description":"Document library drive ID. REQUIRED for provider \"sharepoint_graph\"; optional for \"one_drive\" (SharePoint/Business drives accessed via the OneDrive toolkit); unused otherwise."},{"name":"include_subfolders","required":false,"type":"boolean","description":"Recurse into subfolders. Default true."},{"name":"max_files","required":false,"type":"integer","description":"Maximum files per run. Default 50.","minimum":1,"maximum":500},{"name":"auto_sync","required":false,"type":"boolean","description":"Re-sync automatically on a schedule. Default false."},{"name":"sync_interval_hours","required":false,"type":"integer","description":"Hours between auto-sync runs. Default 24. Common values: 24 = daily, 168 = weekly, 720 = monthly, 2160 = every 3 months, 4320 = every 6 months.","minimum":1}]}},
  {"id":"createEmailAddress","method":"POST","path":"/email/addresses","summary":"Create an email address","description":"Creates an address on an already-**verified** domain, optionally assigned to an assistant so it can send and receive on that address. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"domain_id","required":true,"type":"string","description":"Must belong to an already-verified domain.","format":"uuid"},{"name":"local_part","required":true,"type":"string"},{"name":"assistant_id","required":false,"type":"string","format":"uuid"},{"name":"display_name","required":false,"type":"string","maxLength":128}]}},
  {"id":"createEmailDomain","method":"POST","path":"/email/domains","summary":"Connect an email domain","description":"Connects a new domain to the email channel. Returns the domain in `pending` status together with the DNS records (CNAMEs for sending/DKIM, an MX record for receiving) to add before calling `POST /email/domains/{id}/verify`. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"domain","required":true,"type":"string"}]}},
  {"id":"createIntegration","method":"POST","path":"/integrations","summary":"Create a calendar integration","description":"Create a calendar integration. The connection is verified **before** saving (Cal.com: API key + event type; Calendly: OAuth `connection_id` + public `event_type_id`; Acuity: OAuth `connection_id` + numeric `appointment_type_id` and optional `calendar_id`; google/outlook: the calendar connection must exist; native: the booking event type must exist) — invalid credentials are rejected with `400` and never stored. Calendly resource URIs, Acuity account identifiers, and all OAuth tokens stay internal. Requires a user-owned credential of a workspace owner or admin (workspace service-account credentials can only read calendar integrations and get `403`) and a plan that includes calendar integrations.\n\n**Required scope:** `integrations:write` (keys without scope restrictions have full access).\n\nmeetergo verifies the chosen meeting type using scheduling access before saving. Discover meeting types through POST /integrations/meetergo/meeting-types.","tag":"Integrations","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","maxLength":64},{"name":"provider","required":true,"type":"string","enum":["calcom","calendly","acuity","google_calendar","outlook_calendar","native","etermin","meetergo","highlevel"]},{"name":"config","required":true,"type":"object","description":"Provider-specific configuration (see the Integration schema). For Acuity send an OAuth `connection_id`, numeric `appointment_type_id`, optional `calendar_id`, and optional `allowed_ops`; appointment metadata and timezone are loaded canonically from Acuity. For meetergo use a personal access token or platform API key in token_encrypted, a meeting_type_id, optional timezone, and allowed_ops.book. Platform API keys also require acting_user_id; personal tokens must omit it. Meeting title and duration are verified with the provider. Native meetergo supports availability and booking; use the meetergo MCP app for other operations."},{"name":"is_active","required":false,"type":"boolean","default":true}]}},
  {"id":"createInvoicePaymentLink","method":"POST","path":"/billing/invoice-payment","summary":"Create invoice payment link","description":"Creates a short-lived, one-time billing link on the current platform domain. The link opens the oldest payable workspace invoice and falls back to billing management when no payable invoice exists. This recovery operation remains available with a valid credential when API Access is paused after a failed plan payment. The credential's current workspace role must be `owner`, `admin`, or `billing`. No payment-provider identifiers are returned. **Required scope:** `billing:write`; `billing:read` is insufficient (keys without scope restrictions have full access).","tag":"Billing","parameters":[]},
  {"id":"createKnowledgeBase","method":"POST","path":"/knowledge-bases","summary":"Create a knowledge base","description":"Creates an empty knowledge base. Attach it to an assistant via the assistant's `knowledgebase_id`. **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string"},{"name":"description","required":false,"type":"string"}]}},
  {"id":"createKnowledgeBaseFaq","method":"POST","path":"/knowledge-bases/{id}/faqs","summary":"Create and publish an FAQ entry","description":"Creates human-approved FAQ knowledge and indexes it immediately. **Required scope:** `knowledge:write`.","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"question","required":true,"type":"string","maxLength":2000},{"name":"answer","required":true,"type":"string","maxLength":16000}]}},
  {"id":"createLoopQueue","method":"POST","path":"/loop/queues","summary":"Create a Loop call queue","description":"Creates a Loop call queue. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","minLength":1,"maxLength":120},{"name":"strategy","required":true,"type":"string","enum":["longest_idle","round_robin","sequential"]},{"name":"max_wait_seconds","required":true,"type":"integer","minimum":10,"maximum":3600},{"name":"wrap_up_seconds","required":true,"type":"integer","minimum":0,"maximum":600},{"name":"overflow_rule_id","required":true,"type":"string","format":"uuid"},{"name":"active","required":true,"type":"boolean"},{"name":"member_ids","required":false,"type":"array","description":"Legacy member list. Use members for ordered capacity settings.","items":{"type":"string","format":"uuid"}},{"name":"members","required":false,"type":"array","description":"Members in queue order with concurrent-call capacity.","items":{"type":"object"}}]}},
  {"id":"createLoopRingGroup","method":"POST","path":"/loop/ring-groups","summary":"Create a Loop ring group","description":"Creates a Loop ring group. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","minLength":1,"maxLength":120},{"name":"strategy","required":true,"type":"string","enum":["simultaneous","sequential","round_robin"]},{"name":"ring_timeout_seconds","required":true,"type":"integer","minimum":5,"maximum":120},{"name":"presence_required","required":true,"type":"boolean"},{"name":"active","required":true,"type":"boolean"},{"name":"member_ids","required":false,"type":"array","description":"Legacy member list. Use members for ordered delay settings.","items":{"type":"string","format":"uuid"}},{"name":"members","required":false,"type":"array","description":"Members in ringing order with an optional pre-ring delay.","items":{"type":"object"}}]}},
  {"id":"createLoopRoutingRule","method":"POST","path":"/loop/routing-rules","summary":"Create a Loop routing rule","description":"Creates an ordered routing rule with optional weekly hours and time-conditioned steps. Continuation outcomes cover pre-answer failures only; an answered person or assistant is terminal. Cycles are rejected. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","minLength":1,"maxLength":120},{"name":"active","required":true,"type":"boolean"},{"name":"schedule_enabled","required":false,"type":"boolean","default":false},{"name":"schedule_timezone","required":false,"type":"string","description":"IANA timezone, or null to inherit the workspace timezone."},{"name":"weekly_availability","required":false,"type":"object"},{"name":"steps","required":true,"type":"array","items":{"type":"object"}}]}},
  {"id":"createMessagingConnector","method":"POST","path":"/messaging-connectors","summary":"Create messaging connector","description":"Connect a chat app with its credentials (platform-specific fields are required). Help desk, mailbox, Instagram and Zulip channels are connected in the dashboard, not here. Conversation settings optional (`response_delay_sec` 0–30 default 5, `inactivity_timeout_min` default 30, `allow_retrigger`, `conversation_ended_webhook_url`). **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"platform","required":true,"type":"string","description":"Chat apps that connect with credentials. The other channels returned by `GET /messaging-connectors` are connected in the dashboard.","enum":["telegram","slack","messenger","teams","discord","gchat","x","whatsapp"]},{"name":"name","required":true,"type":"string","maxLength":120},{"name":"assistant_id","required":true,"type":"string","format":"uuid"},{"name":"bot_token","required":false,"type":"string"},{"name":"bot_username","required":false,"type":"string"},{"name":"signing_secret","required":false,"type":"string"},{"name":"team_name","required":false,"type":"string"},{"name":"page_access_token","required":false,"type":"string"},{"name":"app_secret","required":false,"type":"string"},{"name":"verify_token","required":false,"type":"string"},{"name":"page_name","required":false,"type":"string"},{"name":"phone_number_id","required":false,"type":"string","description":"WhatsApp Cloud API phone number ID"},{"name":"access_token","required":false,"type":"string","description":"WhatsApp permanent System User token"},{"name":"waba_id","required":false,"type":"string","description":"WhatsApp Business Account ID"},{"name":"display_phone_number","required":false,"type":"string"},{"name":"whatsapp_text_enabled","required":false,"type":"boolean"},{"name":"whatsapp_voice_enabled","required":false,"type":"boolean"},{"name":"whatsapp_outbound_voice_enabled","required":false,"type":"boolean"},{"name":"response_delay_sec","required":false,"type":"integer","minimum":0,"maximum":30},{"name":"inactivity_timeout_min","required":false,"type":"integer","minimum":1,"maximum":1440},{"name":"allow_retrigger","required":false,"type":"boolean"},{"name":"conversation_ended_webhook_url","required":false,"type":"string","format":"uri"}]}},
  {"id":"createMilianVoiceSession","method":"POST","path":"/milian/voice-sessions","summary":"Start a Milian voice session","description":"Create a short-lived live voice connection after explicit approval of additional workspace credits. Requires milian:write, a writable user credential, workspace Beta Features and an eligible plan. Each session starts a new conversation. Workspace tools retain the credential scopes and role. Connect using the returned URL and subprotocols within 60 seconds. Clients can supply optional visible page text; explicit screen sharing takes priority. Screen analysis also consumes credits. Do not retry automatically. See the Milian API guide for the WebSocket protocol.","tag":"Milian","parameters":[],"body":{"required":true,"fields":[{"name":"approve_credit_usage","required":true,"type":"boolean","description":"Explicit user approval for this paid session."},{"name":"context","required":false,"type":"object"}]}},
  {"id":"createPlatformCustomPayment","method":"POST","path":"/platform/users/{user_id}/custom-payments","summary":"Create a custom payment for a customer","description":"Charges a customer a one-off amount or starts a custom recurring subscription, outside their regular plan. **Required scope:** `platform:write`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"user_id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"kind","required":true,"type":"string","enum":["one_time","subscription"]},{"name":"channel","required":true,"type":"string","enum":["charge_saved_method","payment_link","invoice"]},{"name":"description","required":true,"type":"string","maxLength":500},{"name":"quantity","required":false,"type":"integer","minimum":1,"maximum":999,"default":1},{"name":"amount_minor","required":true,"type":"integer","description":"Unit price in the currency's smallest unit. Total charged = amount_minor * quantity.","minimum":1},{"name":"currency","required":true,"type":"string","description":"3-letter ISO currency code, e.g. EUR.","minLength":3,"maxLength":3},{"name":"interval","required":false,"type":"string","description":"Required when kind is subscription.","enum":["day","week","month","year"]},{"name":"interval_count","required":false,"type":"integer","minimum":1,"maximum":365,"default":1},{"name":"trial_days","required":false,"type":"integer","description":"Subscription only. Not available on the invoice channel.","minimum":0,"maximum":730},{"name":"days_until_due","required":false,"type":"integer","description":"Invoice channel only.","minimum":1,"maximum":365,"default":14},{"name":"tax_behavior","required":false,"type":"string","enum":["exclusive","inclusive","unspecified"],"default":"exclusive"},{"name":"tax_code","required":false,"type":"string","maxLength":40},{"name":"automatic_tax","required":false,"type":"boolean","description":"Default: on when available for the billing account."},{"name":"notify_customer","required":false,"type":"boolean","description":"Default: on for invoice/payment_link, off for charge_saved_method."},{"name":"internal_note","required":false,"type":"string","description":"Private note, never shown to the customer.","maxLength":1000},{"name":"workspace_id","required":false,"type":"string","description":"Disambiguate when the customer has multiple workspaces in your scope.","format":"uuid"},{"name":"payment_method_id","required":false,"type":"string","description":"charge_saved_method only: a specific saved payment method id."},{"name":"idempotency_key","required":false,"type":"string","description":"Resubmitting the same key returns the existing payment instead of charging twice.","maxLength":200},{"name":"confirm_large_amount","required":false,"type":"boolean","description":"Required (true) when amount_minor * quantity is unusually large."}]}},
  {"id":"createPlatformUserToken","method":"POST","path":"/platform/users/{user_id}/token","summary":"Create a platform user token","description":"Mints a `fam_...` API key for this customer without needing their password — useful for a dashboard, an onboarding email, or an automated workflow acting on their behalf. The key is returned in full exactly once; store it immediately, it cannot be retrieved again. `scopes` defaults to full access for the target customer (this key belongs to a different principal than your own credential, so it is not limited to your own credential's scopes). The key follows the platform's live-membership rule: if the customer ever leaves this workspace, the key stops working automatically. **Required scope:** `platform:write`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"user_id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":false,"fields":[{"name":"name","required":false,"type":"string","maxLength":100,"default":"Platform access token"},{"name":"scopes","required":false,"type":"array","description":"Subset of the canonical API scopes to grant this token. Omitted or empty = full access for this customer — this is a completely different principal than your own operator credential, so it is NOT limited to your own credential's scopes.","items":{"type":"string"}},{"name":"expires_in_days","required":false,"type":"integer","description":"Omitted = the token never expires.","minimum":1,"maximum":365},{"name":"workspace_id","required":false,"type":"string","description":"Pick a specific workspace when the customer has several in your scope; defaults to the one they own.","format":"uuid"}]}},
  {"id":"createQaRun","method":"POST","path":"/qa/runs","summary":"Create QA run","description":"Start a cohort QA analysis for a pack and date range. Consumes credits. **Required scope:** `calls:write`.","tag":"QA","parameters":[],"body":{"required":true,"fields":[{"name":"pack","required":true,"type":"string","enum":["full","language_hallucinations","resolution_sentiment","performance_trends"]},{"name":"name","required":false,"type":"string","description":"Optional cohort display name","maxLength":120},{"name":"from_at","required":true,"type":"string","format":"date-time"},{"name":"to_at","required":true,"type":"string","format":"date-time"},{"name":"assistant_ids","required":false,"type":"array","items":{"type":"string","format":"uuid"}},{"name":"filters","required":false,"type":"object"},{"name":"resolution_criteria","required":false,"type":"string","description":"What counts as a successful resolution for this cohort","maxLength":4000}]}},
  {"id":"createResellerTaxRegistration","method":"POST","path":"/reseller/tax/registrations","summary":"Create reseller tax registration","description":"Requires an active Whitelabel payment account, API Access and workspace owner/admin authority. Requires billing:write. Changes affect customer tax calculations. Act only on explicit instructions from the business owner. Registrations describe where to collect tax and do not register a business with tax authorities. Registrations cannot be deleted; end collection with an expiry time.","tag":"White Label","parameters":[],"body":{"required":true,"fields":[{"name":"country","required":true,"type":"string"},{"name":"registration_options","required":true,"type":"object","description":"Options for the selected jurisdiction, without a wrapping country key. For DE use {\"type\":\"standard\"}; for US use {\"type\":\"state_sales_tax\",\"state\":\"CA\"}. Must match the tax registration already held by the business."},{"name":"active_from","required":true,"type":"json"},{"name":"expires_at","required":false,"type":"integer","minimum":1},{"name":"request_key","required":true,"type":"string","description":"Unique per creation request. Reuse only for an identical retry to prevent duplicates.","minLength":8,"maxLength":128}]}},
  {"id":"createRoutine","method":"POST","path":"/routines","summary":"Create a mission","description":"Creates a Milian Mission. The workspace's included and purchased mission capacity is enforced. **Required scope:** `routines:write` (keys without scope restrictions have full access).","tag":"Milian Missions","parameters":[],"body":{"required":true,"fields":[{"name":"id","required":false,"type":"string","format":"uuid"},{"name":"name","required":true,"type":"string"},{"name":"prompt","required":true,"type":"string","description":"The instruction the mission runs unattended each time it fires."},{"name":"schedule_type","required":true,"type":"string","description":"manual = only runs via POST /routines/{id}/run. hourly/daily/weekdays/weekly/custom fire on the given schedule.","enum":["manual","hourly","daily","weekdays","weekly","custom"]},{"name":"schedule_minute","required":false,"type":"integer","description":"hourly only — minute of the hour to fire on (0-59), default 0.","minimum":0,"maximum":59},{"name":"schedule_time","required":false,"type":"string","description":"daily/weekdays/weekly only — 24h wall-clock time \"HH:MM\", default \"09:00\"."},{"name":"schedule_weekday","required":false,"type":"integer","description":"weekly only — day of week, 0=Sunday … 6=Saturday.","minimum":0,"maximum":6},{"name":"cron_expression","required":false,"type":"string","description":"custom only — standard 5-field cron (minute hour day-of-month month day-of-week). Occurrences must be at least 10 minutes apart."},{"name":"timezone","required":false,"type":"string","description":"IANA timezone the schedule fields above are evaluated in, e.g. `Europe/Berlin`. Default `UTC`."},{"name":"enabled","required":false,"type":"boolean"},{"name":"required_toolkits","required":false,"type":"array","description":"Connected-app toolkit slugs this mission's prompt depends on, e.g. [\"slack\",\"gmail\"]. The mission refuses to be created while one of these is not connected.","items":{"type":"string"}}]}},
  {"id":"createRoutineVersionDraft","method":"POST","path":"/routines/{id}/versions","summary":"Save a mission draft","description":"Creates or replaces the editable draft while the active version keeps running. **Required scope:** `routines:write`.","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}],"body":{"required":true,"fields":[{"name":"spec","required":true,"type":"object"}]}},
  {"id":"createSegment","method":"POST","path":"/segments","summary":"Create a segment","description":"Save a lead filter as a reusable segment. Its matches are resolved live (dynamic, not a snapshot) — see `GET /segments/{id}/leads` and `POST /campaigns/{id}/leads/assign`. **Required scope:** `segments:write` (the legacy `calls:write` scope is also accepted; keys without scope restrictions have full access).","tag":"Segments","parameters":[],"body":{"required":true}},
  {"id":"createSipTrunk","method":"POST","path":"/sip-trunks","summary":"Create a SIP trunk","description":"Registers your own SIP provider for inbound and outbound calling. Supports DID or Extension (`trunk_kind`), calling-number format, transport, and advanced options (secure trunking, headers, codecs). Use this to bring your own numbers instead of buying from the marketplace. See [BYO SIP trunk](/telephony/sip-trunks). **Required scope:** `sip_trunks:write` (keys without scope restrictions have full access).","tag":"SIP Trunks","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string"},{"name":"sip_address","required":true,"type":"string","description":"Provider termination host, e.g. `sip.provider.com` (no `sip:` prefix, no port)."},{"name":"numbers","required":true,"type":"array","description":"Exactly one inbound match number is required. DID: E.164. Extension: E.164 or national digits without country code.","items":{"type":"string"}},{"name":"trunk_kind","required":false,"type":"string","enum":["did","extension"],"default":"did"},{"name":"provider","required":false,"type":"string","enum":["twilio","custom"],"default":"custom"},{"name":"auth_username","required":false,"type":"string"},{"name":"auth_password","required":false,"type":"string","description":"Stored server-side; never returned by the API."},{"name":"inbound_auth_username","required":false,"type":"string"},{"name":"inbound_auth_password","required":false,"type":"string","description":"Stored server-side; never returned by the API."},{"name":"credential_mode","required":false,"type":"string","enum":["shared","separate"],"default":"shared"},{"name":"outbound_auth_mode","required":false,"type":"string","enum":["credentials","none"],"default":"credentials"},{"name":"transport","required":false,"type":"string","enum":["auto","udp","tcp","tls"],"default":"auto"},{"name":"calling_number_format","required":false,"type":"string","enum":["e164_plus","e164_no_plus","national"],"default":"e164_plus"},{"name":"destination_country","required":false,"type":"string","description":"ISO-3166 alpha-2 for outbound region pinning, or empty for automatic."},{"name":"secure_trunking","required":false,"type":"boolean","description":"TLS signaling + SRTP media.","default":false},{"name":"media_encryption","required":false,"type":"string","enum":["allow","require","disable"]},{"name":"outbound_headers","required":false,"type":"object","description":"Custom outbound INVITE headers (max 10)."},{"name":"inbound_headers","required":false,"type":"object"},{"name":"headers_to_attributes","required":false,"type":"object"},{"name":"outbound_headers_to_attributes","required":false,"type":"object"},{"name":"include_headers","required":false,"type":"string","enum":["none","x","all"],"default":"none"},{"name":"media_codecs","required":false,"type":"array","items":{"type":"string","enum":["PCMU","PCMA","G722","AMR-WB"]}},{"name":"only_listed_codecs","required":false,"type":"boolean","default":false},{"name":"media_timeout_sec","required":false,"type":"integer","minimum":1,"maximum":3600},{"name":"ringing_timeout_sec","required":false,"type":"integer","minimum":5,"maximum":600},{"name":"metadata","required":false,"type":"object","description":"May include inbound auth mode (`inbound_auth`, `allowed_addresses`) and region hints."},{"name":"outbound_from_user_mode","required":false,"type":"string","description":"Outbound From user for your own SIP trunk. Phone number preserves the existing behavior. SIP username uses the authentication username and keeps the primary DID unchanged. Not available on imported carrier connections.","enum":["phone_number","auth_username"],"default":"phone_number"},{"name":"outbound_caller_id_header","required":false,"type":"string","description":"Used with SIP username identity. The primary international DID is sent in the From display name and optionally the selected identity header. Match the carrier caller ID settings.","enum":["from_display","p_asserted_identity","p_preferred_identity"],"default":"from_display"}]}},
  {"id":"createSupportRequest","method":"POST","path":"/support/requests","summary":"Create a support request","description":"Submits a support request for the authenticated root workspace, including a white-label reseller workspace. Reseller-customer workspaces are not eligible. Reusing the same client request ID with the same content returns the original reference. Workspaces with Priority Support (included in the plan or booked as add-on) are routed to priority support automatically; `priority_support` in the response confirms it. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"client_request_id","required":true,"type":"string","description":"Stable UUID generated by the client. Reuse it only when retrying the same request.","format":"uuid"},{"name":"subject","required":true,"type":"string","minLength":1,"maxLength":160},{"name":"message","required":true,"type":"string","minLength":1,"maxLength":8000}]}},
  {"id":"createTool","method":"POST","path":"/tools","summary":"Create a tool","description":"Create one centrally managed API, MCP, or built-in tool. Requires an admin-level credential because configs may contain secrets. Assign it via `PUT /assistants/{id}/tools`. **Required scope:** `assistants:write`.","tag":"Tools","parameters":[],"body":{"required":true}},
  {"id":"createTranslationSession","method":"POST","path":"/translation-sessions","summary":"Create a translation room","description":"Prepare a room for an assistant using Translate. The Translate Agent mode must be included in the workspace's current plan. The credential user is speaker 1; speaker 2 joins without an account. Creating a room does not place calls. Requires calls:write and a credential belonging to the room host. Workspace roles, credits, assistant and calling limits apply.","tag":"Translation","parameters":[],"body":{"required":true,"fields":[{"name":"assistant_id","required":true,"type":"string","format":"uuid"}]}},
  {"id":"createVoiceCloneUpload","method":"POST","path":"/voices/clone/uploads","summary":"Prepare voice clone uploads","description":"Creates an opaque job and short-lived upload destinations for one or more audio samples (at most 3; call GET /voices/clone/capability first and check `sample_constraints.max_files` for the number currently accepted — it can be lower). For each returned URL, send a PUT request with `multipart/form-data`: include `cacheControl=3600`, put the audio Blob in an unnamed file field, and set `x-upsert: false`. Then submit the job. **Required scope:** `voices:write` or `assistants:write`. A user-bound credential is required.","tag":"Voices","parameters":[],"body":{"required":true,"fields":[{"name":"files","required":true,"type":"array","items":{"type":"object"}}]}},
  {"id":"createWidgetConnector","method":"POST","path":"/widget-connectors","summary":"Create web widget","description":"**Required scope:** `assistants:write`. Requires the Web widget feature in the workspace plan. `allowed_origins` is optional (defaults to `[]`); an empty allowlist blocks third-party hosts until origins are added. If `theme.logo_url` is omitted and the selected assistant has a portrait, that portrait becomes the widget's initial header logo; it can be replaced or removed later. Phone verification requires explicit acceptance of the current verification SMS credit price. Previously issued browser permissions expire after at most 7 days and are revoked when this widget configuration changes.","tag":"Widgets","parameters":[],"body":{"required":true,"fields":[{"name":"assistant_id","required":true,"type":"string","format":"uuid"},{"name":"name","required":true,"type":"string"},{"name":"allowed_origins","required":false,"type":"array","description":"Optional site origins that may embed the widget (e.g. https://example.com). Empty or omitted blocks third-party hosts.","items":{"type":"string"}},{"name":"voice_enabled","required":false,"type":"boolean"},{"name":"chat_enabled","required":false,"type":"boolean"},{"name":"is_active","required":false,"type":"boolean"},{"name":"theme","required":false,"type":"object","description":"Widget appearance. launcher_label_i18n is derived from launcher_label and is read-only — never persist client-supplied maps."},{"name":"phone_verification_enabled","required":false,"type":"boolean","description":"Require the selected email or SMS verification before chat or voice. Available in root workspaces, including a reseller’s own workspace; unavailable to reseller customer workspaces.","default":false},{"name":"phone_verification_accepted_credits","required":false,"type":"number","description":"Explicitly accept the current per-SMS price from the widget list response. Currently 80 credits per accepted send, including resends; code checks and valid remembered visits are free."},{"name":"verification_method","required":false,"type":"string","description":"Verify visitors by SMS or email. Email uses the platform sender without additional credits.","enum":["sms","email"],"default":"sms"}]}},
  {"id":"createWorkspace","method":"POST","path":"/workspaces","summary":"Create a workspace","description":"Create an additional workspace owned by the calling credential's user. Requires a user-owned API key or OAuth token — a service-account key IS a single workspace and cannot own more (`403`). Limited by the plan's workspace allowance (unlimited, or unavailable when the plan includes none) plus any Extra workspaces add-on, counted across every workspace this user already owns in this same brand. **Required scope:** `settings:write`.","tag":"Workspaces","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","description":"Plain-text display name. Must not contain < > { } [ ] ` \\ or line breaks; such names are rejected with 400.","minLength":1,"maxLength":80}]}},
  {"id":"createWorkspaceApiKey","method":"POST","path":"/workspaces/{workspace_id}/api-keys","summary":"Create an API key for a workspace","description":"Mints a service-account API key bound to the selected workspace. The calling credential must be user-owned, carry `settings:write`, and its user must currently be an owner or admin in the target workspace. The target must be visible within the calling credential's brand; no white-label entitlement is required. Requested scopes can only stay equal to or become narrower than the calling credential's scopes. A child key cannot outlive a finite calling credential. The target may still be awaiting plan activation, but a suspended target is rejected. The plaintext key is returned exactly once with `Cache-Control: no-store`; do not retry automatically because each successful request creates a new key.","tag":"Workspaces","parameters":[{"name":"workspace_id","in":"path","required":true,"type":"string","format":"uuid","description":"Target workspace UUID from `GET /workspaces`."}],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","maxLength":100},{"name":"scopes","required":false,"type":"array","description":"Must be a subset of the calling credential's own scopes — a key can never mint another key with broader access than itself. Omitted defaults to the calling credential's own scopes (or, if the credential itself has unrestricted access, every scope).","items":{"type":"string"}},{"name":"expires_in_days","required":false,"type":"integer","description":"Requested lifetime. Omitted inherits a finite calling credential's expiry, or means no expiry when the caller itself does not expire.","minimum":1,"maximum":365}]}},
  {"id":"deleteAssistant","method":"DELETE","path":"/assistants/{id}","summary":"Delete an assistant","description":"Deletes the assistant permanently. Phone numbers pointing at it are unassigned. Not possible while one of its calls is live: wait until the call has ended, then retry. Open translation rooms that nobody has joined are ended. **Required scope:** `assistants:write` (keys without scope restrictions have full access).","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}]},
  {"id":"deleteAssistantAvatar","method":"DELETE","path":"/assistants/{id}/avatar","summary":"Remove assistant picture","description":"Deletes the custom picture and clears `avatar_url`. The UI falls back to the default mesh orb. No-op if none is set.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","description":"Assistant id."}]},
  {"id":"deleteAssistantGreetingAudio","method":"DELETE","path":"/assistants/{id}/greeting-audio","summary":"Remove audio first message","description":"Deletes the stored audio greeting and clears `greeting_audio_path`. The assistant falls back to the `first_message` text / TTS. No-op if none is set.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","description":"Assistant id."}]},
  {"id":"deleteAssistantTest","method":"DELETE","path":"/assistants/{id}/tests/{testId}","summary":"Delete simulation test","description":"**Required scope:** `assistants:write`.","tag":"Simulations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"testId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteAssistantVersion","method":"DELETE","path":"/assistants/{id}/versions/{versionId}","summary":"Delete assistant version","description":"**Required scope:** `assistants:write`.","tag":"Versions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"versionId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteAutomation","method":"DELETE","path":"/automations/{id}","summary":"Delete automation","description":"Delete automation","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteAutomationConnection","method":"DELETE","path":"/automations/connections/{id}","summary":"Delete automation connection","description":"Delete automation connection","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteBookingEventType","method":"DELETE","path":"/booking-event-types/{id}","summary":"Delete a booking event type","description":"Permanently delete an event type. **All its bookings are deleted with it** (ON DELETE CASCADE).\n\n**Required scope:** `bookings:write` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Event type ID"}]},
  {"id":"deleteCallerId","method":"DELETE","path":"/caller-ids/{id}","summary":"Delete caller ID","description":"**Required scope:** `phone_numbers:write` or `calls:write`.","tag":"Caller IDs","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteCampaign","method":"DELETE","path":"/campaigns/{id}","summary":"Delete a campaign","description":"Deletes the campaign. Its leads are kept (their campaign reference is cleared). **Required scope:** `campaigns:write` (keys without scope restrictions have full access).","tag":"Campaigns","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."}]},
  {"id":"deleteCarrierConnection","method":"DELETE","path":"/carrier-connections/{id}","summary":"Disconnect a carrier connection","description":"Safely detaches imported numbers, removes their platform trunks, deletes provider resources, and forgets credentials. **Required scope:** `sip_trunks:write`.","tag":"Carrier Connections","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Carrier connection ID."}]},
  {"id":"deleteCrawlSource","method":"DELETE","path":"/knowledge-bases/{id}/crawl-sources/{sourceId}","summary":"Delete a crawl source","description":"Delete a website crawl source. Documents already created by past crawls are kept; only future syncs stop. **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"sourceId","in":"path","required":true,"type":"string","format":"uuid","description":"Crawl source ID."}]},
  {"id":"deleteCrmSync","method":"DELETE","path":"/crm-syncs/{id}","summary":"Delete CRM sync","description":"Delete the sync configuration and memberships. Imported Audience contacts are kept. Requires `automations:write` or `calls:write`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"CRM sync ID."}]},
  {"id":"deleteDashboard","method":"DELETE","path":"/dashboards/{id}","summary":"Delete a custom dashboard","description":"Deletes the dashboard. Reusable widget records are retained. **Required scope:** `dashboards:write` or `calls:write`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."}]},
  {"id":"deleteDriveSource","method":"DELETE","path":"/knowledge-bases/{id}/drive-sources/{sourceId}","summary":"Delete a cloud drive source","description":"Delete a cloud drive sync source. Documents already created by past syncs are kept by default; only future syncs stop. Pass `?purge=true` to also remove the documents this source already created. **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"sourceId","in":"path","required":true,"type":"string","format":"uuid","description":"Drive source ID."},{"name":"purge","in":"query","required":false,"type":"boolean","default":false,"description":"Also delete the kb_documents already synced from this source."}]},
  {"id":"deleteEmailAddress","method":"DELETE","path":"/email/addresses/{id}","summary":"Delete an email address","description":"**Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteEmailDomain","method":"DELETE","path":"/email/domains/{id}","summary":"Disconnect an email domain","description":"Disconnects a domain; its addresses are removed with it. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteIntegration","method":"DELETE","path":"/integrations/{id}","summary":"Delete a calendar integration","description":"Permanently delete a calendar integration. Assistant assignments are removed automatically. Requires a user-owned credential of a workspace owner or admin; workspace service-account credentials get `403`.\n\n**Required scope:** `integrations:write` (keys without scope restrictions have full access).","tag":"Integrations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Integration ID"}]},
  {"id":"deleteKnowledgeBase","method":"DELETE","path":"/knowledge-bases/{id}","summary":"Delete a knowledge base","description":"Deletes the knowledge base including all its documents and chunks. **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}]},
  {"id":"deleteKnowledgeBaseDocument","method":"DELETE","path":"/knowledge-bases/{id}/documents/{docId}","summary":"Delete a document","description":"Deletes one knowledge-base document together with its indexed chunks and its stored original file. Assistants stop using its content right away. A page that came from an Auto Refresh website is imported again on the next refresh unless you add it to that source's exclude paths; a file from a cloud drive comes back on the next sync unless you remove it from the synced folder. Unknown, foreign or malformed IDs return 404. **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"docId","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge document ID, as returned by `GET /knowledge-bases/{id}/documents`."}]},
  {"id":"deleteKnowledgeBaseDocuments","method":"POST","path":"/knowledge-bases/{id}/documents/delete","summary":"Delete documents in bulk","description":"Deletes up to 200 documents of one knowledge base in a single request, together with their indexed chunks and stored original files. IDs that do not exist in this knowledge base (or were already deleted) are returned in `not_found_ids` instead of failing the request, so a retry is safe. Pages that came from an Auto Refresh website are imported again on the next refresh unless you add them to that source's exclude paths; files from a cloud drive come back on the next sync unless you remove them from the synced folder. An unknown knowledge base returns 404. **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}],"body":{"required":true,"fields":[{"name":"document_ids","required":true,"type":"array","description":"IDs of the documents to delete (1–200), as returned by `GET /knowledge-bases/{id}/documents`. Duplicates are ignored.","items":{"type":"string","format":"uuid"}}]}},
  {"id":"deleteKnowledgeBaseFaq","method":"DELETE","path":"/knowledge-bases/{id}/faqs/{faqId}","summary":"Delete an FAQ entry","description":"Delete an FAQ entry","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"faqId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteLead","method":"DELETE","path":"/campaigns/{id}/leads/{leadId}","summary":"Remove a lead from a campaign","description":"Removes the lead from campaign execution while retaining the Audience contact, calls, and completed campaign history. This operation never permanently deletes the contact. **Required scope:** `leads:write` (keys without scope restrictions have full access).","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."},{"name":"leadId","in":"path","required":true,"type":"string","format":"uuid","description":"Lead ID."}]},
  {"id":"deleteLoopNumberRoute","method":"DELETE","path":"/loop/number-routes/{id}","summary":"Delete a Loop phone number route","description":"Removes the Loop destination from an eligible purchased phone number. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}]},
  {"id":"deleteLoopQueue","method":"DELETE","path":"/loop/queues/{id}","summary":"Delete a Loop call queue","description":"Deletes a call queue. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}]},
  {"id":"deleteLoopRingGroup","method":"DELETE","path":"/loop/ring-groups/{id}","summary":"Delete a Loop ring group","description":"Deletes a ring group. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}]},
  {"id":"deleteLoopRoutingRule","method":"DELETE","path":"/loop/routing-rules/{id}","summary":"Delete a Loop routing rule","description":"Deletes a routing rule. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}]},
  {"id":"deleteMessagingConnector","method":"DELETE","path":"/messaging-connectors/{id}","summary":"Delete messaging connector","description":"**Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deletePasskey","method":"DELETE","path":"/settings/passkeys","summary":"Delete a passkey","description":"Removes one of the user's passkeys, for example for a lost device. The user can no longer sign in with it; other sign-in methods keep working. Only available on the main platform and with a user-owned API key or OAuth token. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"passkey_id","required":true,"type":"string","description":"Passkey id returned by the list endpoint.","format":"uuid"}]}},
  {"id":"deletePhoneNumberVerification","method":"DELETE","path":"/phone-numbers/verifications/{id}","summary":"Delete regulatory number verification","description":"Delete a draft or failed verification case and its archived documents. Cases already submitted for review are retained. **Required scope:** `phone_numbers:write`.","tag":"Phone Numbers","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteRoutine","method":"DELETE","path":"/routines/{id}","summary":"Delete a mission","description":"Permanently deletes a mission; it stops running immediately. Past runs already on record are unaffected. **Required scope:** `routines:write` (keys without scope restrictions have full access).","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}]},
  {"id":"deleteSegment","method":"DELETE","path":"/segments/{id}","summary":"Delete a segment","description":"Delete a segment. The leads it currently matches are not affected. **Required scope:** `segments:write` (the legacy `calls:write` scope is also accepted; keys without scope restrictions have full access).","tag":"Segments","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Segment ID."}]},
  {"id":"deleteSipTrunk","method":"DELETE","path":"/sip-trunks/{id}","summary":"Delete a SIP trunk","description":"Deletes a customer-owned SIP trunk and its associated voice routing. Managed marketplace and verified caller-ID infrastructure is not accessible through this endpoint. **Required scope:** `sip_trunks:write` (keys without scope restrictions have full access).","tag":"SIP Trunks","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"SIP trunk ID."}]},
  {"id":"deleteVoiceClone","method":"DELETE","path":"/voices/clone/{cloneId}","summary":"Delete cloned voice","description":"Requests durable deletion of a workspace-owned cloned voice. Remove the voice from assistants before deletion. **Required scope:** `voices:write` or `assistants:write`. A user-bound credential is required.","tag":"Voices","parameters":[{"name":"cloneId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteWhatsAppConnectorAsset","method":"DELETE","path":"/whatsapp/connectors/{id}/assets","summary":"Remove WhatsApp sender logo / banner","description":"**Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"kind","in":"query","required":true,"type":"string","enum":["logo","banner"]}]},
  {"id":"deleteWidgetConnector","method":"DELETE","path":"/widget-connectors/{id}","summary":"Delete web widget","description":"**Required scope:** `assistants:write`.","tag":"Widgets","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"deleteWidgetConnectorLogo","method":"DELETE","path":"/widget-connectors/{id}/logo","summary":"Remove widget header logo","description":"**Required scope:** `assistants:write`.","tag":"Widgets","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"disconnectAssistantAutomation","method":"DELETE","path":"/assistants/{id}/automations/{automationId}","summary":"Disconnect an assistant automation","description":"Pause and disconnect an assistant-callable automation. Requires both `assistants:write` and `automations:write`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."},{"name":"automationId","in":"path","required":true,"type":"string","format":"uuid","description":"Automation ID."}]},
  {"id":"discoverCrawlSourcePaths","method":"POST","path":"/knowledge-bases/{id}/crawl-sources/discover","summary":"Discover website crawl paths","description":"Inspect a website before creating or updating a crawl source. The preview uses the same-host, SSRF, `robots.txt` and sitemap rules as the crawler, but creates no source or documents, performs no indexing and spends no credits. **Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}],"body":{"required":true,"fields":[{"name":"root_url","required":true,"type":"string","description":"Website root URL to inspect (http/https).","format":"uri"},{"name":"max_pages","required":false,"type":"integer","description":"Maximum discovered pages returned.","minimum":1,"maximum":500,"default":50}]}},
  {"id":"discoverCrmSyncMetadata","method":"POST","path":"/crm-syncs/discover","summary":"Discover CRM objects and fields","description":"Discover importable objects for a connection. Include `object_type` to receive fields and list/view/filter sources. Set `include_preview` with a field mapping to receive up to five read-only mapped sample records after expression evaluation and phone/email normalization. Credentials are decrypted only inside the service and never returned. Requires `automations:read` or `calls:read`.","tag":"Automations","parameters":[],"body":{"required":true,"fields":[{"name":"connection_id","required":true,"type":"string","format":"uuid"},{"name":"object_type","required":false,"type":"string"},{"name":"selection","required":false,"type":"object","description":"Provider-neutral source selection. `sourceId` limits the source; `default_phone_country` is an optional ISO-2 fallback for national phone numbers."},{"name":"field_mapping","required":false,"type":"object","description":"Source key or composed source expression to destination. Combined values use non-evaluated `{{field}}` tokens plus optional literal text, for example `{{salutation}} {{firstName}} {{lastName}}`. Destinations include channel identities such as `channel.telegram.username` or `channel.whatsapp.user_id`."},{"name":"include_preview","required":false,"type":"boolean","default":false},{"name":"preview_limit","required":false,"type":"integer","minimum":1,"maximum":5,"default":3}]}},
  {"id":"discoverTool","method":"POST","path":"/tools/discover","summary":"Discover MCP tool functions","description":"Discover functions and input schemas offered by an MCP server. Does not execute remote functions. Requires an admin-level credential and assistants:write. OAuth consent must be completed in the browser.","tag":"Tools","parameters":[],"body":{"required":true,"fields":[{"name":"tool_id","required":false,"type":"string","description":"Existing tool to reuse masked secrets.","format":"uuid"},{"name":"config","required":true,"type":"object","description":"HTTP or MCP configuration, as accepted when creating this tool type."}]}},
  {"id":"dismissInboxLabel","method":"POST","path":"/history/inbox-labels/{id}/dismiss","summary":"Dismiss a message label","description":"Requires calls:write and workspace write permission. Repeating the request is safe. Does not remove the message, alter replies, or change the connected mailbox.","tag":"History","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"endTranslationSession","method":"POST","path":"/translation-sessions/{id}/end","summary":"End a translation room","description":"Stop the entire shared session and both telephone connections. The status can remain ending while connections close; repeat safely. Requires calls:write and a credential belonging to the room host. Workspace roles, credits, assistant and calling limits apply.","tag":"Translation","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[]}},
  {"id":"eraseCustomerMemory","method":"DELETE","path":"/contacts/{id}/memory","summary":"Erase customer memory","description":"Permanently deletes all stored summaries, preferences, and remembered variables for the contact. A content-free deletion audit remains; the contact and exact channel identities remain. **Required scope:** `leads:write` or `calls:write`.","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Audience contact ID."}]},
  {"id":"executeMeetergoCalendarAction","method":"POST","path":"/integrations/meetergo/action","summary":"Check availability or book with meetergo","description":"Uses an active meetergo integration in the current workspace. Availability requires integrations:read; booking requires integrations:write, enabled booking permission and confirmation from the attendee. Availability works with a workspace service-account credential or a user-owned owner/admin credential; booking requires a user-owned owner/admin credential. Check availability first and book an exact returned start. The provider is checked again before writing. A pending_confirmation result is not a confirmed booking. Never automatically retry a booking with an unknown outcome.","tag":"Integrations","parameters":[],"body":{"required":true}},
  {"id":"getAiInferenceSettings","method":"GET","path":"/settings/ai-inference","summary":"Get AI inference settings","description":"Reads the workspace AI inference region (`global`, `eu`, or `us`). EU also activates after-save AI-disclosure review for assistants. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"getApiKey","method":"GET","path":"/api-keys/{id}","summary":"Get an API key","description":"Metadata for a single API key (never the secret). 404 if it belongs to another workspace. **Required scope:** `settings:read`.","tag":"API Keys","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getAssistant","method":"GET","path":"/assistants/{id}","summary":"Get an assistant","description":"**Required scope:** `assistants:read` (keys without scope restrictions have full access).","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}]},
  {"id":"getAssistantAnnouncementAudio","method":"GET","path":"/assistants/{id}/announcements/{assetId}/audio","summary":"Play saved announcement audio","description":"Return the current private WAV audio with the same Bearer authentication as other API requests. Audio is not generated by this endpoint. A replaced or no longer available announcement cannot be played. **Required scope:** `assistants:read`.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."},{"name":"assetId","in":"path","required":true,"type":"string","format":"uuid","description":"Audio identity from the current preview link."}],"binary":true},
  {"id":"getAssistantAnnouncements","method":"GET","path":"/assistants/{id}/announcements","summary":"Get saved announcement audio","description":"Read preparation status and authenticated preview links for the saved greeting, consent and farewell. Reading does not start generation. Changed text, voice or effective speech settings revoke older previews. With secondary languages configured, end-call farewell text guides a live message in the caller's current supported language; these farewells are skipped for saved audio. **Required scope:** `assistants:read`.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}]},
  {"id":"getAssistantComplianceReview","method":"GET","path":"/assistants/{id}/compliance-review","summary":"Get assistant compliance review","description":"Returns the customer-visible automated compliance status, score, flags, reason, and manual-review state. Internal model, workflow, token, and prompt-snapshot fields are omitted. **Required scope:** `assistants:read`.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}]},
  {"id":"getAssistantIntegrations","method":"GET","path":"/assistants/{id}/integrations","summary":"List assistant integrations","description":"List the calendar integrations assigned to an assistant. Each assignment adds `check_availability` and `book_appointment` (Calendly link mode: `send_booking_link`) plus provider-supported appointment lookup, cancellation, and rescheduling tools.\n\n**Required scope:** `integrations:read` or `assistants:read` (keys without scope restrictions have full access).","tag":"Integrations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID"}]},
  {"id":"getAssistantTools","method":"GET","path":"/assistants/{id}/tools","summary":"List assigned tools","description":"List assigned central tools. `meta.revision` is required for an atomic replacement. **Required scope:** `assistants:read`.","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}]},
  {"id":"getAssistantVariables","method":"GET","path":"/assistants/{id}/variables","summary":"Get assistant variables","description":"Returns the custom variable definitions of an assistant plus the inbound variable webhook URL. The webhook secret is never returned. **Required scope:** `assistants:read`.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}]},
  {"id":"getAssistantVersion","method":"GET","path":"/assistants/{id}/versions/{versionId}","summary":"Get assistant version","description":"Includes full snapshot. **Required scope:** `assistants:read`.","tag":"Versions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"versionId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getAutomation","method":"GET","path":"/automations/{id}","summary":"Get automation","description":"Get one automation and recent runs.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getAutomationConnection","method":"GET","path":"/automations/connections/{id}","summary":"Get automation connection","description":"Load one connection with secrets masked. **Required scope:** `automations:read` or `calls:read`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getAutomationTriggerTestData","method":"POST","path":"/automations/trigger-test-data","summary":"Preview or capture conversation trigger data","description":"Read-only Conversation started testing. Requires automations:read or calls:read and automation access. Samples use the selected channel, assistant variables and widget pre-chat form. Listen without since to arm using server time; poll with the returned since timestamp and source_id. Does not activate or execute automations. Real conversations can still execute active automations and use credits.","tag":"Automations","parameters":[],"body":{"required":true,"fields":[{"name":"trigger","required":true,"type":"object"},{"name":"mode","required":true,"type":"string","enum":["sample","listen"]},{"name":"source_id","required":false,"type":"string","description":"Test source from the response sources list. Required when multiple connections match.","format":"uuid"},{"name":"since","required":false,"type":"string","description":"Server timestamp from the arming response. Maximum lookback: 10 minutes.","format":"date-time"}]}},
  {"id":"getBalance","method":"GET","path":"/balance","summary":"Get balance","description":"Minutes and credits balance of the API key's workspace plus a summary of its active plan. **Required scope:** `billing:read` (keys without scope restrictions have full access).","tag":"Billing","parameters":[]},
  {"id":"getBooking","method":"GET","path":"/bookings/{id}","summary":"Get a booking","description":"Read a single booking.\n\n**Required scope:** `bookings:read` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Booking ID"}]},
  {"id":"getBookingEmailTemplates","method":"GET","path":"/booking-email-templates","summary":"Get standard booking email templates","description":"Read standard text for all seven guest and host messages, plus supported template variables. Requires bookings:read. Standard messages follow recipient language; custom text is sent as written. Optional location, question answers and calendar attachment notes are omitted from standard messages when not applicable.","tag":"Bookings","parameters":[{"name":"locale","in":"query","required":false,"type":"string","enum":["en","de","fr","es"],"default":"en","description":"Language of the standard templates."}]},
  {"id":"getBookingEventType","method":"GET","path":"/booking-event-types/{id}","summary":"Get a booking event type","description":"Read a single event type.\n\n**Required scope:** `bookings:read` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Event type ID"}]},
  {"id":"getCall","method":"GET","path":"/calls/{id}","summary":"Get a call","description":"Call details including the transcript, the AI summary, provider-neutral failure guidance, the chronological event log, and a signed `recording_url` (valid 1 hour) if a recording exists. Failed transfer events expose the same safe failure shape without raw SIP or SDK diagnostics. **Required scope:** `calls:read` (keys without scope restrictions have full access).\n\nRemoved conversations are excluded. Their detail IDs return not found.\n\nIncludes measured call insights. Unavailable measurements are null. Transcript recognition confidence is a score, not a correctness guarantee. Recording playback is limited to available consent-permitted audio.","tag":"Calls","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Call ID."}]},
  {"id":"getCallRecording","method":"GET","path":"/calls/{id}/recording","summary":"Get a call recording URL","description":"Returns a time-limited signed download URL for the call recording. 404 if the call does not exist or has no recording. **Required scope:** `calls:read` (keys without scope restrictions have full access).\n\nRemoved conversations are excluded. Their detail IDs return not found.","tag":"Calls","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Call ID."},{"name":"expires_in","in":"query","required":false,"type":"integer","minimum":60,"maximum":86400,"default":3600,"description":"URL validity in seconds (60–86400)."}]},
  {"id":"getCampaign","method":"GET","path":"/campaigns/{id}","summary":"Get a campaign","description":"Campaign details including `total_leads`. **Required scope:** `campaigns:read` (keys without scope restrictions have full access).","tag":"Campaigns","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."}]},
  {"id":"getCampaignStats","method":"GET","path":"/campaigns/{id}/stats","summary":"Get campaign stats","description":"Progress and performance aggregates for a campaign: total and completed leads, calls made, total call duration, and delivery attempts by outcome. **Required scope:** `campaigns:read` (the legacy `calls:read` scope is also accepted; keys without scope restrictions have full access).","tag":"Campaigns","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."}]},
  {"id":"getCarrierConnection","method":"GET","path":"/carrier-connections/{id}","summary":"Get a carrier connection","description":"**Required scope:** `sip_trunks:read`.","tag":"Carrier Connections","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Carrier connection ID."}]},
  {"id":"getConsentComplianceSettings","method":"GET","path":"/settings/consent-compliance","summary":"Get consent compliance mode","description":"Reads how marketing opt-outs are enforced in the workspace. `universal` blocks every linked channel after any opt-out; `per_channel` blocks only the originating channel. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"getCrawlSource","method":"GET","path":"/knowledge-bases/{id}/crawl-sources/{sourceId}","summary":"Get a crawl source","description":"Fetch a single website crawl source, including its custom display name, last run status, `pages_crawled`, `credits_spent` and `last_error`. **Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"sourceId","in":"path","required":true,"type":"string","format":"uuid","description":"Crawl source ID."}]},
  {"id":"getCreditNotificationPreferences","method":"GET","path":"/me/credit-notifications","summary":"Get low-credit warning preferences","description":"Reads the personal low-credit warning threshold and delivery channels for the user associated with this credential. This preference follows the user across workspaces. A user-owned API key or OAuth token is required; service-account credentials are rejected. **Required scope:** `settings:read`.","tag":"Account","parameters":[]},
  {"id":"getCrmSync","method":"GET","path":"/crm-syncs/{id}","summary":"Get CRM sync","description":"Get CRM sync","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"CRM sync ID."}]},
  {"id":"getCustomDomainStatus","method":"GET","path":"/custom-domain","summary":"Get custom domain status","description":"Reads the workspace custom domain and checks its live ownership plus DNS/TLS configuration. `ready` becomes true only when ownership is verified and the platform reports a valid configuration that can receive a TLS certificate. **Required scope:** `settings:read` or `assistants:read`. Requires workspace owner/admin role and the Whitelabel entitlement. **Requires the white-label entitlement** (plan add-on `whitelabel`, or a workspace override). Workspaces without it get `403 whitelabel_not_in_plan`, and only workspace owners and admins may call it.","tag":"Settings","parameters":[]},
  {"id":"getCustomerMemory","method":"GET","path":"/contacts/{id}/memory","summary":"Get customer memory","description":"Returns the contact, shared and assistant-specific memories, exact channel identities, and recent audit events. **Required scope:** `leads:read` or `calls:read`.","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Audience contact ID."}]},
  {"id":"getDarkWindowSettings","method":"GET","path":"/settings/dark-windows","summary":"Get Dark Windows settings","description":"Reads proactive-outbound quiet hours for every supported channel and the workspace timezone. Inbound customer replies remain available. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"getDashboard","method":"GET","path":"/dashboards/{id}","summary":"Get a custom dashboard","description":"**Required scope:** `dashboards:read` or `calls:read`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."}]},
  {"id":"getDashboardAnalytics","method":"GET","path":"/dashboards/{id}/analytics","summary":"Get dashboard analytics","description":"Tenant-scoped call KPIs and deltas, zero-filled daily activity, breakdowns, assistant ranking, campaign progress, recent calls, and plan-gated module summaries. Date buckets follow the workspace timezone. **Required scope:** `dashboards:read` or `calls:read`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."},{"name":"range","in":"query","required":false,"type":"string","enum":["7d","14d","30d","90d"],"default":"30d"},{"name":"from","in":"query","required":false,"type":"string","description":"Inclusive ISO date or timestamp."},{"name":"to","in":"query","required":false,"type":"string","description":"A date is inclusive; a timestamp is an exclusive boundary."},{"name":"assistant_ids","in":"query","required":false,"type":"string","description":"Comma-separated assistant IDs (max 50)."},{"name":"campaign_ids","in":"query","required":false,"type":"string","description":"Comma-separated campaign IDs (max 50)."},{"name":"directions","in":"query","required":false,"type":"string","description":"Comma-separated call directions."},{"name":"statuses","in":"query","required":false,"type":"string","description":"Comma-separated call statuses."},{"name":"sentiments","in":"query","required":false,"type":"string","description":"Comma-separated post-call sentiments."},{"name":"success","in":"query","required":false,"type":"boolean"},{"name":"compare","in":"query","required":false,"type":"boolean","default":true,"description":"Compare with the immediately preceding equal-length period."}]},
  {"id":"getDriveSource","method":"GET","path":"/knowledge-bases/{id}/drive-sources/{sourceId}","summary":"Get a cloud drive source","description":"Fetch a single cloud drive sync source, including its custom display name, remote folder metadata, last run status, `files_synced`, `credits_spent` and `last_error`. **Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"sourceId","in":"path","required":true,"type":"string","format":"uuid","description":"Drive source ID."}]},
  {"id":"getEmailDomain","method":"GET","path":"/email/domains/{id}","summary":"Get an email domain","description":"**Required scope:** `assistants:read`. Requires workspace owner/admin.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getEmailHistoryItem","method":"GET","path":"/history/emails/{id}","summary":"Get an email conversation","description":"Returns every inbound and outbound turn in the email thread in chronological order, including stable thread and immediate-parent IDs, full plain-text bodies, reply states/errors, and attachment metadata. Inbound audio and image attachments can include a transcript or a short image description, with media links valid for one hour. Image descriptions can include readable text; PDFs, videos and other files retain metadata only. **Required scope:** `calls:read`.\n\nRemoved conversations are excluded. Their detail IDs return not found.","tag":"History","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Email message or thread-root ID. Any message ID in the thread resolves to the complete conversation."}]},
  {"id":"getEmailSettings","method":"GET","path":"/email/settings","summary":"Get email channel defaults","description":"Workspace-wide default sender name and signature, used when an address doesn't have its own. **Required scope:** `assistants:read`. Requires workspace owner/admin.","tag":"Messaging","parameters":[]},
  {"id":"getInboxLabelSettings","method":"GET","path":"/inbox-labels/settings","summary":"Get message label settings","description":"Requires calls:read. Returns the workspace preference and plan availability.","tag":"History","parameters":[]},
  {"id":"getIntegration","method":"GET","path":"/integrations/{id}","summary":"Get a calendar integration","description":"Read a single calendar integration. Secret values are masked.\n\n**Required scope:** `integrations:read` (keys without scope restrictions have full access).","tag":"Integrations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Integration ID"}]},
  {"id":"getKnowledgeBase","method":"GET","path":"/knowledge-bases/{id}","summary":"Get a knowledge base","description":"**Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}]},
  {"id":"getKnowledgeBaseFaq","method":"GET","path":"/knowledge-bases/{id}/faqs/{faqId}","summary":"Get an FAQ entry","description":"Get an FAQ entry","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"faqId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getLead","method":"GET","path":"/campaigns/{id}/leads/{leadId}","summary":"Get a campaign lead","description":"Returns editable contact data and user-managed `custom_fields` plus a separate read-only `system_variables` object. **Required scope:** `leads:read`.","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."},{"name":"leadId","in":"path","required":true,"type":"string","format":"uuid","description":"Lead ID."}]},
  {"id":"getLoop","method":"GET","path":"/loop","summary":"Get Famulor Loop access and settings","description":"Returns member access and safe workspace settings. Requires `loop:read`. Registration secrets and internal cost data are never returned; credentials without an associated member receive `not_authenticated` access.","tag":"Famulor Loop","parameters":[]},
  {"id":"getLoopAvailability","method":"GET","path":"/loop/availability","summary":"Get personal Loop availability","description":"Returns the authenticated member's weekly Loop schedule, effective timezone, current schedule result, and selected Recall appointment calendar. Requires a user-owned credential with `loop:read`.","tag":"Famulor Loop","parameters":[]},
  {"id":"getLoopCall","method":"GET","path":"/loop/calls/{id}","summary":"Get a Loop call","description":"Read a Loop call with participant names, avatars, and available recordings with playback links valid for one hour. Personal scope requires ownership or participation; workspace scope requires workspace owner/admin access. Requires a user-owned credential with loop:read. Human conversations are not automatically transcribed.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"scope","in":"query","required":false,"type":"string","enum":["personal","workspace"],"default":"personal","description":"Personal call history by default. Workspace call history is available to authorized workspace managers."}]},
  {"id":"getLoopDialingPreferences","method":"GET","path":"/loop/preferences","summary":"Get personal Loop dialing preferences","description":"Returns the authenticated member's default country for national dial-pad numbers. Requires a user-owned credential with `loop:read`.","tag":"Famulor Loop","parameters":[]},
  {"id":"getLoopNumberRoute","method":"GET","path":"/loop/number-routes/{id}","summary":"Get a Loop phone number route","description":"Returns one eligible purchased phone number and its logical destination. Requires `loop:read` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}]},
  {"id":"getLoopPresence","method":"GET","path":"/loop/presence","summary":"Get personal Loop presence","description":"Returns the authenticated member's availability and reachable device classes. Requires `loop:read`.","tag":"Famulor Loop","parameters":[]},
  {"id":"getLoopQueue","method":"GET","path":"/loop/queues/{id}","summary":"Get a Loop call queue","description":"Returns one call queue. Requires `loop:read` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}]},
  {"id":"getLoopRecording","method":"GET","path":"/loop/recording","summary":"Get Loop call recording","description":"Read the recording state and available controls for an active Loop call. Requires loop:read, a user-owned credential and permission to control this call. Does not start recording.","tag":"Famulor Loop","parameters":[{"name":"call_id","in":"query","required":true,"type":"string","format":"uuid","description":"Public Loop call ID."}]},
  {"id":"getLoopRingGroup","method":"GET","path":"/loop/ring-groups/{id}","summary":"Get a Loop ring group","description":"Returns one ring group. Requires `loop:read` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}]},
  {"id":"getLoopRoutingRule","method":"GET","path":"/loop/routing-rules/{id}","summary":"Get a Loop routing rule","description":"Returns one routing rule including shared weekly hours, time conditions, and continuation outcomes. Requires `loop:read` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}]},
  {"id":"getMarketingIntegrations","method":"GET","path":"/settings/marketing","summary":"Get marketing integrations","description":"Reads structured marketing pixel IDs (GA4, Meta, Google Ads, Microsoft UET) for this white-label domain. Conversion API secrets are never returned — only whether a secret is stored. **Required scope:** `settings:read`. Requires white-label access.","tag":"Settings","parameters":[]},
  {"id":"getMe","method":"GET","path":"/me","summary":"Get current credential","description":"Self-inspection of the calling API key: key metadata, workspace (tenant), active plan, effective limits, feature toggles, and Assistant engine-mode availability (`-1` = unlimited, `0` = disabled). No scope required — any valid key works.","tag":"Account","parameters":[]},
  {"id":"getMemorySettings","method":"GET","path":"/settings/memory","summary":"Get memory settings","description":"Reads the workspace defaults for caller memory. Assistants with `memory_mode: \"inherit\"` (see `PATCH /assistants/{id}`) follow `memory_enabled_default`. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"getMessagingHistoryItem","method":"GET","path":"/history/messaging/{id}","summary":"Get a messaging conversation","description":"Returns up to 500 messages in chronological order with full text, attachment metadata, available voice-note transcripts, short image descriptions, and media links valid for one hour. Applies to chat channels and connected mailbox or support channels. Transcripts and image descriptions are available only when an accessible attachment could be analyzed. Image descriptions can include readable text; this attachment feature does not analyze PDFs or videos. Fetch this endpoint again to refresh media links. **Required scope:** `calls:read`.\n\nRemoved conversations are excluded. Their detail IDs return not found.","tag":"History","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Messaging conversation ID returned by the history list."}]},
  {"id":"getMessengerFacebookLoginConfig","method":"GET","path":"/messenger/facebook-login","summary":"Messenger Facebook Login public config","description":"Returns whether Connect with Facebook for Messenger is enabled and the public Meta app ID. **Required scope:** `assistants:read`.","tag":"Messaging","parameters":[]},
  {"id":"getOutboundLimits","method":"GET","path":"/settings/outbound-limits","summary":"Get outbound call limits","description":"Returns today's workspace-wide usage, remaining allowance, reset time, and request history for outbound calls through integrated numbers. Inbound, web, and customer-owned SIP trunk calls do not count. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"getPaymentStatus","method":"GET","path":"/billing/payment-status","summary":"Get workspace payment status","description":"Check whether the workspace has open invoices with an amount remaining. These invoices require payment before continuing in the app. Returns the oldest outstanding invoice and the number still open. Paid, void, draft, zero-balance and uncollectible invoices do not block the app. A failed automatic prepaid top-up is a separate notice. Amounts use the invoice currency’s minor unit. No payment links or provider resource identifiers are exposed; use the invoice payment link operation to pay. Available with a valid credential even when API Access is paused. Required scope: billing:read.","tag":"Billing","parameters":[]},
  {"id":"getPhoneNumber","method":"GET","path":"/phone-numbers/{id}","summary":"Get a phone number","description":"**Required scope:** `phone_numbers:read` (keys without scope restrictions have full access).","tag":"Phone Numbers","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Phone number ID."}]},
  {"id":"getPhoneNumberVerification","method":"GET","path":"/phone-numbers/verifications/{id}","summary":"Get regulatory number verification","description":"Fetch one verification case with its progress `timeline`: submitted → automated check → regulatory review → verified → buy a number. **Required scope:** `phone_numbers:read`.","tag":"Phone Numbers","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getPhoneNumberVerificationRequirements","method":"GET","path":"/phone-numbers/verifications/requirements","summary":"Get number verification requirements","description":"Returns the current registration fields, accepted document types, and address requirements for a supported catalog combination. Field names are used as keys when submitting registration details. Required address information is supplied through the address object; internal address references are managed automatically. Unsupported registration types return 400. No verification case is created. **Required scope:** `phone_numbers:read`.","tag":"Phone Numbers","parameters":[{"name":"country","in":"query","required":true,"type":"string","minLength":2,"maxLength":2,"description":"ISO-2 country code, for example DE."},{"name":"type","in":"query","required":false,"type":"string","enum":["local","mobile","national"],"default":"local"},{"name":"end_user_type","in":"query","required":false,"type":"string","enum":["business","individual"],"default":"business"}]},
  {"id":"getPhoneNumberVerificationSubmission","method":"GET","path":"/phone-numbers/verifications/{id}/submission","summary":"Get the last submitted verification details","description":"Returns the details last submitted for your own verification case: country, number type, registration type, contact email, prefix, address, registration details, supporting documents, and the names of the stored document files. Use it to correct a failed or rejected case and resubmit it with `replace_verification_id`. Only the person who submitted the case can read it. Requires a user-scoped API key. **Required scope:** `phone_numbers:read`.","tag":"Phone Numbers","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getPlatformCustomPayment","method":"GET","path":"/platform/custom-payments/{payment_id}","summary":"Get a custom payment","description":"Fetches a single custom payment by ID. **Required scope:** `platform:read`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"payment_id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getPlatformDefaultLimits","method":"GET","path":"/platform/default-limits","summary":"Get platform registration and prepaid defaults","description":"Returns the independent self-service registration and prepaid-account controls, the prepaid extra-minute price in EUR, and the limits applied to prepaid accounts. Available only to API keys belonging to a white-label reseller workspace. **Required scope:** `platform:read`.","tag":"White Label","parameters":[]},
  {"id":"getPlatformUser","method":"GET","path":"/platform/users/{user_id}","summary":"Get a platform user","description":"Detail, in-scope workspaces, and balances for a single customer. **Required scope:** `platform:read`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"user_id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"workspace_id","in":"query","required":false,"type":"string","format":"uuid","description":"Pick a specific workspace when the customer has several in your scope; defaults to the one they own."}]},
  {"id":"getPlatformUserPasswordAccess","method":"GET","path":"/platform/users/{user_id}/password","summary":"Get customer password permissions","description":"Requires platform:read. Checks whether an operator may set this customer’s password or send a branded reset email. Customer must own the selected workspace.","tag":"White Label","parameters":[{"name":"user_id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"workspace_id","in":"query","required":true,"type":"string","format":"uuid"}]},
  {"id":"getPlatformWelcomeCredits","method":"GET","path":"/platform/welcome-credits","summary":"Get platform welcome-credit settings","description":"Returns the one-time wallet credits offered to each newly created free customer, whether automatic grants are active, the reseller wallet balance, and the number of customers that balance can currently fund. Available only to API keys belonging to a white-label reseller workspace. **Required scope:** `platform:read`.","tag":"White Label","parameters":[]},
  {"id":"getQaRun","method":"GET","path":"/qa/runs/{id}","summary":"Get QA run","description":"Fetch a QA run and optional results. A result that could not be scored has an `error` code: `empty_transcript`, `invalid_json`, `call_not_found`, `process_failed` or `judge_failed`; a failed run has `run_failed`. **Required scope:** `calls:read`.","tag":"QA","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"include_results","in":"query","required":false,"type":"boolean"}]},
  {"id":"getReferrals","method":"GET","path":"/referrals","summary":"Get referrals","description":"Refer and Earn share link, reward amounts, and masked referral history for the API-key workspace. Only available on the main platform. **Required scope:** `billing:read` (keys without scope restrictions have full access).","tag":"Billing","parameters":[]},
  {"id":"getResellerBilling","method":"GET","path":"/reseller/billing","summary":"Get reseller financial overview or activity","description":"Read the payment-account readiness, settlement balances, customer payments, bank payout history, balance transactions or tax registration details for the credential’s own Whitelabel workspace. Requires owner or admin authority, Whitelabel access, API Access and billing:read. Financial data is returned only after payments and payouts are enabled and account verification is complete. Amounts are in settlement or transaction currency minor units, without display-currency conversion. Provider IDs, metadata, customer personal data, bank details, fee breakdowns and session secrets are excluded. This operation never moves funds.","tag":"White Label","parameters":[{"name":"view","in":"query","required":false,"type":"string","enum":["overview","payments","payouts","transactions","tax"],"default":"overview","description":"Choose account overview, payments, payouts, balance transactions or tax registrations."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":100,"default":25,"description":"Activity page size."},{"name":"cursor","in":"query","required":false,"type":"string","maxLength":2048,"description":"Opaque next_cursor from the preceding page for the same view."}]},
  {"id":"getResellerTaxSettings","method":"GET","path":"/reseller/tax/settings","summary":"Get reseller tax settings","description":"Requires an active Whitelabel payment account, API Access and workspace owner/admin authority. Requires billing:read. Business address and tax defaults are returned for the credential’s own workspace.","tag":"White Label","parameters":[]},
  {"id":"getRetentionSettings","method":"GET","path":"/settings/retention","summary":"Get data retention settings","description":"Reads per-channel workspace overrides, the governing plan default and limits, and whether the current plan includes Data Retention. A `null` channel value follows `plan_default_days`. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"getRoutine","method":"GET","path":"/routines/{id}","summary":"Get a mission","description":"**Required scope:** `routines:read` (keys without scope restrictions have full access).","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}]},
  {"id":"getRoutineWebhook","method":"GET","path":"/routines/{id}/webhook","summary":"Get mission webhook setup","description":"Returns the public delivery URL, required header name, and configured state. The credential and internal Automation identity are never returned. **Required scope:** `routines:read`.","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}]},
  {"id":"getSegment","method":"GET","path":"/segments/{id}","summary":"Get a segment","description":"Read a single segment. **Required scope:** `segments:read` (the legacy `calls:read` scope is also accepted; keys without scope restrictions have full access).","tag":"Segments","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Segment ID."}]},
  {"id":"getSipTrunk","method":"GET","path":"/sip-trunks/{id}","summary":"Get a SIP trunk","description":"Returns a customer-owned BYO/BYOC SIP trunk. Managed trunks behind marketplace purchases and verified caller IDs return `404` and are not part of this resource. Passwords and internal trunk identifiers are never returned. **Required scope:** `sip_trunks:read` (keys without scope restrictions have full access).","tag":"SIP Trunks","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"SIP trunk ID."}]},
  {"id":"getSlackOauthConfig","method":"GET","path":"/slack/oauth","summary":"Slack Add to Slack public config","description":"Returns whether Add to Slack is enabled and the public Slack client ID for the platform Famulor app. **Required scope:** `assistants:read`. Platform-root workspaces only (not whitelabel).","tag":"Messaging","parameters":[]},
  {"id":"getSmsRegistration","method":"GET","path":"/phone-numbers/{id}/sms-registration","summary":"Get SMS registration","description":"Read registration for a purchased active US local SMS-capable number in the active workspace. Requires phone_numbers:read.","tag":"Phone Numbers","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getSmsRegistrationBilling","method":"GET","path":"/billing/sms-registration","summary":"Get workspace SMS registration billing","description":"Requires billing:read. User-owned credentials need a workspace owner, admin or billing role; workspace service-account credentials can read it with the scope alone. Available even after the associated phone rentals end.","tag":"Billing","parameters":[]},
  {"id":"getSupportRequest","method":"GET","path":"/support/requests/{reference}","summary":"Get a support request","description":"Returns one of your support requests with its status, assigned support team member and the conversation with the support team. **Required scope:** `settings:read`.","tag":"Settings","parameters":[{"name":"reference","in":"path","required":true,"type":"string"}]},
  {"id":"getTelephonyUsageRates","method":"GET","path":"/usage/telephony-rates","summary":"Estimate assistant or Loop phone rates","description":"List available countries or estimate incoming or outgoing assistant or Loop phone rates for the current workspace. Loop requires calls:read or loop:read; assistant estimates require calls:read. Omit country to list supported countries. Assistant estimates cover purchased numbers and verified caller IDs using the included phone service. Your own connected phone service is billed separately. Amounts are EUR equivalents at the current credit top-up rate, not a guaranteed invoice total. Country ranges cover available number types and destination networks. Transfers can involve multiple call legs; Loop conference participation, recording and queue handling can add separate usage. AI assistant talk time is separate. Final charges are calculated after the call ends.","tag":"Billing","parameters":[{"name":"context","in":"query","required":false,"type":"string","enum":["loop","assistant"],"default":"loop","description":"Choose assistant phone service or Loop calling."},{"name":"country","in":"query","required":false,"type":"string","description":"Two-letter country code. Incoming: receiving number country. Outgoing: destination country. Omit for the country list."},{"name":"direction","in":"query","required":false,"type":"string","enum":["inbound","outbound"],"default":"outbound"}]},
  {"id":"getTool","method":"GET","path":"/tools/{id}","summary":"Get a tool","description":"Read a single reusable tool. Secret values in `config` are always masked as `•••`.\n\n**Required scope:** `assistants:read` (keys without scope restrictions have full access).","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Tool ID."}]},
  {"id":"getToolUsage","method":"GET","path":"/tools/{id}/usage","summary":"Get tool usage and impact","description":"Lists assistants currently assigned to the tool. **Required scope:** `assistants:read`.","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getTranslationSession","method":"GET","path":"/translation-sessions/{id}","summary":"Get a translation room","description":"Read connection state and original/translated phrase pairs while the room is active. Phrase history expires when the room ends. Requires calls:read and a credential belonging to the room host.","tag":"Translation","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"after","in":"query","required":false,"type":"integer","minimum":0,"description":"Last received phrase sequence; returns up to 200 newer active-session phrases."}]},
  {"id":"getVoiceClone","method":"GET","path":"/voices/clone/{cloneId}","summary":"Get cloned voice","description":"Returns one ready cloned voice owned by the current workspace. **Required scope:** `voices:read` or `assistants:read`.","tag":"Voices","parameters":[{"name":"cloneId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getVoiceCloneCapability","method":"GET","path":"/voices/clone/capability","summary":"Check voice cloning capability","description":"Returns access, current audio sample constraints, and the one-time workspace creation allowance and current credit price. Stored voices have no plan capacity limit. Read pricing.next_creation_credits before submitting a job. **Required scope:** voices:read or assistants:read.","tag":"Voices","parameters":[]},
  {"id":"getVoiceCloneJob","method":"GET","path":"/voices/clone/jobs/{jobId}","summary":"Get voice clone job","description":"Returns the workspace-scoped status of a create or delete job. **Required scope:** `voices:read` or `assistants:read`.","tag":"Voices","parameters":[{"name":"jobId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getVoicePreview","method":"GET","path":"/voices/{id}/preview","summary":"Play a Full Duplex voice preview","description":"Download an existing native voice recording. Use the voice ID returned by the compatible Realtime voice catalog. Requires voices:read and current workspace access to Full Duplex. This endpoint does not synthesize new speech. Preview paths returned by the catalog are relative to the API origin and require the same authentication.","tag":"Voices","parameters":[{"name":"id","in":"path","required":true,"type":"string","description":"Opaque catalog voice selector, such as voice:9a53d9f9-1f61-43a9-b877-80e006f775ad."},{"name":"realtime_variant","in":"query","required":false,"type":"string","enum":["full_duplex"],"default":"full_duplex"}],"binary":true},
  {"id":"getWhatsAppCallingReadiness","method":"GET","path":"/whatsapp/calling","summary":"WhatsApp calling readiness","description":"Voice-calling readiness for a WhatsApp connector's business phone number (Meta call settings, webhook subscription, quality rating). **Required scope:** `assistants:read`.","tag":"Messaging","parameters":[{"name":"connector_id","in":"query","required":true,"type":"string","format":"uuid"}]},
  {"id":"getWhatsAppEmbeddedSignupConfig","method":"GET","path":"/whatsapp/embedded-signup","summary":"WhatsApp Embedded Signup public config","description":"Returns whether Meta Embedded Signup is enabled and public app/config IDs. **Required scope:** `assistants:read`.","tag":"Messaging","parameters":[]},
  {"id":"getWhatsAppSenderProfile","method":"GET","path":"/whatsapp/connectors/{id}/profile","summary":"Get WhatsApp sender profile","description":"Load WhatsApp Business Profile draft + Meta status cache. **Required scope:** `assistants:read`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getWidgetConnector","method":"GET","path":"/widget-connectors/{id}","summary":"Get web widget","description":"**Required scope:** `assistants:read`.","tag":"Widgets","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"getWorkspaceCountry","method":"GET","path":"/settings/workspace-country","summary":"Get workspace country","description":"Reads the workspace home country. A null value means the country has not yet been detected or selected. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"getWorkspaceUsageRates","method":"GET","path":"/usage/rates","summary":"Get workspace usage rates","description":"Current customer credit rates for the credential workspace, including fixed charges, token-based AI usage and variable charges. Requires billing:read or calls:read. A null credit amount means usage-based or variable pricing, never free usage. Monthly add-on subscriptions and phone-number rental are separate. Rates include separate full_duplex and avatar surcharges per active minute, in addition to the normal talk_minute rate. Both apply when used together; prices are fixed at call start.","tag":"Billing","parameters":[]},
  {"id":"importCarrierNumbers","method":"POST","path":"/carrier-connections/{id}/import","summary":"Import carrier numbers","description":"Configures carrier routing and creates platform SIP trunks. Returns one result per number; individual failures do not fail the whole batch. **Required scope:** `sip_trunks:write`.","tag":"Carrier Connections","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Carrier connection ID."}],"body":{"required":true,"fields":[{"name":"numbers","required":true,"type":"array","items":{"type":"object"}}]}},
  {"id":"inviteTranslationGuest","method":"POST","path":"/translation-sessions/{id}/invite","summary":"Invite the external guest","description":"Return the room invitation link. Supply email to send the invitation; no account is created. The invitation allows guest participation only. Requires calls:write and a credential belonging to the room host. Workspace roles, credits, assistant and calling limits apply.","tag":"Translation","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"email","required":false,"type":"string","format":"email"}]}},
  {"id":"linkLoopCallContact","method":"PATCH","path":"/loop/calls/{id}","summary":"Link a Loop call to a contact","description":"Link a Loop call you own or participated in to an Audience contact, or pass `lead_id: null` to remove the link. The linked contact is shown in History → Loop calls; without a link the contact is matched by phone number. Requires a user-owned credential with `loop:write`.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"lead_id","required":true,"type":"string","description":"Audience contact ID from the same workspace, or null to unlink.","format":"uuid"}]}},
  {"id":"listAccountSessions","method":"GET","path":"/settings/sessions","summary":"List active account sessions","description":"Lists active sign-in sessions for the user associated with the API credential. Session IDs are opaque revocation handles; authentication tokens, IP addresses, and native authentication-provider identifiers are never returned. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"listAcuityAppointmentTypes","method":"GET","path":"/integrations/acuity/appointment-types","summary":"List Acuity appointment types","description":"Lists appointment types available to the selected Acuity account, including service, class, and series types. **Required scope:** `integrations:read`. User-owned credentials need a workspace owner or admin role; workspace service-account credentials only need the scope.","tag":"Integrations","parameters":[{"name":"connection_id","in":"query","required":true,"type":"string","format":"uuid"}]},
  {"id":"listAcuityCalendars","method":"GET","path":"/integrations/acuity/calendars","summary":"List Acuity calendars","description":"Lists calendars available to the selected Acuity account. Use a calendar ID to restrict an integration to one calendar, or omit it to use any compatible calendar. **Required scope:** `integrations:read`. User-owned credentials need a workspace owner or admin role; workspace service-account credentials only need the scope.","tag":"Integrations","parameters":[{"name":"connection_id","in":"query","required":true,"type":"string","format":"uuid"}]},
  {"id":"listAcuityConnections","method":"GET","path":"/integrations/acuity/connections","summary":"List connected Acuity accounts","description":"Lists workspace-bound Acuity Scheduling OAuth accounts. Access tokens, provider account URIs, and client secrets are never returned. **Required scope:** `integrations:read`. User-owned credentials need a workspace owner or admin role; workspace service-account credentials only need the scope.","tag":"Integrations","parameters":[]},
  {"id":"listApiKeys","method":"GET","path":"/api-keys","summary":"List API keys","description":"List the API keys created in the calling workspace, including revoked ones (`revoked_at` set). Never returns the secret — only `prefix` plus metadata; use it to audit which keys exist and when each was last used. **Required scope:** `settings:read`.","tag":"API Keys","parameters":[{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listAssistantAutomations","method":"GET","path":"/assistants/{id}/automations","summary":"List assistant-callable automations","description":"List automations this assistant can choose to run in voice, web chat, messaging, or email conversations. **Required scope:** `assistants:read`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}]},
  {"id":"listAssistants","method":"GET","path":"/assistants","summary":"List assistants","description":"Paginated list of assistants in your workspace, newest first. **Required scope:** `assistants:read` (keys without scope restrictions have full access).","tag":"Assistants","parameters":[{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listAssistantTests","method":"GET","path":"/assistants/{id}/tests","summary":"List simulation tests","description":"List simulation tests for an assistant. **Required scope:** `assistants:read`. Requires the Simulations feature in the workspace plan.","tag":"Simulations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"listAssistantVersions","method":"GET","path":"/assistants/{id}/versions","summary":"List assistant versions","description":"**Required scope:** `assistants:read`.","tag":"Versions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"listAudienceContactChannels","method":"GET","path":"/leads/{id}/channels","summary":"List contact channels","description":"List the manually manageable channel profiles linked to one Audience contact. Microsoft Teams profiles expose the visible connection name without internal account or routing identifiers. **Required scope:** `leads:read` (legacy `calls:read` is also accepted).","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Audience contact ID."}]},
  {"id":"listAudienceContacts","method":"GET","path":"/leads","summary":"List Audience contacts","description":"List contacts across all campaigns with channel and tenant-scoped Call QA filters. Channel matches use linked calls, SMS, email, messaging conversations and contact channel profiles. Repeating `channel` matches any selected channel. QA uses the per-call History scorecard, counts every call once and excludes unscored calls. QA filters require the AI QA Scorecards feature. **Required scope:** `leads:read` (legacy `calls:read` is also accepted).","tag":"Leads","parameters":[{"name":"search","in":"query","required":false,"type":"string","description":"Search contact name, phone or email."},{"name":"display_status","in":"query","required":false,"type":"array","items":{"type":"string","enum":["created","processing","rescheduled","max_retries","completed","dnc"]}},{"name":"campaign_id","in":"query","required":false,"type":"string","description":"Campaign UUID or `none` for contacts without a campaign."},{"name":"dnc","in":"query","required":false,"type":"boolean","description":"When true, only contacts on the Do-Not-Call list are returned. When false, contacts on that list are excluded."},{"name":"channel","in":"query","required":false,"type":"array","items":{"type":"string","enum":["call","sms","email","whatsapp","telegram","messenger","slack","teams","discord","gchat","x","freshdesk","gmail","outlook","zendesk","servicenow","intercom","zoho_mail","agent_mail","instagram","zulip"]},"description":"Contacts with activity or a profile on any selected channel. Repeat the query parameter for multiple channels."},{"name":"source","in":"query","required":false,"type":"array","items":{"type":"string"},"description":"Contact source tag. Repeat for multiple values; values are ORed."},{"name":"tag","in":"query","required":false,"type":"array","items":{"type":"string"},"description":"Contact tag. Repeat for multiple values; values are ORed."},{"name":"created_from","in":"query","required":false,"type":"string","format":"date-time","description":"Inclusive lower bound for the contact creation timestamp."},{"name":"created_to","in":"query","required":false,"type":"string","format":"date-time","description":"Inclusive upper bound for the contact creation timestamp."},{"name":"attempts_min","in":"query","required":false,"type":"integer","minimum":0,"description":"Minimum outbound call attempts."},{"name":"attempts_max","in":"query","required":false,"type":"integer","minimum":0,"description":"Maximum outbound call attempts."},{"name":"amd_result","in":"query","required":false,"type":"array","items":{"type":"string","enum":["human","uncertain","machine-vm","machine-ivr","machine-unavailable","none"]},"description":"Last AMD result. Repeat for multiple values; `none` matches contacts without a result."},{"name":"qa_window","in":"query","required":false,"type":"json","default":90},{"name":"qa_average_min","in":"query","required":false,"type":"number","minimum":0,"maximum":100},{"name":"qa_average_max","in":"query","required":false,"type":"number","minimum":0,"maximum":100},{"name":"qa_min_scored_calls","in":"query","required":false,"type":"integer","minimum":1},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listAutomationAiActions","method":"GET","path":"/automations/ai-actions","summary":"List Milian AI automation actions","description":"Requires automations:read. Returns the five evaluation actions, configuration defaults, output fields and three editable presets. Also available as list_automation_ai_actions over MCP.","tag":"Automations","parameters":[]},
  {"id":"listAutomationConnections","method":"GET","path":"/automations/connections","summary":"List automation connections","description":"Workspace-scoped reusable credentials for CRM providers, SMTP relays, and official remote MCP endpoints used by automation nodes. Provider catalog entries with `supports_crm_sync=true` can power recurring CRM Sync (inbound, outbound, or bidirectional) when connected with `kind=api` (HubSpot, HighLevel, Salesforce, Pipedrive, Close, Zoho CRM, Attio, Keap, and Twenty). Apps connected through Browse apps appear with `provider=connected_app` and `config.toolkit`. Secrets are never returned; secret fields arrive as `\"•••\"`. **Required scope:** `automations:read` or `calls:read`.","tag":"Automations","parameters":[]},
  {"id":"listAutomations","method":"GET","path":"/automations","summary":"List automations","description":"Returns native workspace automations plus platform entitlement/run allowance. **Required scope:** `automations:read` or the legacy `calls:read`. The workspace plan must include Automations.","tag":"Automations","parameters":[]},
  {"id":"listBookingEventTypes","method":"GET","path":"/booking-event-types","summary":"List booking event types","description":"List the event types of the native booking engine. Each active event type has a public, iframe-embeddable booking page at `/book/{workspace}/{slug}` and can be attached to assistants via a `native` calendar integration.\n\n**Required scope:** `bookings:read` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[]},
  {"id":"listBookings","method":"GET","path":"/bookings","summary":"List bookings","description":"List bookings of the native booking engine. Bookings are created by the public booking page, by assistants mid-call (`book_appointment`), via the public page API, or by `POST /bookings` — which also supports a staff override outside the event type's open times. Use `view` for the dashboard-style lists, or `status` for an exact status; they cannot be combined.\n\n**Required scope:** `bookings:read` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[{"name":"event_type_id","in":"query","required":false,"type":"string","format":"uuid","description":"Filter by event type."},{"name":"status","in":"query","required":false,"type":"string","enum":["confirmed","cancelled","completed","no_show"],"description":"Filter by exact status. Cannot be combined with view."},{"name":"source","in":"query","required":false,"type":"string","enum":["web","call","api","manual"],"description":"Filter by booking source."},{"name":"view","in":"query","required":false,"type":"string","enum":["upcoming","unconfirmed","recurring","past","cancelled"],"description":"Dashboard-style booking view. Cannot be combined with status."},{"name":"from","in":"query","required":false,"type":"string","format":"date-time","description":"Only bookings with start_at >= from."},{"name":"to","in":"query","required":false,"type":"string","format":"date-time","description":"Only bookings with start_at <= to."},{"name":"limit","in":"query","required":false,"type":"integer","maximum":200,"default":50},{"name":"offset","in":"query","required":false,"type":"integer","default":0}]},
  {"id":"listBookingSlots","method":"GET","path":"/booking-event-types/{id}/slots","summary":"List free slots","description":"List the free start times of one active event type for a date range (at most 28 days; dates default to the workspace time zone). Past times and times after `bookable_until` are never returned. Pass a returned slot unchanged as `start` to `POST /bookings` or `POST /bookings/{id}/reschedule`; when moving a booking, pass `exclude_booking_id` so its own time does not block nearby slots.\n\nReturns `409` instead of `200` when the event type is turned off, or when the workspace has not set up its public booking address yet.\n\nA `503` here can mean either request protection is temporarily unavailable (`internal_error`) or the availability engine itself failed to load (`service_unavailable`, message \"Could not load availability\").\n\n**Required scope:** `bookings:read` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Event type ID"},{"name":"start","in":"query","required":false,"type":"string","format":"date","description":"Start of the date range (YYYY-MM-DD); default today."},{"name":"end","in":"query","required":false,"type":"string","format":"date","description":"End of the date range (YYYY-MM-DD); default start + 6 days, max 28 days."},{"name":"timezone","in":"query","required":false,"type":"string","description":"IANA time zone for the returned range and slots; default the workspace time zone."},{"name":"exclude_booking_id","in":"query","required":false,"type":"string","format":"uuid","description":"Exclude this booking's own time from busy calculations (use when rescheduling it)."}]},
  {"id":"listCalendlyConnections","method":"GET","path":"/integrations/calendly/connections","summary":"List connected Calendly accounts","description":"Lists workspace-bound Calendly OAuth accounts. Access tokens, refresh tokens, user resource URIs, refresh locks, and client secrets are never returned. **Required scope:** `integrations:read`. User-owned credentials need a workspace owner or admin role; workspace service-account credentials only need the scope.","tag":"Integrations","parameters":[]},
  {"id":"listCalendlyEventTypes","method":"GET","path":"/integrations/calendly/event-types","summary":"List active Calendly event types","description":"Lists active event types by public ID, name and duration, with supported location options. Full Calendly resource URIs stay internal. **Required scope:** `integrations:read`. User-owned credentials need a workspace owner or admin role; workspace service-account credentials only need the scope.","tag":"Integrations","parameters":[{"name":"connection_id","in":"query","required":true,"type":"string","format":"uuid"}]},
  {"id":"listCallerIds","method":"GET","path":"/caller-ids","summary":"List caller IDs","description":"**Required scope:** `phone_numbers:read` or `calls:read`.","tag":"Caller IDs","parameters":[]},
  {"id":"listCalls","method":"GET","path":"/calls","summary":"List calls","description":"Calls in your workspace, newest first by creation time unless `sort=updated_at` is set. Failed outbound calls include a provider-neutral `failure` object with stable retry/action guidance. **Required scope:** `calls:read` (keys without scope restrictions have full access).\n\nRemoved conversations are excluded. Their detail IDs return not found.","tag":"Calls","parameters":[{"name":"assistant_id","in":"query","required":false,"type":"string","format":"uuid","description":"Filter by assistant."},{"name":"campaign_id","in":"query","required":false,"type":"string","format":"uuid","description":"Filter by campaign (dialer calls)."},{"name":"status","in":"query","required":false,"type":"string","enum":["queued","ringing","in_progress","completed","failed","no_answer","busy"]},{"name":"direction","in":"query","required":false,"type":"string","enum":["inbound","outbound","web"]},{"name":"sort","in":"query","required":false,"type":"string","enum":["created_at","updated_at"],"default":"created_at","description":"Sort newest first by creation time (default) or latest update. Use `updated_at` when polling completed calls so older calls that finish later appear in the recent page."},{"name":"from","in":"query","required":false,"type":"string","format":"date-time","description":"Only calls created at or after this ISO 8601 date/datetime."},{"name":"to","in":"query","required":false,"type":"string","format":"date-time","description":"Only calls created at or before this ISO 8601 date/datetime."},{"name":"sentiment","in":"query","required":false,"type":"string","enum":["positive","neutral","negative"],"description":"Filter by post-call sentiment (requires the assistant's `analysis_config` sentiment to be enabled)."},{"name":"success","in":"query","required":false,"type":"boolean","description":"Filter by post-call success verdict (requires the assistant's `analysis_config.success` to be enabled)."},{"name":"q","in":"query","required":false,"type":"string","description":"Lexical search across the call transcript and summary. Case-insensitive substring match."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listCampaignDeliveries","method":"GET","path":"/campaigns/{id}/deliveries","summary":"List campaign deliveries","description":"Lists primary and follow-up delivery attempts. Provider, room, carrier and lease identifiers are never exposed. **Required scope:** `campaigns:read`.","tag":"Campaigns","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."},{"name":"stage","in":"query","required":false,"type":"string","enum":["primary","follow_up"]},{"name":"status","in":"query","required":false,"type":"string"},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listCampaigns","method":"GET","path":"/campaigns","summary":"List campaigns","description":"**Required scope:** `campaigns:read` (keys without scope restrictions have full access).","tag":"Campaigns","parameters":[{"name":"status","in":"query","required":false,"type":"string","enum":["draft","running","paused","completed","archived"]},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listCarrierAvailableNumbers","method":"GET","path":"/carrier-connections/{id}/available-numbers","summary":"List carrier numbers available to import","description":"Lists carrier-owned numbers and flags routing conflicts and numbers already imported into this workspace. **Required scope:** `sip_trunks:read`.","tag":"Carrier Connections","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Carrier connection ID."}]},
  {"id":"listCarrierConnections","method":"GET","path":"/carrier-connections","summary":"List carrier connections","description":"Lists BYOC connections and their imported numbers. Secrets are never returned. **Required scope:** `sip_trunks:read`.","tag":"Carrier Connections","parameters":[]},
  {"id":"listCrawlSourcePages","method":"GET","path":"/knowledge-bases/{id}/crawl-sources/{sourceId}/pages","summary":"List indexed crawl-source pages","description":"List up to 500 ready website pages already indexed for a crawl source. This read-only request does not fetch the website, start a refresh, or spend credits. **Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"sourceId","in":"path","required":true,"type":"string","format":"uuid","description":"Crawl source ID."}]},
  {"id":"listCrawlSources","method":"GET","path":"/knowledge-bases/{id}/crawl-sources","summary":"List crawl sources","description":"List the website crawl sources of a knowledge base, including each source's editable custom display name. Each source crawls pages under a root URL (same host only, static HTML — no JavaScript rendering) into knowledge documents. **Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}]},
  {"id":"listCrmSyncRuns","method":"GET","path":"/crm-syncs/{id}/runs","summary":"List CRM sync runs","description":"List durable run history and counters. Requires `automations:read` or `calls:read`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"CRM sync ID."}]},
  {"id":"listCrmSyncs","method":"GET","path":"/crm-syncs","summary":"List CRM syncs","description":"List recurring CRM syncs (inbound, outbound, or bidirectional). Requires workspace Beta Features, the automation platform entitlement, CRM sync plan capacity, and `automations:read` or `calls:read`.","tag":"Automations","parameters":[]},
  {"id":"listCustomerMemories","method":"GET","path":"/contacts/memory","summary":"List customer memories","description":"Lists one consent- and retention-aware memory entry per contact with exact channel identities. Private assistant content is never exposed in the list. **Required scope:** `leads:read` or `calls:read`.","tag":"Leads","parameters":[{"name":"consent","in":"query","required":false,"type":"string","enum":["unknown","granted","denied"]},{"name":"search","in":"query","required":false,"type":"string","maxLength":200,"description":"Case-insensitive search across contact name, phone, email, and the currently visible shared summary. Applied before pagination together with the consent filter. Private, expired, and stale memory content is not searched."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listDashboards","method":"GET","path":"/dashboards","summary":"List custom dashboards","description":"Returns the workspace's custom dashboards in display order. **Required scope:** `dashboards:read` or the legacy `calls:read`. The workspace plan must include Custom dashboards.","tag":"Dashboards","parameters":[{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listDashboardWidgets","method":"GET","path":"/dashboards/{id}/widgets","summary":"List dashboard widgets","description":"Returns widgets with conditions, visualization settings, display order, and 12-column grid layout. **Required scope:** `dashboards:read` or `calls:read`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."}]},
  {"id":"listDriveSources","method":"GET","path":"/knowledge-bases/{id}/drive-sources","summary":"List cloud drive sources","description":"List the cloud drive sync sources of a knowledge base, including each source's editable custom display name. Each source syncs files from a Google Drive, OneDrive, Box, Dropbox, or SharePoint folder (via an app connection under Automations → Connections) into knowledge documents. **Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}]},
  {"id":"listEmailAddresses","method":"GET","path":"/email/addresses","summary":"List email addresses","description":"List addresses on the email channel, including the resolved domain and assigned assistant. **Required scope:** `assistants:read`. Requires workspace owner/admin.","tag":"Messaging","parameters":[]},
  {"id":"listEmailDomains","method":"GET","path":"/email/domains","summary":"List email domains","description":"List the domains connected to the email channel, including DNS verification status and the exact records to add at your DNS provider. **Required scope:** `assistants:read`. Requires workspace owner/admin.","tag":"Messaging","parameters":[]},
  {"id":"listEmailSenders","method":"GET","path":"/email-senders","summary":"List email sender choices","description":"Returns the secrets-free sender choices that can be stored on a reusable `send_email` tool: automatic routing, workspace SMTP, platform mail, and verified sender addresses. Also returns workspace display-name and signature defaults. **Required scope:** `settings:read` or `assistants:read`. Requires workspace owner/admin role.","tag":"Settings","parameters":[]},
  {"id":"listHistory","method":"GET","path":"/history","summary":"List conversation history","description":"Calls and assistant email conversations in your workspace, globally sorted by latest activity. Failed outbound call rows include the provider-neutral `failure` object. Every inbound and outbound email turn with the same stable `thread_id` is grouped into one conversation row. Email reply states are normalized to the shared statuses (`pending` → `in_progress`, `replied`/outbound → `completed`). **Required scope:** `calls:read`.\n\nRemoved conversations are excluded. Their detail IDs return not found.","tag":"History","parameters":[{"name":"type","in":"query","required":false,"type":"string","enum":["call","avatar","email","live_chat","whatsapp_voice","whatsapp","telegram","slack","messenger","teams","discord","gchat","x","freshdesk","gmail","outlook","zendesk","servicenow","intercom","zoho_mail","agent_mail","instagram","zulip"],"description":"Filter by channel: matches the `channel` field of each row. `avatar` = web voice with virtual avatar; `live_chat` = widget text chat; messaging channels (chat apps, help desks, mailboxes) query messaging conversations."},{"name":"direction","in":"query","required":false,"type":"string","enum":["inbound","outbound","web"],"description":"Filter by direction. `web` applies only to calls."},{"name":"status","in":"query","required":false,"type":"string","enum":["queued","ringing","in_progress","completed","failed","no_answer","busy","skipped"]},{"name":"assistant_id","in":"query","required":false,"type":"string","format":"uuid","description":"Filter calls and emails by assistant."},{"name":"campaign_id","in":"query","required":false,"type":"string","format":"uuid","description":"Filter by campaign; campaign history contains calls only."},{"name":"lead_id","in":"query","required":false,"type":"string","format":"uuid","description":"Filter the unified history by one Audience contact across calls, messaging and email."},{"name":"tags","in":"query","required":false,"type":"string","description":"Filter by Audience contact tags. Comma-separated; conversations whose contact has any of these tags are included."},{"name":"search","in":"query","required":false,"type":"string","description":"Search phone numbers, email addresses, email subject/body, and call summaries."},{"name":"from","in":"query","required":false,"type":"string","format":"date-time","description":"Only entries active at or after this ISO 8601 date/datetime (latest message time for email threads)."},{"name":"to","in":"query","required":false,"type":"string","format":"date-time","description":"Only entries active at or before this ISO 8601 date/datetime (latest message time for email threads)."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listIntegrations","method":"GET","path":"/integrations","summary":"List calendar integrations","description":"List all calendar integrations of the account (Cal.com, Calendly, Acuity Scheduling, Google Calendar, Outlook, native booking engine). Secret values in configs are always masked. Assign integrations to an assistant via `PUT /assistants/{id}/integrations` — the assistant then gets availability and booking tools plus provider-supported appointment lookup, cancellation, and rescheduling.\n\n**Required scope:** `integrations:read` (keys without scope restrictions have full access).","tag":"Integrations","parameters":[]},
  {"id":"listKnowledgeBaseDocuments","method":"GET","path":"/knowledge-bases/{id}/documents","summary":"List documents","description":"Lists the documents of one knowledge base, newest first: uploaded files, raw text, file URLs, single web pages, crawled website pages and cloud drive files. Each document shows its source, indexing status and chunk count. Use a document `id` to read its indexed chunks (`GET /knowledge-bases/{id}/documents/{docId}/chunks`) or to retry it (`POST /knowledge-bases/{id}/documents` with only `document_id`). Unknown, foreign or malformed knowledge base IDs return 404. **Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listKnowledgeBaseFaqs","method":"GET","path":"/knowledge-bases/{id}/faqs","summary":"List FAQ entries and knowledge gaps","description":"Lists approved FAQ entries or the human-review knowledge-gap inbox. **Required scope:** `knowledge:read`. Beta Features must be enabled for the workspace. Search is case-insensitive literal text matching across questions, answers and proposed answers, applied together with status before pagination. Results are ordered by most recently updated first. meta.pagination.total is the number matching both filters; meta.pending is all open entries (needs_answer and needs_review) in the knowledge base, independent of search, status and page.","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"status","in":"query","required":false,"type":"array","items":{"type":"string","enum":["needs_answer","needs_review","approved","dismissed"]},"description":"One or more statuses, comma-separated or supplied as repeated status parameters. Omit for all statuses.","style":"form","explode":false},{"name":"search","in":"query","required":false,"type":"string","maxLength":200,"description":"Literal text to find in questions, answers or proposed answers. Case-insensitive; surrounding whitespace is ignored. Empty text applies no search filter."},{"name":"include_occurrences","in":"query","required":false,"type":"boolean","default":false},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listKnowledgeBases","method":"GET","path":"/knowledge-bases","summary":"List knowledge bases","description":"**Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listKnowledgeDocumentChunks","method":"GET","path":"/knowledge-bases/{id}/documents/{docId}/chunks","summary":"List document chunks","description":"Lists the exact searchable chunks produced for one knowledge-base document, in source order. Get document IDs from `GET /knowledge-bases/{id}/documents`. Embeddings and internal indexing metadata are never returned. **Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"docId","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge document ID, as returned by `GET /knowledge-bases/{id}/documents`."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0}]},
  {"id":"listLanguages","method":"GET","path":"/languages","summary":"List languages","description":"The platform's assistant language catalog (ISO 639-1 or ISO 639-3 codes with English labels), managed by the platform admin. Use the codes for `primary_language` and `secondary_languages` on an assistant. Only enabled languages are returned. **Required scope:** `assistants:read` (keys without scope restrictions have full access).","tag":"Catalog","parameters":[]},
  {"id":"listLeads","method":"GET","path":"/campaigns/{id}/leads","summary":"List leads","description":"Leads of a campaign, newest first. Every lead includes the derived `display_status`. **Required scope:** `leads:read` (keys without scope restrictions have full access).","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."},{"name":"status","in":"query","required":false,"type":"string","enum":["pending","queued","calling","completed","failed","no_answer","busy","do_not_call"]},{"name":"display_status","in":"query","required":false,"type":"string","enum":["created","processing","rescheduled","max_retries","completed","dnc"],"description":"Filter by derived display status. Mutually exclusive with `status` (if both are sent, `display_status` wins)."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listLoopCalls","method":"GET","path":"/loop/calls","summary":"List Loop calls","description":"List paginated Loop calls with participant names and avatars. Personal scope shows only calls you own or participated in, with direction relative to you. Workspace scope requires workspace owner/admin access. Usage is returned in minutes and credits. Requires a user-owned credential with loop:read.","tag":"Famulor Loop","parameters":[{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":100,"default":50,"description":"Maximum number of calls to return."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"maximum":1000000,"default":0,"description":"Number of calls to skip."},{"name":"scope","in":"query","required":false,"type":"string","enum":["personal","workspace"],"default":"personal","description":"Personal call history by default. Workspace call history is available to authorized workspace managers."}]},
  {"id":"listLoopDevices","method":"GET","path":"/loop/devices","summary":"List personal Loop devices","description":"Lists safe metadata for the authenticated member's registered devices. Registration usernames, passwords, credential versions, and internal resource identifiers are excluded. Requires `loop:read`.","tag":"Famulor Loop","parameters":[]},
  {"id":"listLoopDirectory","method":"GET","path":"/loop/directory","summary":"List the Loop directory","description":"Lists Loop-enabled workspace members, extensions, and availability. Requires a user-scoped credential with `loop:read` and active Loop access.","tag":"Famulor Loop","parameters":[]},
  {"id":"listLoopNumberRoutes","method":"GET","path":"/loop/number-routes","summary":"List Loop phone number routes","description":"Lists eligible purchased phone numbers and their logical destinations. Requires `loop:read` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[]},
  {"id":"listLoopQueues","method":"GET","path":"/loop/queues","summary":"List Loop call queues","description":"Lists Loop call queues and their enabled workspace members. Requires `loop:read` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[]},
  {"id":"listLoopRecalls","method":"GET","path":"/loop/recalls","summary":"List personal Loop Recall items","description":"Lists only Recall items assigned to the authenticated member. Workspace administrators do not receive other members' Recall items through this personal endpoint. Requires a user-owned credential with `loop:read`.","tag":"Famulor Loop","parameters":[{"name":"status","in":"query","required":false,"type":"string","enum":["action_required","completed","failed","cancelled"]},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listLoopRingGroups","method":"GET","path":"/loop/ring-groups","summary":"List Loop ring groups","description":"Lists Loop ring groups and their enabled workspace members. Requires `loop:read` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[]},
  {"id":"listLoopRoutingRules","method":"GET","path":"/loop/routing-rules","summary":"List Loop routing rules","description":"Lists ordered routing rules with shared weekly hours, time-conditioned steps, and pre-answer continuation outcomes. Requires `loop:read` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[]},
  {"id":"listMeetergoMeetingTypes","method":"POST","path":"/integrations/meetergo/meeting-types","summary":"List meetergo meeting types","description":"Discover enabled meeting types with scheduling access. Supply a token for a new connection or the ID of an existing active integration to reuse its saved credential. Requires a plan with Calendar integrations and either a workspace service-account credential or a user-owned owner/admin credential. Required scope: integrations:read.","tag":"Integrations","parameters":[],"body":{"required":true,"fields":[{"name":"token","required":false,"type":"string","description":"Personal token (rgo-) or platform API key (ak_live:). Omit when reusing a saved integration.","writeOnly":true},{"name":"integration_id","required":false,"type":"string","format":"uuid"},{"name":"acting_user_id","required":false,"type":"string","description":"Required only for platform API keys. Omit for personal tokens.","format":"uuid"}]}},
  {"id":"listMessagingConnectors","method":"GET","path":"/messaging-connectors","summary":"List messaging connectors","description":"List the workspace's messaging channel connections: chat apps, help desks and mailboxes. Each channel must be included in the workspace's plan; `meta.entitlements` shows which channels are available. **Required scope:** `assistants:read`.","tag":"Messaging","parameters":[{"name":"platform","in":"query","required":false,"type":"string","enum":["telegram","slack","messenger","teams","discord","gchat","x","whatsapp","freshdesk","gmail","outlook","zendesk","servicenow","intercom","zoho_mail","agent_mail","instagram","zulip"],"description":"Only return connectors for this channel."}]},
  {"id":"listMessagingConnectorWatchOptions","method":"GET","path":"/messaging-connectors/{id}/watch-options","summary":"List mailbox watch options","description":"List Gmail labels or Outlook/Zoho Mail folders the assistant can watch for this connected mailbox. Use a returned `id` and `name` with PATCH `/messaging-connectors/{id}` (`watch_scope` plus `watch_id` / `watch_name`). Returns `{ supported: false }` for other channels. **Required scope:** `assistants:read`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"listMessengerFacebookPages","method":"POST","path":"/messenger/facebook-login/pages","summary":"List Facebook Pages for a user access token","description":"Server-side Graph API call: lists the Facebook Pages managed by the given user access token, so you can complete Messenger Connect entirely via the API (config → Facebook Login on your own frontend → this endpoint → complete connector). **Required scope:** `assistants:write`. The token is never logged or returned. Complete the connector with the original `access_token` plus the selected `page_id`.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"access_token","required":true,"type":"string","description":"Facebook USER access token obtained via Facebook Login."}]}},
  {"id":"listModels","method":"GET","path":"/models","summary":"List models","description":"Requires the active workspace Fallbacks & Guardrails entitlement in addition to assistants:read. Returns compatible model choices filtered by workspace inference region. Whitelabel access alone does not grant catalog access. Without type, results are grouped by category; with type, results are an array.","tag":"Catalog","parameters":[{"name":"type","in":"query","required":false,"type":"string","enum":["llm","stt","tts","realtime"],"description":"Model category to list."},{"name":"mode","in":"query","required":false,"type":"string","enum":["pipeline","realtime","half_cascade"],"description":"Return only models usable in this engine mode. LLM and Realtime models match through their supported_modes; STT models match pipeline; TTS models match pipeline and half_cascade. Realtime mode lists no STT or TTS models."},{"name":"realtime_variant","in":"query","required":false,"type":"string","enum":["standard","full_duplex"],"default":"standard","description":"Filter native speech model choices by Realtime conversation variant. Full Duplex also requires workspace Beta access and available defaults."}]},
  {"id":"listPasskeys","method":"GET","path":"/settings/passkeys","summary":"List passkeys","description":"Lists the passkeys the user associated with the API credential can sign in with, newest first. Passkeys are added in the app under Settings → Preferences, because that requires the user's device. Only available on the main platform and with a user-owned API key or OAuth token. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"listPerplexityModels","method":"POST","path":"/tools/perplexity/models","summary":"List Perplexity models","description":"Return the current Agent API model catalog using either a supplied Perplexity API key or the securely stored key of an existing connector. Secret keys are never returned. Requires an admin-level credential. **Required scope:** `assistants:write`.","tag":"Tools","parameters":[],"body":{"required":true}},
  {"id":"listPhoneNumbers","method":"GET","path":"/phone-numbers","summary":"List phone numbers","description":"Phone numbers of your workspace, newest first. **Required scope:** `phone_numbers:read` (keys without scope restrictions have full access).","tag":"Phone Numbers","parameters":[{"name":"assistant_id","in":"query","required":false,"type":"string","format":"uuid","description":"Filter by assigned assistant."},{"name":"status","in":"query","required":false,"type":"string","enum":["active","pending","released","suspended"]},{"name":"country","in":"query","required":false,"type":"string","description":"ISO-2 country code, e.g. `DE`."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listPhoneNumberVerificationCatalog","method":"GET","path":"/phone-numbers/verifications/catalog","summary":"List countries requiring number verification","description":"Lists countries and number types that require verification, including the supported business or individual registrations for each type. Use only the combinations in this catalog, then load their current requirements before submitting a case. **Required scope:** `phone_numbers:read`.","tag":"Phone Numbers","parameters":[]},
  {"id":"listPhoneNumberVerifications","method":"GET","path":"/phone-numbers/verifications","summary":"List regulatory number verifications","description":"List regulatory verification cases for the workspace. **Required scope:** `phone_numbers:read`.","tag":"Phone Numbers","parameters":[]},
  {"id":"listPlatformCustomPayments","method":"GET","path":"/platform/custom-payments","summary":"List custom payments across your customers","description":"Lists custom payments across every customer in your scope, newest first. **Required scope:** `platform:read`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"status","in":"query","required":false,"type":"string"},{"name":"kind","in":"query","required":false,"type":"string","enum":["one_time","subscription"]},{"name":"channel","in":"query","required":false,"type":"string","enum":["charge_saved_method","payment_link","invoice"]},{"name":"q","in":"query","required":false,"type":"string","description":"Search the payment description."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":100,"default":25},{"name":"cursor","in":"query","required":false,"type":"string"}]},
  {"id":"listPlatformUserCustomPayments","method":"GET","path":"/platform/users/{user_id}/custom-payments","summary":"List a customer's custom payments","description":"Lists custom payments billed to one customer, newest first, plus create-time context (resolved workspace, currency options, saved payment methods, tax-automation availability). **Required scope:** `platform:read`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"user_id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"workspace_id","in":"query","required":false,"type":"string","format":"uuid","description":"Pick a specific workspace when the customer has several in your scope; defaults to the one they own."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":100,"default":25},{"name":"cursor","in":"query","required":false,"type":"string","description":"Opaque next_cursor from the previous page."},{"name":"sync","in":"query","required":false,"type":"boolean","description":"Refresh non-terminal rows from the billing provider before returning them."}]},
  {"id":"listPlatformUsers","method":"GET","path":"/platform/users","summary":"List platform users","description":"List the customers you can manage through the White-Label Platform API — your reseller workspace's customers, or (for platform admins) direct platform customers. `q` searches name and email (case-insensitive substring). Sorted by `created_at` descending. **Required scope:** `platform:read`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"q","in":"query","required":false,"type":"string","description":"Case-insensitive substring search across name and email."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listPromptTemplates","method":"GET","path":"/prompt-templates","summary":"List prompt templates","description":"System-prompt and conversational-flow templates visible to this workspace: platform templates (respecting global vs root visibility) plus workspace/reseller templates. Use an item's `id` as `template_id` when creating an assistant for server-side resolution. `blueprint` describes the use-case outcome, supported surfaces, setup requirements and presentation. `compatibility` summarizes the validated flow graph. `avatar_url` is only the catalog portrait; avatar-ready blueprint presentation means the assistant is designed for a separately configured virtual speaking avatar. **Required scope:** `assistants:read`.","tag":"Catalog","parameters":[{"name":"language","in":"query","required":false,"type":"string","description":"ISO-639-1 language filter (e.g. `de`)."},{"name":"theme","in":"query","required":false,"type":"string","description":"Use-case theme. Built-in themes: receptionist, lead_qualifier, appointment, support, screener, survey, sales, personal_assistant, callback_intake, property_lead, service_intake, feedback_survey, guest_concierge, avatar_concierge, loop_recall. Templates can also carry custom themes, which filter the same way."},{"name":"branch","in":"query","required":false,"type":"string","description":"Industry branch: general, healthcare, dental, real_estate, home_services, saas, hospitality, legal, automotive, ecommerce, education."},{"name":"q","in":"query","required":false,"type":"string","description":"Search name, description, and content."},{"name":"has_flow","in":"query","required":false,"type":"boolean","description":"When `true`, only templates with a Flow JSON graph. When `false`, only Single-prompt templates (`flow_json` null)."}]},
  {"id":"listQaRuns","method":"GET","path":"/qa/runs","summary":"List QA runs","description":"List cohort AI Quality Assurance runs. **Required scope:** `calls:read`.","tag":"QA","parameters":[]},
  {"id":"listResellerPlans","method":"GET","path":"/reseller/plans","summary":"List customer plans and inclusions","description":"List plans belonging to the credential’s Whitelabel workspace and the available services to include. Requires owner or admin authority, Whitelabel access and settings:read. Wholesale costs and payment-provider identifiers are not returned. Plan prices use EUR minor units.","tag":"White Label","parameters":[]},
  {"id":"listRoutineRuns","method":"GET","path":"/routines/{id}/runs","summary":"List mission runs","description":"Lists this mission's recent runs, most recent first. Run transcripts (visible on the workspace Milian Missions page) are kept for 10 days. **Required scope:** `routines:read` (keys without scope restrictions have full access).","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":100,"default":25,"description":"Maximum number of runs to return (1-100)."}]},
  {"id":"listRoutines","method":"GET","path":"/routines","summary":"List missions","description":"**Required scope:** `routines:read` (keys without scope restrictions have full access).","tag":"Milian Missions","parameters":[]},
  {"id":"listRoutineVersions","method":"GET","path":"/routines/{id}/versions","summary":"List mission versions","description":"Lists drafts and immutable published versions, newest first. **Required scope:** `routines:read`.","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}]},
  {"id":"listScheduledCallbacks","method":"GET","path":"/scheduled-callbacks","summary":"List scheduled callbacks","description":"Callbacks booked by the Schedule callback tool across voice, chat/messaging, and email. Due `pending` rows are dialed automatically by the platform dialer. **Required scope:** `calls:read`.","tag":"Callbacks","parameters":[{"name":"status","in":"query","required":false,"type":"string","enum":["pending","dialing","completed","failed","cancelled"],"description":"Filter by status."},{"name":"search","in":"query","required":false,"type":"string","description":"Filter by phone number or reason (substring match)."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listSegmentLeads","method":"GET","path":"/segments/{id}/leads","summary":"List a segment's leads","description":"Leads currently matching the segment's saved filters, newest first, paginated. Every lead includes the derived `display_status`. Resolution is capped at 5000 matching leads — `meta.pagination.total` reflects that cap, not an unbounded count.\n\n**Required scope:** `segments:read` (`leads:read` and the legacy `calls:read` scope are also accepted; keys without scope restrictions have full access).","tag":"Segments","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Segment ID."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listSegments","method":"GET","path":"/segments","summary":"List segments","description":"List all segments (saved, dynamic lead filters) of the workspace. **Required scope:** `segments:read` (the legacy `calls:read` scope is also accepted; keys without scope restrictions have full access).","tag":"Segments","parameters":[{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listSipTrunks","method":"GET","path":"/sip-trunks","summary":"List SIP trunks","description":"Lists only customer-owned BYO/BYOC SIP trunks. Managed trunks behind marketplace purchases and verified caller IDs are never returned; use the phone-number endpoints for those numbers. Passwords and internal trunk identifiers are never returned. **Required scope:** `sip_trunks:read` (keys without scope restrictions have full access).","tag":"SIP Trunks","parameters":[{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listSupportRequests","method":"GET","path":"/support/requests","summary":"List support requests","description":"Lists the API key user's own support requests in this workspace (newest first, max 30) with live status, priority, the assigned support team member and unread replies. Reseller-customer workspaces are not eligible. **Required scope:** `settings:read`.","tag":"Settings","parameters":[]},
  {"id":"listSuppressionEntries","method":"GET","path":"/suppression-list","summary":"List suppression entries","description":"Lists active marketing suppressions across voice, SMS, email, and supported messaging channels. Results expose the public contact identity, scope, origin channel, source, and consent mode captured at opt-out. **Required scope:** `suppression:read` (keys without scope restrictions have full access).","tag":"Suppression","parameters":[{"name":"search","in":"query","required":false,"type":"string","description":"Filter by phone number, email, identity, or reason (substring match)."},{"name":"channel","in":"query","required":false,"type":"string","description":"Return records that block this channel, including universal (`all`) suppressions.","enum":["voice","sms","email","telegram","slack","messenger","teams","discord","gchat","x","whatsapp","freshdesk","gmail","outlook","zendesk","servicenow","intercom","zoho_mail","agent_mail","instagram","zulip"]},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listTeamMembers","method":"GET","path":"/team-members","summary":"List team members","description":"List the current workspace team. Requires owner or admin access and settings:read.","tag":"Workspaces","parameters":[]},
  {"id":"listToolRuns","method":"GET","path":"/tools/{id}/runs","summary":"List reusable tool runs","description":"Recent executions and statistics over only the returned window. Requires an admin-level credential and assistants:read.","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50}]},
  {"id":"listTools","method":"GET","path":"/tools","summary":"List reusable tools","description":"List the central API, MCP, and built-in Tool Registry. Each item includes its optimistic `revision`, `usage_count`, OAuth connection health, and latest execution result; secret values are masked. **Required scope:** `assistants:read`.","tag":"Tools","parameters":[]},
  {"id":"listToolVersions","method":"GET","path":"/tools/{id}/versions","summary":"List tool versions","description":"Lists immutable, secret-masked tool versions newest first. **Required scope:** `assistants:read`.","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"listTransactions","method":"GET","path":"/transactions","summary":"List transactions","description":"Workspace balance ledger, newest first. `note` contains a customer-facing description; payment-provider IDs and internal reconciliation references are never returned. Zero-amount entries of the automatic telephony cost reconciliation are omitted because they change no balance. **Required scope:** `billing:read` (keys without scope restrictions have full access).","tag":"Billing","parameters":[{"name":"type","in":"query","required":false,"type":"string","enum":["transfer","call_usage","loop_usage","recording_usage","referral","purchase","plan_included","admin_adjust","email_usage","crawl_usage","sla_fee","retranscribe_usage","sms_usage","simulation_usage","reanalyze_usage","card_collect_usage","chat_usage","messaging_usage","qa_usage","automation_usage","milian_usage"],"description":"Filter by transaction type."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."}]},
  {"id":"listTranslationSessions","method":"GET","path":"/translation-sessions","summary":"List translation rooms","description":"List the current user’s hosted rooms. Requires calls:read and a credential belonging to the room host.","tag":"Translation","parameters":[]},
  {"id":"listVariableSources","method":"GET","path":"/variables/catalog","summary":"List campaign variable sources","description":"Lists system variables, workspace lead attributes, and assistant variables available for campaign and WhatsApp template mappings. **Required scope:** `leads:read`.","tag":"Leads","parameters":[]},
  {"id":"listVoiceClones","method":"GET","path":"/voices/clone","summary":"List cloned voices","description":"Lists ready cloned voices owned by the current workspace. Returned IDs are opaque platform IDs. **Required scope:** `voices:read` or `assistants:read`.","tag":"Voices","parameters":[]},
  {"id":"listVoices","method":"GET","path":"/voices","summary":"List voices","description":"Complete paginated voice library for the active workspace. Voice IDs are provider-neutral local selectors; upstream identifiers and supplier names are never returned. Workspace-owned cloned voices use the same selector contract. Use a voice's `id` as `tts_voice` for Pipeline or fallback speech, or `realtime_voice` for native conversation voices. **Required scope:** `voices:read` (keys without scope restrictions have full access).","tag":"Voices","parameters":[{"name":"language","in":"query","required":false,"type":"string","description":"ISO-639-1 language filter, e.g. `de`."},{"name":"gender","in":"query","required":false,"type":"string","enum":["female","male","neutral"]},{"name":"accent","in":"query","required":false,"type":"string","description":"Accent slug filter, e.g. `bavarian`, `american`, `british`."},{"name":"search","in":"query","required":false,"type":"string","description":"Free-text search over name/accent/age."},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":200,"default":50,"description":"Page size (1–200)."},{"name":"offset","in":"query","required":false,"type":"integer","minimum":0,"default":0,"description":"Number of items to skip."},{"name":"mode","in":"query","required":false,"type":"string","enum":["tts","realtime"],"default":"tts","description":"Choose Pipeline/fallback voices or native conversation voices. Full Duplex uses its native voice for greetings, consent and tool announcements."},{"name":"realtime_variant","in":"query","required":false,"type":"string","enum":["standard","full_duplex"],"default":"standard","description":"Native conversation variant when mode is realtime. Full Duplex requires Beta and compatible workspace defaults."}]},
  {"id":"listWhatsAppTemplates","method":"GET","path":"/whatsapp/templates","summary":"List WhatsApp message templates","description":"List HSM templates for the workspace. **Required scope:** `assistants:read`.","tag":"Messaging","parameters":[{"name":"connector_id","in":"query","required":false,"type":"string","format":"uuid"},{"name":"source","in":"query","required":false,"type":"string","enum":["library"],"description":"Set to `library` to list official pre-written utility templates."},{"name":"language","in":"query","required":false,"type":"string","default":"en_US"},{"name":"limit","in":"query","required":false,"type":"integer","minimum":1,"maximum":100,"default":24},{"name":"after","in":"query","required":false,"type":"string","description":"Opaque pagination cursor returned by a previous template-library response."},{"name":"name","in":"query","required":false,"type":"string","description":"Exact official library-template name."}]},
  {"id":"listWidgetConnectors","method":"GET","path":"/widget-connectors","summary":"List web widgets","description":"**Required scope:** `assistants:read`.","tag":"Widgets","parameters":[{"name":"assistant_id","in":"query","required":false,"type":"string","format":"uuid"}]},
  {"id":"listWorkspaces","method":"GET","path":"/workspaces","summary":"List workspaces","description":"List the workspaces visible to the calling credential. For a user-owned API key or OAuth token: every workspace the key owner is a member of within this key's own brand (a reseller customer's key never sees a different reseller's workspaces). A service-account key is a single workspace by construction and only lists itself. The key's own workspace is flagged `current: true`. Switching the active workspace is per-credential — use or mint a key/token bound to the target workspace; this endpoint only lists what is visible. **Required scope:** `settings:read`.","tag":"Workspaces","parameters":[]},
  {"id":"liveCallControl","method":"POST","path":"/calls/{id}/live-control","summary":"Live call control","description":"Supervisor actions on an active call: `listen_token` (join credentials), `whisper` (coach the agent), `end_agent` (mute AI / take-over), or `hangup` (end the call for everyone via room delete). While an inbound caller is still ringing for a free concurrent line, only listening in and `hangup` are available; joining with a microphone (`barge`), `whisper` and `end_agent` return 409 `caller_waiting_for_line`. Requires Live monitoring in the workspace plan. **Required scope:** `calls:write`.","tag":"Calls","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Active call ID."}],"body":{"required":true,"fields":[{"name":"action","required":true,"type":"string","enum":["listen_token","whisper","end_agent","hangup"]},{"name":"text","required":false,"type":"string","description":"Required when action is `whisper`."},{"name":"speak","required":false,"type":"boolean","description":"When whispering, have the agent speak immediately."},{"name":"reason","required":false,"type":"string","description":"Optional reason for `end_agent` or `hangup`."},{"name":"barge","required":false,"type":"boolean","description":"For `listen_token`: join with publish (audible) instead of hidden listen-only."}]}},
  {"id":"loginPlatformUser","method":"POST","path":"/platform/users/login","summary":"Log in a platform user","description":"Authenticates a customer with their email and password and, on success, mints them an access token exactly like `POST /platform/users/{user_id}/token` — use this to build your own login form or custom auth flow on your white-label platform, instead of sending customers to the hosted login page. REST-only: this is the one White-Label Platform API operation with no MCP equivalent, since credentials should never travel through an MCP tool call. Rate-limited per IP + email. Every failure — unknown email, wrong password, or an email outside your scope — returns the exact same generic `401` message, so a caller can never use the response to guess which accounts exist. **Required scope:** `platform:write`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[],"body":{"required":true,"fields":[{"name":"email","required":true,"type":"string","format":"email"},{"name":"password","required":true,"type":"string"}]}},
  {"id":"logoutPlatformUser","method":"POST","path":"/platform/users/{user_id}/logout","summary":"Log out a platform user","description":"Revokes every active API key and OAuth token this customer holds across the workspace(s) in your scope — use it to force a sign-out, for example after an account is compromised or your relationship with this customer ends. Idempotent: calling it again on an already-logged-out customer just returns zero counts. **Required scope:** `platform:write`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"user_id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"lookupBookings","method":"POST","path":"/bookings/lookup","summary":"Look up upcoming bookings","description":"Finds confirmed future bookings of the workspace by invitee identity — the same identity check assistants use before rescheduling or cancelling. Provide at least one of `phone`, `email`, `name`.\n\nA match is only returned when the identity is strong enough: a matching phone number alone is sufficient (`match_basis: \"phone\"`), while `email` and `name` must BOTH match (`match_basis: \"email+name\"`). Phone numbers are compared E.164-tolerantly (leading `00` is treated as `+`, suffix match on the last 8+ digits), email case-insensitively and exactly, names leniently by word tokens.\n\n**Required scope:** `bookings:read` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[],"body":{"required":true}},
  {"id":"managePlatformUserPassword","method":"POST","path":"/platform/users/{user_id}/password","summary":"Set a customer password or send a reset email","description":"Requires platform:write. Use action reset to send a branded reset email. Action set requires an account used exclusively within your platform and sends a security notification. Administrator accounts and accounts with access outside the operator’s platform cannot have their password set. Passwords are never returned.","tag":"White Label","parameters":[{"name":"user_id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"workspace_id","required":true,"type":"string","format":"uuid"},{"name":"action","required":true,"type":"string","enum":["set","reset"]},{"name":"password","required":false,"type":"string","description":"Required for action set.","format":"password","minLength":8,"maxLength":1024,"writeOnly":true}]}},
  {"id":"manageSmsRegistration","method":"POST","path":"/phone-numbers/{id}/sms-registration","summary":"Prepare, check, correct or attach SMS registration","description":"Requires phone_numbers:write. Save truthful business and consent details to receive a price quote. Review checks the same details for common carrier rejection reasons before you pay; it is advisory and stores nothing. Attach reuses the paid approved workspace registration for another eligible number with the same business and messaging purpose, without an extra subscription. Use POST /billing/sms-registration with billing:write to confirm the price and open checkout.","tag":"Phone Numbers","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true}},
  {"id":"manageSmsRegistrationBilling","method":"POST","path":"/billing/sms-registration","summary":"Pay for or cancel SMS registration","description":"Requires billing:write and a user-owned credential of a workspace owner, admin or billing manager; service-account credentials are rejected because a paying user must approve the charge. Checkout returns the secure payment URL for the explicitly approved quote. Cancellation stops renewal at the end of the paid period; it affects every associated number in this workspace.","tag":"Billing","parameters":[],"body":{"required":true}},
  {"id":"mergeAudienceContacts","method":"POST","path":"/leads/{id}/merge","summary":"Merge Audience contacts","description":"Explicitly merge one Audience contact into another. The target contact keeps its id; phone, email, channel identities, calls, and conversations move over. The source contact is removed. This never happens automatically — PATCH/POST on a colliding identity still returns 409. **Required scope:** `leads:write` (legacy `calls:write` is also accepted).","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Contact to keep."}],"body":{"required":true,"fields":[{"name":"from_contact_id","required":true,"type":"string","description":"Contact to merge and remove.","format":"uuid"}]}},
  {"id":"migrateFamulor1","method":"POST","path":"/migrations/famulor","summary":"Preview or import Famulor 1.0 data","description":"Use `action: preview` first to list source resources, mappings and warnings. Use `action: import` with exact selected source IDs to create target resources. The Famulor 1.0 source API key is request-only and is never logged, persisted or returned. Built-in tools are created in the central Tools library and assigned to their source assistant; selected account-scoped HTTP tools are assigned to every assistant imported in the run. Selected knowledge bases are linked to referencing assistants, and `dualplex` maps to Half-cascade. Campaigns and automations are always created as inactive drafts. A source HTTP 403 for plan-gated automations skips that resource family without blocking the rest of the migration. Preview requires one relevant read scope (`assistants:read`, `campaigns:read`, `automations:read`, or `calls:read`). Import requires the matching write scope for every selected resource family; unrestricted keys have full access.","tag":"Migrations","parameters":[],"body":{"required":true}},
  {"id":"migrateProviderAssistants","method":"POST","path":"/migrations/providers","summary":"Preview or import provider assistants","description":"Preview and import inactive assistant shells from Retell AI, Vapi, or Synthflow. The source API key is request-only and is never logged, persisted, or returned. Preview requires `assistants:read`; import requires `assistants:write`. Tools, knowledge content, flows, squads, phone numbers, routing, and credentials are not copied and are returned as manual review items.","tag":"Migrations","parameters":[],"body":{"required":true}},
  {"id":"pauseRoutine","method":"POST","path":"/routines/{id}/pause","summary":"Pause a mission","description":"Pauses the Mission and its trigger without deleting versions or runs. Only workspace owners and admins may pause. **Required scope:** `routines:write`.","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}]},
  {"id":"prepareAssistantAnnouncements","method":"POST","path":"/assistants/{id}/announcements","summary":"Prepare saved announcement audio","description":"Queue missing supported fixed announcements from the assistant’s saved settings. No request body is needed; this operation cannot render an unsaved draft. Matching clips are reused. Returns immediately with background progress; poll GET on this path. Failed or unsupported preparation keeps existing call-time behavior. Saving an assistant also requests preparation. With secondary languages configured, end-call farewell text guides a live message in the caller's current supported language; these farewells are skipped for saved audio. **Required scope:** `assistants:write`.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}]},
  {"id":"previewNaturalLanguageDashboard","method":"POST","path":"/dashboards/{id}/natural-language","summary":"Preview a natural-language dashboard plan","description":"Maps a plain-language request to the approved semantic analytics catalog. This preview never writes data and never accepts SQL, table names, or arbitrary fields. **Required scope:** `dashboards:write` or `calls:write`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."}],"body":{"required":true,"fields":[{"name":"prompt","required":true,"type":"string","minLength":8,"maxLength":1200}]}},
  {"id":"publishRoutineVersion","method":"POST","path":"/routines/{id}/publish","summary":"Publish a mission version","description":"Atomically activates a reviewed draft and its trigger. Only workspace owners and admins may publish. **Required scope:** `routines:write`.","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}],"body":{"required":true,"fields":[{"name":"version_id","required":true,"type":"string","format":"uuid"}]}},
  {"id":"reauthorizeTool","method":"POST","path":"/tools/{id}/reauthorize","summary":"Reauthorize an OAuth MCP tool","description":"Creates a short-lived browser authorization URL for an existing OAuth MCP tool. Completing the flow repairs the same tool id and preserves assignments, allowed tools, settings, and run history. **Required scope:** `assistants:write`.","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"registerPlatformUser","method":"POST","path":"/platform/users","summary":"Register a platform user","description":"Creates a new customer account and workspace on your behalf — a real user plus a fresh workspace scoped under your reseller (or, for platform admins, a new platform root workspace). Returns `409` if the email is already registered anywhere on the platform; the message never reveals whether that account happens to be inside or outside your own scope (anti-enumeration). **Required scope:** `platform:write`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[],"body":{"required":true,"fields":[{"name":"name","required":false,"type":"string"},{"name":"email","required":true,"type":"string","format":"email"},{"name":"mode","required":false,"type":"string","description":"`invite` (default) creates the account without a password — pair it with `POST /platform/users/{user_id}/token` or `.../login` for your own custom auth flow. `password` sets an initial password you choose.","enum":["invite","password"],"default":"invite"},{"name":"password","required":false,"type":"string","description":"Required when `mode` is `password` (min. 8 characters). Ignored otherwise.","minLength":8},{"name":"timezone","required":false,"type":"string"},{"name":"language","required":false,"type":"string","enum":["en","de","fr","es"]}]}},
  {"id":"releasePhoneNumber","method":"DELETE","path":"/phone-numbers/{id}","summary":"Release or delete a phone number","description":"Release a phone number. Paid marketplace numbers are soft-scheduled: the subscription ends at the end of the billing period, the number stays active until then (`release_scheduled_at`), then the number is given up and status becomes `released`. Complimentary plan numbers and unpaid purchases are released immediately. Customer-provided numbers are deleted together with their call routing. **Required scope:** `phone_numbers:write` (keys without scope restrictions have full access).","tag":"Phone Numbers","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Phone number ID."}]},
  {"id":"removeCarrierNumber","method":"DELETE","path":"/carrier-connections/{id}/numbers/{numberId}","summary":"Remove an imported carrier number","description":"Detaches one number at the carrier and removes its platform SIP resources. **Required scope:** `sip_trunks:write`.","tag":"Carrier Connections","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Carrier connection ID."},{"name":"numberId","in":"path","required":true,"type":"string","format":"uuid","description":"Imported phone-number resource ID."}]},
  {"id":"removeCustomDomain","method":"DELETE","path":"/custom-domain","summary":"Remove custom domain","description":"Detaches the workspace custom domain (and any www/apex companion redirect) from the platform, removes it where possible, and disables it for host-based login and branding. **Required scope:** `settings:write` or `assistants:write`. Requires workspace owner/admin role. **Requires the white-label entitlement** (plan add-on `whitelabel`, or a workspace override). Workspaces without it get `403 whitelabel_not_in_plan`, and only workspace owners and admins may call it.","tag":"Settings","parameters":[]},
  {"id":"removeDashboardWidget","method":"DELETE","path":"/dashboards/{id}/widgets/{widgetId}","summary":"Detach a dashboard widget","description":"Detaches the widget from this dashboard; the reusable widget record is retained. **Required scope:** `dashboards:write` or `calls:write`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."},{"name":"widgetId","in":"path","required":true,"type":"string","format":"uuid","description":"Widget ID."}]},
  {"id":"removeSuppressionEntry","method":"DELETE","path":"/suppression-list/{id}","summary":"Restore contact consent","description":"Revokes one active suppression and appends an opt-in audit event; compliance history is not erased. `{id}` accepts the suppression entry ID, an E.164 phone number, or an email address. Prefer the entry ID when a contact has multiple channel-specific records. **Required scope:** `suppression:write`.","tag":"Suppression","parameters":[{"name":"id","in":"path","required":true,"type":"string","description":"Suppression entry ID, URL-encoded E.164 phone number, or URL-encoded email address."}]},
  {"id":"renameAssistantVersion","method":"PATCH","path":"/assistants/{id}/versions/{versionId}","summary":"Rename assistant version","description":"Sets a customer-facing name for a saved version. Send an empty string to clear the custom name. **Required scope:** `assistants:write`.","tag":"Versions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"versionId","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"label","required":true,"type":"string","description":"Custom version name. An empty string clears it.","maxLength":80}]}},
  {"id":"renameLoopDevice","method":"PATCH","path":"/loop/devices/{id}","summary":"Rename a personal Loop device","description":"Updates the customer-facing name of a device owned by the authenticated member. Registration credentials are never returned. Requires `loop:write`.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Loop device ID."}],"body":{"required":true,"fields":[{"name":"label","required":true,"type":"string","minLength":1,"maxLength":80}]}},
  {"id":"replaceAssistant","method":"PUT","path":"/assistants/{id}","summary":"Update an assistant (PUT alias)","description":"Alias of `PATCH /assistants/{id}` — identical behavior (partial update, version snapshot). Kept for clients that only support PUT. Pipeline and Half-cascade assistants are checked against the languages their voice can speak, with `400 invalid_request` on failure. Every language is re-checked when the voice moves to a different voice provider or the engine switches to Pipeline or Half-cascade; otherwise only languages the request adds are checked, so another voice from the same provider and unrelated edits keep the current languages. **Required scope:** `assistants:write`.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}],"body":{"required":true,"description":"Writable assistant fields. Unknown fields are ignored. Non-null engine model overrides require the Fallbacks & Guardrails add-on and are validated against the assistant owner's effective catalog access and engine compatibility. Null resets to the next default level.","fields":[{"name":"name","required":false,"type":"string"},{"name":"tags","required":false,"type":"array","description":"Free-form workspace tags for filtering assistants. Case-insensitive unique; original spelling is kept.","items":{"type":"string","maxLength":40}},{"name":"is_active","required":false,"type":"boolean"},{"name":"system_prompt","required":false,"type":"string"},{"name":"response_by_channel","required":false,"type":"object","description":"Versioned manual response instructions for exact output channels. Omit a channel key to use Automatic. Manual instructions supplement and never replace safety, language, tool, or delivery rules. Requires the workspace's Manual channel responses feature."},{"name":"mode","required":false,"type":"string","description":"Assistant engine: Pipeline, Realtime, Half-cascade, or Translate for a two-person interpreter room. The selected mode must be included in the workspace's current plan.","enum":["pipeline","realtime","half_cascade","translation"]},{"name":"realtime_provider","required":false,"type":"string"},{"name":"realtime_model","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement."},{"name":"realtime_voice","required":false,"type":"string","description":"Compatible native conversation voice. Use a neutral ID returned by the native voice library. Available for Realtime; the chosen variant controls compatibility."},{"name":"llm_provider","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement.","enum":["openai","azure","google","groq","anthropic",null]},{"name":"llm_model","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement."},{"name":"half_cascade_provider","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement."},{"name":"half_cascade_model","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement."},{"name":"llm_temperature","required":false,"type":"number"},{"name":"stt_language","required":false,"type":"string"},{"name":"stt_keyterms","required":false,"type":"array","description":"Speech-recognition glossary for customer, product, and proper names. Plan-gated.","items":{"type":"string","maxLength":100}},{"name":"stt_keyterm_detection_enabled","required":false,"type":"boolean","description":"Beta: automatically detect additional call-local keyterms. Detected terms are not persisted."},{"name":"tts_provider","required":false,"type":"string","enum":["cartesia","elevenlabs","openai","google","azure","fishaudio","deepgram","inworld","rime","xai"]},{"name":"tts_voice","required":false,"type":"string","description":"Pipeline or Half-Cascade speech voice. For Full Duplex, retained only for a Pipeline fallback; greetings, consent and tool announcements use realtime_voice. Uploaded greeting audio retains its recorded voice. Must be able to speak the primary and secondary languages."},{"name":"tts_speed","required":false,"type":"number"},{"name":"tts_emotion","required":false,"type":"array","description":"Legacy array field controlling Dynamic emotions (Expressive Mode) for compatible pipeline and half-cascade voices. Omit on create to enable it when supported. Send [] to disable it or [\"calm\"] to enable it. Realtime speech models handle expression natively.","items":{"type":"string"}},{"name":"tts_style_prompt","required":false,"type":"string","description":"Optional free-text speaking-style instructions for compatible TTS models. Send null to clear the override."},{"name":"elevenlabs_stability","required":false,"type":"number","description":"Voice stability override. Send null to use the voice-provider default.","minimum":0,"maximum":1},{"name":"elevenlabs_similarity","required":false,"type":"number","description":"Voice similarity override. Send null to use the voice-provider default.","minimum":0,"maximum":1},{"name":"elevenlabs_style","required":false,"type":"number","description":"Voice-style exaggeration override. Send null to use the voice-provider default.","minimum":0,"maximum":1},{"name":"elevenlabs_speaker_boost","required":false,"type":"boolean","description":"Speaker-boost override. Send null to use the voice-provider default."},{"name":"affective_dialog","required":false,"type":"boolean","description":"Realtime mode with a Google realtime model only: match the caller's tone with warmer, more expressive speech."},{"name":"turn_detection","required":false,"type":"string","enum":["multilingual_model","english_model","vad","stt"]},{"name":"vad_min_silence_ms","required":false,"type":"integer"},{"name":"vad_threshold","required":false,"type":"number","description":"Voice-detection threshold. Null uses the effective engine default: 0.50 for pipeline and adaptive voice detection, 0.50 for web server VAD, and 0.70 for phone server VAD. This detects speech; it does not filter audio.","minimum":0.1,"maximum":0.9},{"name":"allow_interruptions","required":false,"type":"boolean"},{"name":"min_interruption_duration_ms","required":false,"type":"integer"},{"name":"response_timing","required":false,"type":"string","description":"How quickly the assistant answers once the caller pauses: `snappy` answers right away, `balanced` leaves a short pause, `patient` waits longer for callers who pause mid-sentence. Applies to pipeline mode and adaptive realtime turn handling.","enum":["snappy","balanced","patient"]},{"name":"min_interruption_words","required":false,"type":"integer","description":"Pipeline mode only: ignore barge-ins shorter than this many words, so back-channel sounds like “mhm” don't interrupt the assistant. 0 turns it off; larger values are capped at 10.","minimum":0,"maximum":10},{"name":"noise_cancellation","required":false,"type":"string","enum":["bvc","bvc_telephony","none"]},{"name":"preemptive_generation","required":false,"type":"boolean","description":"Begin response generation before turn confirmation. Effective in pipeline mode only."},{"name":"resume_false_interruption","required":false,"type":"boolean","description":"Resume interrupted output when an apparent interruption produces no transcript during the two-second false-interruption window. Effective in pipeline mode and adaptive realtime turn handling, and only while interruptions are enabled."},{"name":"max_tool_steps","required":false,"type":"integer"},{"name":"first_message","required":false,"type":"string"},{"name":"greeting_mode","required":false,"type":"string","enum":["agent_speaks_first","user_speaks_first"]},{"name":"greeting_allow_interruptions","required":false,"type":"boolean","description":"When true, the caller may barge in during the opening greeting (first message / audio / silence fallback). Default false = play greeting uninterrupted. Separate from allow_interruptions (rest of the call)."},{"name":"ai_speaks_after_silence","required":false,"type":"boolean","description":"When greeting_mode is user_speaks_first: after ai_entry_timeout_sec of initial silence, the assistant speaks (static or dynamic). Default false."},{"name":"silence_greeting_mode","required":false,"type":"string","enum":["static","dynamic"]},{"name":"silence_greeting_message","required":false,"type":"string"},{"name":"ai_entry_timeout_sec","required":false,"type":"integer","minimum":1,"maximum":20},{"name":"pre_call","required":false,"type":"object","description":"iOS/Android Call Screen Handling. Mirrored into flow_json.pre_call when a flow exists."},{"name":"flow_json","required":false,"type":"object","description":"Agent type. Omit or `null` = Single prompt (default). Object = Conversational flow (Flow JSON v1). Seed Start→Agent→End for a basic flow; non-trivial graphs may require the Flow builder feature in the workspace plan. In flow mode, `system_prompt` is the Advanced / base prompt (agent-node text is appended)."},{"name":"recording_enabled","required":false,"type":"boolean","description":"Whether audio recording is enabled for calls handled by this assistant. In PATCH and PUT requests, omitting this field leaves the existing setting unchanged. Saving an explicit boolean (`true` or `false`) updates the setting. Recording calls is independent of Loop recording and voicemail recording; see `/assistants/conversation-quality#consent` for caller consent rules and `/billing/minutes#call-recording` for recording billing."},{"name":"retranscribe_enabled","required":false,"type":"boolean","description":"Enhanced transcription: after the call, the recording is transcribed again with a higher-accuracy engine and shown next to the live transcript. Only takes effect while `recording_enabled` is on. Billed in credits per recorded minute."},{"name":"card_collect_enabled","required":false,"type":"boolean","description":"Allows secure payment card collection (the Collect payment card tool and Flow Collect steps of type `credit_card`). Also needs a connected payment account. Switching it on requires a plan that includes payment card collection; otherwise the request fails with HTTP 403."},{"name":"max_call_duration_sec","required":false,"type":"integer","description":"Maximum call duration in seconds (60–1800). null = unlimited (budget cap still applies).","minimum":60,"maximum":1800},{"name":"inbound_ringing_timeout_sec","required":false,"type":"integer","description":"How long inbound callers hear ringing before the call times out (30–120 s, default 60). If every concurrent line is busy, callers keep ringing within this time until a line frees up.","minimum":30,"maximum":120},{"name":"outbound_ringing_timeout_sec","required":false,"type":"integer","description":"How long outbound SIP/WhatsApp calls ring before no-answer (15–80 s, default 45).","minimum":15,"maximum":80},{"name":"amd_enabled","required":false,"type":"boolean","description":"Answering machine detection on direct outbound calls (dashboard, API, automations, callbacks). New assistants default to `false`: the assistant greets as soon as the call is answered and mailboxes are not detected. Campaign calls use the campaign's `amd_enabled`.","default":false},{"name":"voicemail_enabled","required":false,"type":"boolean","description":"What a direct outbound call does at a detected mailbox: `true` = speak `voicemail_message`, then hang up; `false` = hang up without a message. Takes effect while `amd_enabled` is on. Campaign calls use the campaign's voicemail settings.","default":false},{"name":"voicemail_message","required":false,"type":"string","description":"Message spoken onto a detected mailbox when `voicemail_enabled` is `true`; supports `{{variables}}`. `null` or empty = the greeting / first message is used."},{"name":"idle_timeout_sec","required":false,"type":"integer"},{"name":"transcription_timeout_sec","required":false,"type":"number","description":"Seconds after VAD detects speech with no STT transcript before asking the caller to repeat. null disables.","minimum":1,"maximum":30},{"name":"knowledgebase_id","required":false,"type":"string","format":"uuid"},{"name":"knowledge_gap_mode","required":false,"type":"string","enum":["off","questions_only","draft_for_review","tentative_live"]},{"name":"webhook_url","required":false,"type":"string","description":"Agent-level post-call webhook URL."},{"name":"webhook_timeout_sec","required":false,"type":"integer","minimum":1,"maximum":30},{"name":"webhook_retries","required":false,"type":"integer","minimum":0,"maximum":5},{"name":"webhook_delivery_mode","required":false,"type":"string","description":"none = do not deliver; custom = POST the assistant webhook URL after the call; automation = deliver through the bound automation.","enum":["none","custom","automation"]},{"name":"automation_id","required":false,"type":"string","description":"Bound automation when webhook delivery is automation.","format":"uuid"},{"name":"notification_settings","required":false,"type":"object","description":"Activity notifications for this assistant, keyed by History channel (`call`, `avatar`, `live_chat`, `whatsapp_voice`, `whatsapp`, `telegram`, `slack`, `messenger`, `teams`, `discord`, `gchat`, `x`, `freshdesk`, `gmail`, `outlook`, `zendesk`, `servicenow`, `intercom`, `zoho_mail`, `agent_mail`, `instagram`, `zulip`, `email`; the legacy key `messaging` applies to every messaging channel). Each channel takes `email` and `push` toggles. A missing channel or toggle stays on; set it to `false` to opt out. Unknown keys are dropped."},{"name":"metadata","required":false,"type":"object"},{"name":"outbound_phone_number_id","required":false,"type":"string","description":"Workspace phone number this assistant calls from on outbound calls (an `id` from `GET /phone-numbers`). Several assistants can share one number. A `phone_number_id` passed when starting a call takes precedence. A number from another workspace or a released number returns HTTP 404. Null clears it.","format":"uuid"},{"name":"background_audio","required":false,"type":"object","description":"BackgroundAudioPlayer config (`ambient`, `ambient_volume`, `thinking`, `thinking_volume`). `{}` = off. Hold music is configured on the warm-transfer tool, not here."},{"name":"adaptive_interruptions","required":false,"type":"boolean"},{"name":"realtime_turn_mode","required":false,"type":"string","description":"Realtime turn handling: robust voice activity, semantic completion, or adaptive barge-in.","enum":["server_vad","semantic","adaptive"]},{"name":"realtime_eagerness","required":false,"type":"string","description":"How quickly the assistant responds when realtime_turn_mode is semantic.","enum":["auto","low","medium","high"]},{"name":"long_call_memory","required":false,"type":"string","description":"Pipeline mode only: context strategy once a call runs long. `full` keeps the whole conversation in context; `recent` keeps the latest part in focus for faster responses on calls of 10+ minutes.","enum":["full","recent"]},{"name":"idle_messages","required":false,"type":"array","description":"Fixed re-engagement phrases on caller inactivity; `[]` = LLM-generated.","items":{"type":"string"}},{"name":"idle_max_rounds","required":false,"type":"integer","description":"Unanswered idle check-ins before the assistant says goodbye and ends the call (1–10, default 2).","minimum":1,"maximum":10},{"name":"fallback_config","required":false,"type":"object","description":"Requires Fallbacks & Guardrails. Saved fallback configuration is omitted from responses without this workspace entitlement."},{"name":"fallbacks_enabled","required":false,"type":"boolean","description":"Turns on platform-managed model fallbacks, so a call continues on a backup model if a speech or language model fails. Must be a boolean. Switching it on requires Fallbacks & Guardrails; otherwise the request fails with HTTP 403."},{"name":"pronunciation_map","required":false,"type":"object"},{"name":"tts_filter_markdown","required":false,"type":"boolean"},{"name":"tts_filter_emoji","required":false,"type":"boolean"},{"name":"consent_enabled","required":false,"type":"boolean"},{"name":"consent_text","required":false,"type":"string"},{"name":"consent_mode","required":false,"type":"string"},{"name":"consent_decline_action","required":false,"type":"string","description":"What happens when the caller declines consent: `no_recording` continues the call without recording, `hangup` says a farewell and ends the call.","enum":["no_recording","hangup"]},{"name":"consent_decline_text","required":false,"type":"string","description":"Custom farewell spoken before the call ends when the caller declines consent and `consent_decline_action` is `hangup`. Null or empty uses the default farewell for the assistant's language."},{"name":"consent_covers_recording","required":false,"type":"boolean"},{"name":"consent_covers_memory","required":false,"type":"boolean"},{"name":"guardrails","required":false,"type":"object"},{"name":"language_voices","required":false,"type":"object","description":"Per-language voice overrides for Pipeline/Half-cascade. Languages without an entry keep the main voice. A private per-language clone is allowed only when the main voice is also a workspace-owned private clone that uses the same provider runtime. Keys must be languages the voice can speak."},{"name":"auto_language_switch","required":false,"type":"boolean","description":"Automatic response-language switching; derived from secondary_languages by the dashboard."},{"name":"output_volume","required":false,"type":"number"},{"name":"speaking_rate","required":false,"type":"number"},{"name":"text_only_enabled","required":false,"type":"boolean"},{"name":"memory_enabled","required":false,"type":"boolean"},{"name":"memory_mode","required":false,"type":"string","description":"`inherit` follows the workspace memory default; `on`/`off` override it.","enum":["inherit","on","off"]},{"name":"memory_scope","required":false,"type":"string","description":"`workspace` = one summary shared across assistants; `assistant` = one summary private to this assistant; `both` = two complete summaries, one shared and one assistant-private.","enum":["workspace","assistant","both"]},{"name":"lead_attribute_mode","required":false,"type":"string","description":"`all` is an immutable compatibility state for an assistant that already had unrestricted contact-field access. Creating with `all` or changing `selected` to `all` returns HTTP 400. `selected` exposes only explicit `source: lead` definitions.","enum":["all","selected"]},{"name":"memory_read_channels","required":false,"type":"array","description":"Per-assistant read allowlist intersected with workspace policy. Send [] to disable reads.","items":{"type":"string","description":"Memory channels. Web Chat and Web Voice require a current verified widget email or phone and memory consent. Web and SMS memory require a root workspace. Legacy web configuration expands to both web channels; anonymous sessions remain excluded.","enum":["voice","sms","whatsapp","email","web","telegram","slack","messenger","teams","discord","gchat","x","freshdesk","gmail","outlook","zendesk","servicenow","intercom","zoho_mail","agent_mail","instagram","zulip","web_chat","web_voice"]}},{"name":"memory_write_channels","required":false,"type":"array","description":"Per-assistant write allowlist intersected with workspace policy. Send [] to disable writes.","items":{"type":"string","description":"Memory channels. Web Chat and Web Voice require a current verified widget email or phone and memory consent. Web and SMS memory require a root workspace. Legacy web configuration expands to both web channels; anonymous sessions remain excluded.","enum":["voice","sms","whatsapp","email","web","telegram","slack","messenger","teams","discord","gchat","x","freshdesk","gmail","outlook","zendesk","servicenow","intercom","zoho_mail","agent_mail","instagram","zulip","web_chat","web_voice"]}},{"name":"memory_categories","required":false,"type":"array","description":"Allowed summary categories. Send [] for metadata-only memory with no new content summary.","items":{"type":"string","enum":["identity","preferences","agreements","open_items"]}},{"name":"redact_pii","required":false,"type":"boolean","description":"When true, apply `pii_redaction` entity filters to stored transcripts."},{"name":"pii_redaction","required":false,"type":"object","description":"PII entity categories + optional custom regexes."},{"name":"analysis_config","required":false,"type":"object","description":"Post-conversation sentiment, success and structured extraction for voice, chat, messaging and email. Results retain native JSON types in History, webhooks, the public API and MCP."},{"name":"qa_scorecard_config","required":false,"type":"json","description":"AI QA scorecard configuration (requires AI QA Scorecards in the workspace plan). `null` or `enabled: false` disables scoring."},{"name":"timezone","required":false,"type":"string","description":"IANA timezone of the assistant (e.g. `Europe/Berlin`, default). Anchors the `get_current_time` system tool, the `{{time}}`/`{{date}}`/`{{datetime}}`/`{{weekday}}` system variables, and the `check_business_hours` built-in tool. On campaign calls the campaign's timezone overrides it per call."},{"name":"primary_language","required":false,"type":"string","description":"Language the assistant answers in by default (ISO 639-1 or ISO 639-3, see `GET /languages`). Pipeline and Half-cascade: must be a language the assistant's voice can speak. If you omit `tts_voice` when creating, a default voice that speaks this language is chosen."},{"name":"secondary_languages","required":false,"type":"array","description":"Languages the assistant may switch to when the caller clearly speaks them (ISO 639-1 or ISO 639-3). Non-empty implies multilingual STT + auto language switch. Each language must be speakable by the assistant's voice (Pipeline and Half-cascade); otherwise the request fails with `invalid_request`.","items":{"type":"string"}},{"name":"variables","required":false,"type":"array","description":"Custom variable definitions, referenced as `{{key}}` and resolved per call (explicit call values > inbound enrichment > current contact values > remembered value > default_value). Each custom definition can be call-only, workspace-shared, or assistant-private.","items":{"type":"object"}},{"name":"variable_webhook_url","required":false,"type":"string","description":"Optional webhook called on inbound calls to enrich variable values before the conversation starts."},{"name":"variable_webhook_secret","required":false,"type":"string","description":"Secret used to sign variable webhook requests (HMAC-SHA256 of the raw body, sent as `X-Famulor-Signature: sha256=<hex>`). Write-only: never returned. Null clears it.","writeOnly":true},{"name":"builtin_tools","required":false,"type":"array","description":"Inline built-in tool configurations (also accepted as `tools` for compatibility). DTMF Input and Collect Keypad Input run as prompt-session tools here; dedicated Flow nodes bind their reusable central-tool equivalents.","items":{"type":"object","description":"One built-in tool configuration. `type` selects the tool; the remaining fields depend on the type. DTMF Input sends keypad tones to an IVR or phone menu; Collect Keypad Input collects keypad or spoken digits from the caller. In an assistant's inline `builtin_tools` they run as prompt-session tools. Reusable copies created through the Tools API can also be assigned to assistants and bound to their dedicated Flow Builder nodes. Calendars use Integrations. All types accept an optional `description` that tells the model when to use the tool. Saved caller-facing announcements, filler phrases and end-call farewells remain editable. With secondary languages configured on the assistant, they guide generated wording in the current supported conversation language without fixed saved audio. Otherwise their existing delivery behavior is preserved. An empty End call farewell adds no speech."}},{"name":"translation_config","required":false,"type":"object"},{"name":"realtime_variant","required":false,"type":"string","description":"Realtime conversation variant. Full Duplex requires workspace Beta features, Realtime plan access and compatible defaults available in the selected workspace region; extra credits may apply. Its reasoning model is managed centrally. Existing assistants use standard.","enum":["standard","full_duplex"]}]}},
  {"id":"replaceAudienceContactChannels","method":"PUT","path":"/leads/{id}/channels","summary":"Replace contact channels","description":"Replace the contact's manually managed channel profiles. For Microsoft Teams, provide the visible `connection_name`; it may be omitted only when exactly one Teams identity connection is active. Active Teams connection names are unique within a workspace, and reconnected copies of the same Microsoft identity are normalized to one current connection name. A user identity already linked to another contact returns a conflict and never merges records. **Required scope:** `leads:write` (legacy `calls:write` is also accepted).","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Audience contact ID."}],"body":{"required":true,"fields":[{"name":"channels","required":true,"type":"array","items":{"type":"object","description":"At least one identity field (user ID, username, display name, or attribute) must be non-empty. Email is managed through the contact's email field and is not accepted here."}}]}},
  {"id":"replyToSupportRequest","method":"POST","path":"/support/requests/{reference}/messages","summary":"Reply to a support request","description":"Sends a reply to the support team. Replying to a resolved request reopens it. **Required scope:** `settings:write`.","tag":"Settings","parameters":[{"name":"reference","in":"path","required":true,"type":"string"}],"body":{"required":true,"fields":[{"name":"message","required":true,"type":"string","minLength":1,"maxLength":8000},{"name":"client_message_id","required":true,"type":"string","description":"Unique UUID for this reply.","format":"uuid"}]}},
  {"id":"requestAssistantComplianceReview","method":"POST","path":"/assistants/{id}/compliance-review","summary":"Request manual compliance review","description":"Submits the current blocked assistant snapshot for manual platform review. **Required scope:** `assistants:write`.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}],"body":{"required":true,"fields":[{"name":"reason","required":true,"type":"string","description":"Why the current assistant content should be approved.","minLength":10,"maxLength":2000}]}},
  {"id":"requestOutboundLimitIncrease","method":"POST","path":"/settings/outbound-limits/requests","summary":"Request an outbound call limit increase","description":"Submits a workspace-wide increase request for review. Only workspace owners and admins can submit a request, and only one request can be pending at a time. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"requested_daily_limit","required":true,"type":"json","description":"Requested number of integrated outbound calls per workspace day, or -1 to request unlimited calls."},{"name":"reason","required":true,"type":"string","minLength":1,"maxLength":2000},{"name":"business_website","required":false,"type":"string","format":"uri","maxLength":2048}]}},
  {"id":"rescheduleBooking","method":"POST","path":"/bookings/{id}/reschedule","summary":"Reschedule a booking","description":"Moves a confirmed booking to a new start time. The new slot is validated against the event type's availability (the booking's own slot does not block itself), unless `allow_outside_availability` is true (staff override: any future time within 2 years that does not overlap a confirmed booking of the same event type); a lost race for the slot returns `409`. Sends an updated ICS invitation to the invitee and re-pushes the external calendar event (both best-effort).\n\n**Required scope:** `bookings:write` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Booking ID"}],"body":{"required":true,"fields":[{"name":"start","required":true,"type":"string","description":"New start time in ISO 8601 UTC. The duration stays the one of the event type.","format":"date-time"},{"name":"allow_outside_availability","required":false,"type":"boolean","description":"Set true to book outside the event type's open times (staff override). Any future time within the next 2 years is accepted; the time must not overlap another confirmed booking of the same event type. Guests on the public booking page only ever see open times.","default":false}]}},
  {"id":"restoreAssistantVersion","method":"POST","path":"/assistants/{id}/versions/{versionId}/restore","summary":"Restore assistant version","description":"Restores snapshot; current config is auto-snapshotted first. A restore goes through the same validation as `PATCH /assistants/{id}`: it is rejected with `400 invalid_request` when the restored voice can't speak the restored languages (Pipeline and Half-cascade). **Required scope:** `assistants:write`.","tag":"Versions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"versionId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"restoreToolVersion","method":"POST","path":"/tools/{id}/versions/{revision}/restore","summary":"Restore a tool version","description":"Restores a historical snapshot as a new revision. **Required scope:** `assistants:write`.","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"revision","in":"path","required":true,"type":"integer","minimum":1}],"body":{"required":true,"fields":[{"name":"expected_revision","required":true,"type":"integer","minimum":1}]}},
  {"id":"retryRoutineRun","method":"POST","path":"/routines/{id}/runs/{runId}/retry","summary":"Retry a mission run","description":"Explicitly starts a new run linked to the finished source run. The source run and its immutable published version stay unchanged; no automatic retry is scheduled. **Required scope:** `routines:write`.","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."},{"name":"runId","in":"path","required":true,"type":"string","format":"uuid","description":"Finished Mission run ID."}]},
  {"id":"reviewSubscriptionPaymentChange","method":"POST","path":"/billing/subscription-change/review","summary":"Review subscription change","description":"Reviews an existing subscription change without submitting the change or charging a card. Provide the complete desired plan and add-on selection. Returns estimated tax, the amount due, masked eligible methods and short-lived references. This operation does not create new subscriptions or checkouts. Resolve pending invoices in the app before requesting another review. Requires a user-owned credential with billing:write scope and owner, admin or billing access in the active workspace. API Access must be enabled.","tag":"Billing","parameters":[],"body":{"required":true,"fields":[{"name":"plan_id","required":false,"type":"string","description":"Target plan. Omit only for an add-on-only subscription.","format":"uuid"},{"name":"addon_ids","required":true,"type":"array","description":"Complete desired add-on selection, including every add-on to keep.","items":{"type":"string","format":"uuid"}},{"name":"addon_quantities","required":false,"type":"object"},{"name":"interval","required":true,"type":"string","enum":["monthly","yearly"]}]}},
  {"id":"revokeApiKey","method":"DELETE","path":"/api-keys/{id}","summary":"Revoke an API key","description":"Revokes (soft-deletes) an API key. Idempotent — revoking an already-revoked key still returns `200 { revoked: true }`. **Required scope:** `settings:write`.","tag":"API Keys","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"revokeLoopDevice","method":"DELETE","path":"/loop/devices/{id}","summary":"Revoke a personal Loop device","description":"Revokes a device owned by the authenticated member. The operation is tenant-scoped and requires `loop:write`.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Loop device ID."}]},
  {"id":"runAssistantTest","method":"POST","path":"/assistants/{id}/tests/{testId}/run","summary":"Run simulation test","description":"Run a chat simulation synchronously (up to ~60s). Linked knowledge bases are searched through real function calls; successful and failed searches are included in tool_calls. Other tools remain simulated and perform no external actions. Voice mode starts a real call asynchronously. **Required scope:** `assistants:write`; voice mode additionally requires `calls:write`.","tag":"Simulations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"testId","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"runAutomationAiAction","method":"POST","path":"/automations/ai-actions","summary":"Preview or run a Milian AI automation action","description":"Requires automations:write. dry_run=true is a free configuration preview. Set false explicitly to run analysis and charge workspace credits. Each live invocation is a separate paid request. Uncertain answers have null values. Technical failures return success=false. Also available as run_automation_ai_action over MCP. Save the same action/config in a graph using POST or PATCH /automations/{id}.","tag":"Automations","parameters":[],"body":{"required":true,"fields":[{"name":"action","required":true,"type":"string","enum":["ai.classify","ai.check_condition","ai.score","ai.detect_labels","ai.analyze"]},{"name":"config","required":true,"type":"object"},{"name":"context","required":false,"type":"object"},{"name":"dry_run","required":false,"type":"boolean","default":true}]}},
  {"id":"runCallActions","method":"POST","path":"/calls/actions","summary":"Run call history actions","description":"Re-evaluate post-call analysis, start an enhanced re-transcription from one call recording, resend `call.completed` webhooks, or add/remove the contact phone from the suppression (blacklist) list. `retranscribe` requires exactly one call ID and returns the rounded recording minutes and credit quote. Other actions process up to 50 call IDs per request. **Required scope:** `calls:write`. Blacklist actions also need `suppression:write` or `campaigns:write` (unrestricted keys have full access).","tag":"Calls","parameters":[],"body":{"required":true,"fields":[{"name":"action","required":true,"type":"string","enum":["reanalyze","retranscribe","resend_webhook","blacklist_add","blacklist_remove"]},{"name":"call_ids","required":true,"type":"array","items":{"type":"string","format":"uuid"}}]}},
  {"id":"runCrawlSource","method":"POST","path":"/knowledge-bases/{id}/crawl-sources/{sourceId}/run","summary":"Run a crawl now","description":"Crawl a website source immediately (synchronous). Fetches pages under the root URL, re-indexes changed pages (unchanged pages are skipped via content hash — no re-embedding, no credits) and charges credits per crawled page. Aborts gracefully when the account runs out of credits (partial results kept, `status` = `error`, `error` = `insufficient credits`). **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"sourceId","in":"path","required":true,"type":"string","format":"uuid","description":"Crawl source ID."}]},
  {"id":"runCrmSync","method":"POST","path":"/crm-syncs/{id}/runs","summary":"Run CRM sync","description":"Queue a durable manual CRM sync run. Requires `automations:write` or `calls:write`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"CRM sync ID."}]},
  {"id":"runDriveSource","method":"POST","path":"/knowledge-bases/{id}/drive-sources/{sourceId}/run","summary":"Run a cloud drive sync now","description":"Sync a cloud drive source immediately (synchronous). Lists files under the folder (optionally recursive), re-indexes new/changed files (unchanged files are skipped via content hash — no re-embedding, no credits), removes documents whose file no longer exists in the folder, and charges credits per new/changed file. Aborts gracefully when the account runs out of credits (partial results kept, `status` = `error`, `error` = `insufficient credits`). **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"sourceId","in":"path","required":true,"type":"string","format":"uuid","description":"Drive source ID."}]},
  {"id":"runHistoryActions","method":"POST","path":"/history/actions","summary":"Run history actions on any channel","description":"Cross-channel superset of `POST /calls/actions`. Re-evaluate the post-conversation analysis (summary, sentiment, success verdict and extracted fields), start an enhanced re-transcription from a call recording, resend the end-of-conversation webhook, reopen a completed WhatsApp conversation with AI auto-replies, or add/remove the contact phone from the suppression (blacklist) list.\n\nSet `kind` to select the record type:\n\n- `call` — phone calls, live chat, avatar sessions and WhatsApp voice (`ids` are call IDs)\n- `messaging` — WhatsApp, Telegram, Slack, Messenger, Teams, Discord, Google Chat and X conversations (`ids` are conversation IDs)\n- `email` — email threads (`ids` are the thread's root message ID, which is what `GET /history` returns as the row `id`)\n\n`retranscribe` is only valid for `kind: call`, requires exactly one ID, and returns the rounded recording minutes plus the credit quote. `resend_webhook` always rebuilds the payload from the record as it is stored right now, so a resend after a `reanalyze` delivers the updated analysis. `resume_ai` is only valid for `kind: messaging` and only while a completed WhatsApp conversation's 24-hour customer service window is still open. It starts a fresh internal inactivity timer without extending the Meta window. `blacklist_add` and `blacklist_remove` are phone-based and therefore only valid for `kind: call`.\n\nOther actions process up to 50 IDs per request. **Required scope:** `calls:write`. Blacklist actions also need `suppression:write` or `campaigns:write` (unrestricted keys have full access).\n\n`remove` removes a completed conversation from History, call/history list and detail APIs, and MCP reads without immediately erasing stored data. It preserves billing, usage and statistics. Existing workspace retention rules continue to apply using the original timestamps. Active conversations cannot be removed. An email message ID removes its entire thread. Retries are idempotent. User-owned credentials require workspace owner/admin access; workspace service-account credentials require `calls:write`. Check each per-record result: active or missing records return `ok: false`. Previously issued download links and exported copies are not revoked. A new incoming email or messaging reply restores thread visibility; historical imports and outbound messages do not.","tag":"History","parameters":[],"body":{"required":true,"fields":[{"name":"action","required":true,"type":"string","enum":["remove","reanalyze","retranscribe","resend_webhook","resume_ai","blacklist_add","blacklist_remove"]},{"name":"kind","required":true,"type":"string","description":"Which History record type the ids address.","enum":["call","messaging","email"]},{"name":"ids","required":true,"type":"array","items":{"type":"string","format":"uuid"}}]}},
  {"id":"runPlatformCustomPaymentAction","method":"POST","path":"/platform/custom-payments/{payment_id}","summary":"Run an action on a custom payment","description":"Runs an action on an existing custom payment: refresh, resend_notification, cancel, cancel_at_period_end, mark_uncollectible, or deactivate_link. **Required scope:** `platform:write`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"payment_id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"action","required":true,"type":"string","enum":["refresh","resend_notification","cancel","cancel_at_period_end","mark_uncollectible","deactivate_link"]},{"name":"immediately","required":false,"type":"boolean","description":"cancel action on a subscription only: true cancels now, false/omitted schedules cancellation at period end."}]}},
  {"id":"runRoutine","method":"POST","path":"/routines/{id}/run","summary":"Run a mission now","description":"Starts a background run of this mission right now, independent of its schedule, billed like a normal copilot chat turn. Returns the created run immediately; the run itself keeps executing in the background — poll `GET /routines/{id}/runs` for its outcome. **Required scope:** `routines:write` (keys without scope restrictions have full access).","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}]},
  {"id":"runWhatsAppCallingAction","method":"POST","path":"/whatsapp/calling","summary":"Enable / resubscribe WhatsApp calling","description":"Actions: `enable_calling` (enable inbound calling in Meta call settings), `resubscribe` (re-subscribe the WABA webhook with this connector's callback URL), `ensure_voice` (best-effort resubscribe + enable, used when Voice is turned on). **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"connector_id","required":true,"type":"string","format":"uuid"},{"name":"action","required":true,"type":"string","enum":["enable_calling","resubscribe","ensure_voice"]}]}},
  {"id":"saveNaturalLanguageDashboard","method":"PUT","path":"/dashboards/{id}/natural-language","summary":"Save a natural-language dashboard plan","description":"Revalidates a previewed semantic plan and saves it as regular reusable dashboard widgets. Client-provided metric, filter, grouping, and visualization values are checked against the same server catalog again before any write. **Required scope:** `dashboards:write` or `calls:write`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."}],"body":{"required":true,"fields":[{"name":"plan","required":true,"type":"object","description":"Versioned, tenant-safe dashboard plan built exclusively from the semantic analytics catalog."}]}},
  {"id":"searchAvailablePhoneNumbers","method":"GET","path":"/phone-numbers/available","summary":"Search purchasable numbers","description":"Searches the marketplace for purchasable numbers, including the workspace's final customer-facing retail price and a short-lived `purchase_token` required to buy that exact offer. The country and number type must be enabled by the platform admin; countries with regulatory requirements additionally need an approved regulatory bundle on file. **Required scope:** `phone_numbers:read` (keys without scope restrictions have full access).","tag":"Phone Numbers","parameters":[{"name":"country","in":"query","required":true,"type":"string","description":"ISO-2 country code, e.g. `DE`."},{"name":"type","in":"query","required":false,"type":"string","enum":["local","mobile","national"],"description":"Number type to search. Omit it to search every type enabled for the country; each result reports its own `type`."},{"name":"contains","in":"query","required":false,"type":"string","description":"Digit pattern the number must contain, e.g. `030`."},{"name":"area_code","in":"query","required":false,"type":"integer","description":"Area code filter, e.g. `415`."}]},
  {"id":"searchKnowledgeBase","method":"POST","path":"/knowledge-bases/{id}/search","summary":"Search knowledge or query a table","description":"Search document excerpts and exact table values with original cells and sources. Send either `query` (natural-language question) or `table_query` (exact lookup or aggregate on one sheet). Table queries evaluate complete sheets, independent of search limits. Cached formulas are unverified; ambiguous or missing numeric values and mixed units are rejected by aggregates. **Required scope:** `knowledge:read` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."}],"body":{"required":true,"description":"Send `query` or `table_query`. If both are present, only `table_query` is evaluated."}},
  {"id":"sendSms","method":"POST","path":"/sms/send","summary":"Send an SMS","description":"Send an outbound SMS from a workspace phone number that has outbound SMS enabled (platform marketplace or Twilio BYOC). US 10DLC senders must be registered with an approved A2P campaign in Twilio. Platform numbers charge SMS credits including carrier pass-through; BYOC charges only the platform SMS fee (customer pays Twilio carrier cost). **Required scope:** `phone_numbers:write`.","tag":"SMS","parameters":[],"body":{"required":true,"fields":[{"name":"from_number_id","required":true,"type":"string","description":"ID of an SMS-capable phone number with outbound SMS enabled.","format":"uuid"},{"name":"to","required":true,"type":"string","description":"Recipient in E.164 format."},{"name":"body","required":true,"type":"string","description":"Message body.","minLength":1,"maxLength":1600}]}},
  {"id":"setAssistantAvatar","method":"POST","path":"/assistants/{id}/avatar","summary":"Set assistant picture","description":"Uploads a custom picture shown in the product UI instead of the default orb. Send JSON `{ \"url\": \"https://…/avatar.png\" }` (downloaded server-side), `{ \"data_base64\": \"…\", \"content_type\": \"image/png\" }`, or multipart/form-data with a `file` field. Formats PNG/JPEG/WebP, max 1 MB incoming (server compresses to ≤512×512 / ~400 KB). Not writable via PATCH.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","description":"Assistant id."}],"body":{"required":true}},
  {"id":"setAssistantGreetingAudio","method":"POST","path":"/assistants/{id}/greeting-audio","summary":"Set audio first message","description":"Uploads an audio greeting played verbatim at call start instead of TTS. Send JSON `{ \"url\": \"https://…/greeting.mp3\" }` (downloaded server-side) or multipart/form-data with a `file` field. Formats mp3/wav/ogg/m4a, max 5 MB. `first_message` remains the transcript / chat / voicemail fallback.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","description":"Assistant id."}],"body":{"required":true,"fields":[{"name":"url","required":true,"type":"string","description":"Public http(s) URL of the audio file to download.","format":"uri"}]}},
  {"id":"setAssistantIntegrations","method":"PUT","path":"/assistants/{id}/integrations","summary":"Replace assistant integrations","description":"REPLACE the integration assignments of an assistant with the given set. Pass an empty array to remove all assignments (possible even after a plan downgrade); assigning requires a plan that includes calendar integrations. Requires a user-owned credential of a workspace owner or admin; workspace service-account credentials get `403`.\n\n**Required scope:** `integrations:write` or `assistants:write` (keys without scope restrictions have full access).","tag":"Integrations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID"}],"body":{"required":true,"fields":[{"name":"integration_ids","required":true,"type":"array","description":"Complete target set of integration IDs.","items":{"type":"string","format":"uuid"}}]}},
  {"id":"setAssistantTools","method":"PUT","path":"/assistants/{id}/tools","summary":"Replace assigned tools","description":"Atomically replace the assistant's complete tool set. `expected_revision` prevents overwriting concurrent assignment changes. **Required scope:** `assistants:write`.","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}],"body":{"required":true,"fields":[{"name":"tool_ids","required":true,"type":"array","description":"Complete target set of tool IDs to assign.","items":{"type":"string","format":"uuid"}},{"name":"expected_revision","required":true,"type":"integer","description":"Toolset revision returned by GET /assistants/{id}/tools.","minimum":1}]}},
  {"id":"setLoopNumberRoute","method":"PUT","path":"/loop/number-routes/{id}","summary":"Set a Loop phone number route","description":"Sets the logical destination for an eligible purchased phone number. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}],"body":{"required":true,"fields":[{"name":"target_type","required":true,"type":"string","enum":["member","extension","ring_group","queue","routing_rule","assistant"]},{"name":"target_id","required":true,"type":"string","format":"uuid"}]}},
  {"id":"setLoopPresence","method":"PATCH","path":"/loop/presence","summary":"Set personal Loop presence","description":"Updates the authenticated member's availability. Active calls continue to determine the effective busy state. Requires `loop:write`.","tag":"Famulor Loop","parameters":[],"body":{"required":true,"fields":[{"name":"status","required":true,"type":"string","enum":["available","busy","do_not_disturb","offline"]}]}},
  {"id":"setLoopRecording","method":"POST","path":"/loop/recording","summary":"Start or stop Loop recording","description":"Start or stop recording the selected active Loop call. Requires loop:write, a user-owned credential and permission to control this call. Recording uses workspace credits. Reuse the same idempotency key only when retrying the same action; use a new key for the next separate action. Active recordings may be paused and resumed; paused time is excluded from recorded duration. The response confirms the current state.","tag":"Famulor Loop","parameters":[],"body":{"required":true,"fields":[{"name":"call_id","required":true,"type":"string","format":"uuid"},{"name":"action","required":true,"type":"string","enum":["start","stop"]},{"name":"idempotency_key","required":true,"type":"string","format":"uuid"}]}},
  {"id":"setRoutineWebhookSecret","method":"POST","path":"/routines/{id}/webhook","summary":"Set or rotate mission webhook secret","description":"Stores a client-generated 32-byte base64url secret. Only workspace owners and admins may set or rotate it. The secret is accepted only as input and is never returned. **Required scope:** `routines:write`.","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}],"body":{"required":true,"fields":[{"name":"secret","required":true,"type":"string","description":"Client-generated 32-byte base64url secret without padding."}]}},
  {"id":"signOutAccountSession","method":"DELETE","path":"/settings/sessions","summary":"Sign out an account session","description":"Revokes one active sign-in session belonging to the user associated with the API credential. The session handle comes from `GET /settings/sessions`. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"session_id","required":true,"type":"string","description":"Opaque session handle returned by the list endpoint.","format":"uuid"}]}},
  {"id":"startCampaign","method":"POST","path":"/campaigns/{id}/start","summary":"Start a campaign","description":"Sets the campaign to `running` and triggers the first dialer wave immediately; subsequent waves run on a schedule. Calling windows, DNC list and concurrency are enforced by the dialer. **Required scope:** `campaigns:write` (keys without scope restrictions have full access).","tag":"Campaigns","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."}]},
  {"id":"startSlackOauth","method":"POST","path":"/slack/oauth","summary":"Start Slack OAuth (Add to Slack)","description":"Returns a Slack authorize URL. Open it in a browser to install the platform Famulor Slack app; the OAuth callback creates/updates a Slack messaging connector with `team_id`. **Required scope:** `assistants:write`. Platform-root workspaces only.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"assistant_id","required":true,"type":"string","format":"uuid"},{"name":"name","required":false,"type":"string","description":"Optional connector display name"}]}},
  {"id":"startTranslationSession","method":"POST","path":"/translation-sessions/{id}/start","summary":"Start a translation room","description":"Start each participant in the browser, through a callback, or speaker 1 by dialing the assigned number and entering the room code. The Translate Agent mode must be included in the workspace's current plan. Phone participants require phone_number. One shared talk rate and translation surcharge apply, plus actual costs for each phone connection. Requires calls:write and a credential belonging to the room host. Workspace roles, credits, assistant and calling limits apply.","tag":"Translation","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"speaker1","required":true,"type":"object"},{"name":"speaker2","required":true,"type":"object"},{"name":"phone_number_id","required":false,"type":"string","format":"uuid"}]}},
  {"id":"startWhatsAppOutboundCall","method":"POST","path":"/calls/whatsapp-outbound","summary":"Start outbound WhatsApp voice call","description":"Place a WhatsApp voice call via the platform WhatsApp voice connector. **Required scope:** `calls:write`. Requires WhatsApp voice in the workspace plan.","tag":"Calls","parameters":[],"body":{"required":true,"fields":[{"name":"connector_id","required":true,"type":"string","format":"uuid"},{"name":"to_number","required":true,"type":"string","description":"E.164 WhatsApp user"},{"name":"assistant_id","required":false,"type":"string","format":"uuid"}]}},
  {"id":"stopCampaign","method":"POST","path":"/campaigns/{id}/stop","summary":"Stop a campaign","description":"Pauses a running campaign (status `paused`). Calls already in progress finish normally; the dialer stops dialing new leads. Returns 409 if the campaign is not running. **Required scope:** `campaigns:write` (keys without scope restrictions have full access).","tag":"Campaigns","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."}]},
  {"id":"submitPhoneNumberVerification","method":"POST","path":"/phone-numbers/verifications","summary":"Submit regulatory number verification","description":"Submit a number verification case with the required address, registration details, and supporting documents. Discover supported combinations with GET /phone-numbers/verifications/catalog and load required fields with GET /phone-numbers/verifications/requirements. To correct your own failed, rejected, or draft case instead of opening a new one, send `replace_verification_id`: GET /phone-numbers/verifications/{id}/submission returns its last details, and supporting documents without a new attachment are reused. A submission that fails the automated check is stored as a failed case. Requires a user-scoped API key. **Required scope:** `phone_numbers:write`.","tag":"Phone Numbers","parameters":[],"body":{"required":true,"fields":[{"name":"replace_verification_id","required":false,"type":"string","description":"Correct and resubmit this own failed, rejected, or draft verification instead of opening a new one. Supporting documents whose `file_field` has no new attachment are reused from it.","format":"uuid"},{"name":"country","required":true,"type":"string","description":"ISO-2"},{"name":"type","required":false,"type":"string","enum":["local","mobile","national"]},{"name":"end_user_type","required":false,"type":"string","enum":["individual","business"]},{"name":"email","required":true,"type":"string","format":"email"},{"name":"prefix","required":true,"type":"string","description":"Area code or E.164 prefix, e.g. 030 or +4930. National digits are completed with the country calling code."},{"name":"address","required":false,"type":"object"},{"name":"end_user_attributes","required":false,"type":"object"},{"name":"supporting_documents","required":false,"type":"array","items":{"type":"object"}},{"name":"attachments","required":false,"type":"array","items":{"type":"object"}}]}},
  {"id":"submitVoiceCloneJob","method":"POST","path":"/voices/clone","summary":"Submit voice clone job","description":"Submits a prepared job after every sample upload finishes. Send either the preferred `id` returned by the upload-preparation endpoint or its transition alias `job_id`; if both are sent, they must match. Explicit rights confirmation is required. **Required scope:** `voices:write` or `assistants:write`. A user-bound credential is required. Read the current creation price from the capability response and accept it with expected_credits. Included creations are a one-time workspace allowance; additional successful creations consume credits. A higher price or exhausted free allowance returns 409 price_changed before processing. Failed creations are not charged. Retries of the same job cannot charge again.","tag":"Voices","parameters":[],"body":{"required":true}},
  {"id":"testMessagingConnectorEndedWebhook","method":"POST","path":"/messaging-connectors/{id}/ended-webhook-test","summary":"Send a test conversation.ended webhook","description":"Sends an example `conversation.ended` payload (Voice-style envelope, with sample transcript/analysis) to the connector's configured webhook, or to `url` if given (test call only — the saved URL is not changed). **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":false,"fields":[{"name":"url","required":false,"type":"string","description":"Overrides the saved conversation_ended_webhook_url for this test call only.","format":"uri"}]}},
  {"id":"testTool","method":"POST","path":"/tools/test","summary":"Test HTTP tool","description":"Send a real HTTP test request using the same request preparation, secret handling and outbound protections as Agent Tools. The request may change the remote system. Requires an admin-level credential and assistants:write.","tag":"Tools","parameters":[],"body":{"required":true,"fields":[{"name":"tool_id","required":false,"type":"string","description":"Existing tool to reuse masked secrets.","format":"uuid"},{"name":"config","required":true,"type":"object","description":"HTTP or MCP configuration, as accepted when creating this tool type."},{"name":"values","required":false,"type":"object","description":"Sample tool parameter values."},{"name":"call_values","required":false,"type":"object","description":"Separate sample call variables."}]}},
  {"id":"tidyAssistantFlow","method":"POST","path":"/assistants/{id}/flow/layout","summary":"Tidy up an assistant flow","description":"Arrange the saved flow with clear spacing between nodes, branches and merges. Changes node positions only; preserves all instructions, tool bindings, connections, conditions and call settings. No request body. Requires Flow Builder access for advanced flows. Read the assistant afterward to retrieve the updated positions. Required scope: `assistants:write`. Also available as the MCP tool `tidy_assistant_flow`.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}]},
  {"id":"transferPlatformUserBalance","method":"POST","path":"/platform/users/{user_id}/balance","summary":"Transfer credits to or from a platform user","description":"Transfers signed credits between your own workspace wallet and this customer's workspace wallet. A **positive** `credits` value grants credits from your wallet to the customer; a **negative** value reclaims credits back from the customer into yours. Either direction requires the source wallet to cover the amount — a wallet balance never goes below zero, and an insufficient-balance attempt fails with `400 invalid_request` rather than partially applying. **Required scope:** `platform:write`. Requires white-label platform access (a reseller workspace with the white-label entitlement, or a platform admin acting from a root workspace) plus a live owner/admin membership in the calling credential's own workspace — see [White Label API](/admin/whitelabel-api).","tag":"White Label","parameters":[{"name":"user_id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"credits","required":true,"type":"number","description":"Signed, non-zero. Positive grants credits from your workspace wallet into the customer's; negative reclaims credits back from the customer into yours. The source wallet must cover the amount — wallet balances never go below zero."},{"name":"note","required":false,"type":"string","description":"Optional audit note."},{"name":"workspace_id","required":false,"type":"string","description":"Pick a specific workspace when the customer has several in your scope; defaults to the one they own.","format":"uuid"}]}},
  {"id":"transferWorkspaceOwnership","method":"POST","path":"/workspace/transfer-ownership","summary":"Transfer workspace ownership","description":"Appoint an existing active, verified member as owner. Requires settings:write and a user-owned credential belonging to the current owner; service-account credentials cannot transfer ownership. The previous owner stays as admin. Plan, credits, numbers, workspace data, payment methods and billing details are preserved. Read the current owner from List team members and provide their user ID as the expected owner to reject stale requests. The previous owner’s user-bound API and OAuth credentials may be revoked by the role change; service-account credentials remain in place. The previous owner’s personal API keys and OAuth access for this workspace are revoked; workspace service credentials stay active.","tag":"Workspaces","parameters":[],"body":{"required":true,"fields":[{"name":"member_id","required":true,"type":"string","description":"Target membership ID in the current workspace.","format":"uuid"},{"name":"expected_owner_user_id","required":true,"type":"string","description":"Current owner user ID from List team members.","format":"uuid"}]}},
  {"id":"triggerAutomation","method":"POST","path":"/automations/{id}","summary":"Trigger automation","description":"Manually start a run for the automation.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"troubleshootCarrierConnection","method":"POST","path":"/carrier-connections/{id}/troubleshoot","summary":"Troubleshoot a carrier connection","description":"Checks credentials, provider routing, platform trunks, and dispatch rules; optionally repairs safe drift. **Required scope:** `sip_trunks:write`.","tag":"Carrier Connections","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Carrier connection ID."}],"body":{"required":false,"fields":[{"name":"repair","required":false,"type":"boolean","default":true}]}},
  {"id":"updateAiInferenceSettings","method":"PATCH","path":"/settings/ai-inference","summary":"Update AI inference settings","description":"Updates the workspace AI inference region. Changing the region re-reviews existing assistants; EU requires a clear AI introduction in the effective opening. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"ai_inference_region","required":true,"type":"string","description":"AI Gateway inference region for workspace backend AI.","enum":["global","eu","us"]}]}},
  {"id":"updateAssistant","method":"PATCH","path":"/assistants/{id}","summary":"Update an assistant","description":"Partial update — only the provided fields change. Every update creates a version snapshot. `PUT` is accepted as an alias of `PATCH`. Pipeline and Half-cascade assistants are checked against the languages their voice can speak, with `400 invalid_request` on failure. Every language is re-checked when the voice moves to a different voice provider or the engine switches to Pipeline or Half-cascade; otherwise only languages the request adds are checked, so another voice from the same provider and unrelated edits keep the current languages. **Required scope:** `assistants:write` (keys without scope restrictions have full access).","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}],"body":{"required":true,"description":"Writable assistant fields. Unknown fields are ignored. Non-null engine model overrides require the Fallbacks & Guardrails add-on and are validated against the assistant owner's effective catalog access and engine compatibility. Null resets to the next default level.","fields":[{"name":"name","required":false,"type":"string"},{"name":"tags","required":false,"type":"array","description":"Free-form workspace tags for filtering assistants. Case-insensitive unique; original spelling is kept.","items":{"type":"string","maxLength":40}},{"name":"is_active","required":false,"type":"boolean"},{"name":"system_prompt","required":false,"type":"string"},{"name":"response_by_channel","required":false,"type":"object","description":"Versioned manual response instructions for exact output channels. Omit a channel key to use Automatic. Manual instructions supplement and never replace safety, language, tool, or delivery rules. Requires the workspace's Manual channel responses feature."},{"name":"mode","required":false,"type":"string","description":"Assistant engine: Pipeline, Realtime, Half-cascade, or Translate for a two-person interpreter room. The selected mode must be included in the workspace's current plan.","enum":["pipeline","realtime","half_cascade","translation"]},{"name":"realtime_provider","required":false,"type":"string"},{"name":"realtime_model","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement."},{"name":"realtime_voice","required":false,"type":"string","description":"Compatible native conversation voice. Use a neutral ID returned by the native voice library. Available for Realtime; the chosen variant controls compatibility."},{"name":"llm_provider","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement.","enum":["openai","azure","google","groq","anthropic",null]},{"name":"llm_model","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement."},{"name":"half_cascade_provider","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement."},{"name":"half_cascade_model","required":false,"type":"string","description":"Requires Fallbacks & Guardrails for this workspace. Select a compatible value from the model catalog; null follows workspace then platform defaults. Omitted from responses without this entitlement."},{"name":"llm_temperature","required":false,"type":"number"},{"name":"stt_language","required":false,"type":"string"},{"name":"stt_keyterms","required":false,"type":"array","description":"Speech-recognition glossary for customer, product, and proper names. Plan-gated.","items":{"type":"string","maxLength":100}},{"name":"stt_keyterm_detection_enabled","required":false,"type":"boolean","description":"Beta: automatically detect additional call-local keyterms. Detected terms are not persisted."},{"name":"tts_provider","required":false,"type":"string","enum":["cartesia","elevenlabs","openai","google","azure","fishaudio","deepgram","inworld","rime","xai"]},{"name":"tts_voice","required":false,"type":"string","description":"Pipeline or Half-Cascade speech voice. For Full Duplex, retained only for a Pipeline fallback; greetings, consent and tool announcements use realtime_voice. Uploaded greeting audio retains its recorded voice. Must be able to speak the primary and secondary languages."},{"name":"tts_speed","required":false,"type":"number"},{"name":"tts_emotion","required":false,"type":"array","description":"Legacy array field controlling Dynamic emotions (Expressive Mode) for compatible pipeline and half-cascade voices. Omit on create to enable it when supported. Send [] to disable it or [\"calm\"] to enable it. Realtime speech models handle expression natively.","items":{"type":"string"}},{"name":"tts_style_prompt","required":false,"type":"string","description":"Optional free-text speaking-style instructions for compatible TTS models. Send null to clear the override."},{"name":"elevenlabs_stability","required":false,"type":"number","description":"Voice stability override. Send null to use the voice-provider default.","minimum":0,"maximum":1},{"name":"elevenlabs_similarity","required":false,"type":"number","description":"Voice similarity override. Send null to use the voice-provider default.","minimum":0,"maximum":1},{"name":"elevenlabs_style","required":false,"type":"number","description":"Voice-style exaggeration override. Send null to use the voice-provider default.","minimum":0,"maximum":1},{"name":"elevenlabs_speaker_boost","required":false,"type":"boolean","description":"Speaker-boost override. Send null to use the voice-provider default."},{"name":"affective_dialog","required":false,"type":"boolean","description":"Realtime mode with a Google realtime model only: match the caller's tone with warmer, more expressive speech."},{"name":"turn_detection","required":false,"type":"string","enum":["multilingual_model","english_model","vad","stt"]},{"name":"vad_min_silence_ms","required":false,"type":"integer"},{"name":"vad_threshold","required":false,"type":"number","description":"Voice-detection threshold. Null uses the effective engine default: 0.50 for pipeline and adaptive voice detection, 0.50 for web server VAD, and 0.70 for phone server VAD. This detects speech; it does not filter audio.","minimum":0.1,"maximum":0.9},{"name":"allow_interruptions","required":false,"type":"boolean"},{"name":"min_interruption_duration_ms","required":false,"type":"integer"},{"name":"response_timing","required":false,"type":"string","description":"How quickly the assistant answers once the caller pauses: `snappy` answers right away, `balanced` leaves a short pause, `patient` waits longer for callers who pause mid-sentence. Applies to pipeline mode and adaptive realtime turn handling.","enum":["snappy","balanced","patient"]},{"name":"min_interruption_words","required":false,"type":"integer","description":"Pipeline mode only: ignore barge-ins shorter than this many words, so back-channel sounds like “mhm” don't interrupt the assistant. 0 turns it off; larger values are capped at 10.","minimum":0,"maximum":10},{"name":"noise_cancellation","required":false,"type":"string","enum":["bvc","bvc_telephony","none"]},{"name":"preemptive_generation","required":false,"type":"boolean","description":"Begin response generation before turn confirmation. Effective in pipeline mode only."},{"name":"resume_false_interruption","required":false,"type":"boolean","description":"Resume interrupted output when an apparent interruption produces no transcript during the two-second false-interruption window. Effective in pipeline mode and adaptive realtime turn handling, and only while interruptions are enabled."},{"name":"max_tool_steps","required":false,"type":"integer"},{"name":"first_message","required":false,"type":"string"},{"name":"greeting_mode","required":false,"type":"string","enum":["agent_speaks_first","user_speaks_first"]},{"name":"greeting_allow_interruptions","required":false,"type":"boolean","description":"When true, the caller may barge in during the opening greeting (first message / audio / silence fallback). Default false = play greeting uninterrupted. Separate from allow_interruptions (rest of the call)."},{"name":"ai_speaks_after_silence","required":false,"type":"boolean","description":"When greeting_mode is user_speaks_first: after ai_entry_timeout_sec of initial silence, the assistant speaks (static or dynamic). Default false."},{"name":"silence_greeting_mode","required":false,"type":"string","enum":["static","dynamic"]},{"name":"silence_greeting_message","required":false,"type":"string"},{"name":"ai_entry_timeout_sec","required":false,"type":"integer","minimum":1,"maximum":20},{"name":"pre_call","required":false,"type":"object","description":"iOS/Android Call Screen Handling. Mirrored into flow_json.pre_call when a flow exists."},{"name":"flow_json","required":false,"type":"object","description":"Agent type. Omit or `null` = Single prompt (default). Object = Conversational flow (Flow JSON v1). Seed Start→Agent→End for a basic flow; non-trivial graphs may require the Flow builder feature in the workspace plan. In flow mode, `system_prompt` is the Advanced / base prompt (agent-node text is appended)."},{"name":"recording_enabled","required":false,"type":"boolean","description":"Whether audio recording is enabled for calls handled by this assistant. In PATCH and PUT requests, omitting this field leaves the existing setting unchanged. Saving an explicit boolean (`true` or `false`) updates the setting. Recording calls is independent of Loop recording and voicemail recording; see `/assistants/conversation-quality#consent` for caller consent rules and `/billing/minutes#call-recording` for recording billing."},{"name":"retranscribe_enabled","required":false,"type":"boolean","description":"Enhanced transcription: after the call, the recording is transcribed again with a higher-accuracy engine and shown next to the live transcript. Only takes effect while `recording_enabled` is on. Billed in credits per recorded minute."},{"name":"card_collect_enabled","required":false,"type":"boolean","description":"Allows secure payment card collection (the Collect payment card tool and Flow Collect steps of type `credit_card`). Also needs a connected payment account. Switching it on requires a plan that includes payment card collection; otherwise the request fails with HTTP 403."},{"name":"max_call_duration_sec","required":false,"type":"integer","description":"Maximum call duration in seconds (60–1800). null = unlimited (budget cap still applies).","minimum":60,"maximum":1800},{"name":"inbound_ringing_timeout_sec","required":false,"type":"integer","description":"How long inbound callers hear ringing before the call times out (30–120 s, default 60). If every concurrent line is busy, callers keep ringing within this time until a line frees up.","minimum":30,"maximum":120},{"name":"outbound_ringing_timeout_sec","required":false,"type":"integer","description":"How long outbound SIP/WhatsApp calls ring before no-answer (15–80 s, default 45).","minimum":15,"maximum":80},{"name":"amd_enabled","required":false,"type":"boolean","description":"Answering machine detection on direct outbound calls (dashboard, API, automations, callbacks). New assistants default to `false`: the assistant greets as soon as the call is answered and mailboxes are not detected. Campaign calls use the campaign's `amd_enabled`.","default":false},{"name":"voicemail_enabled","required":false,"type":"boolean","description":"What a direct outbound call does at a detected mailbox: `true` = speak `voicemail_message`, then hang up; `false` = hang up without a message. Takes effect while `amd_enabled` is on. Campaign calls use the campaign's voicemail settings.","default":false},{"name":"voicemail_message","required":false,"type":"string","description":"Message spoken onto a detected mailbox when `voicemail_enabled` is `true`; supports `{{variables}}`. `null` or empty = the greeting / first message is used."},{"name":"idle_timeout_sec","required":false,"type":"integer"},{"name":"transcription_timeout_sec","required":false,"type":"number","description":"Seconds after VAD detects speech with no STT transcript before asking the caller to repeat. null disables.","minimum":1,"maximum":30},{"name":"knowledgebase_id","required":false,"type":"string","format":"uuid"},{"name":"knowledge_gap_mode","required":false,"type":"string","enum":["off","questions_only","draft_for_review","tentative_live"]},{"name":"webhook_url","required":false,"type":"string","description":"Agent-level post-call webhook URL."},{"name":"webhook_timeout_sec","required":false,"type":"integer","minimum":1,"maximum":30},{"name":"webhook_retries","required":false,"type":"integer","minimum":0,"maximum":5},{"name":"webhook_delivery_mode","required":false,"type":"string","description":"none = do not deliver; custom = POST the assistant webhook URL after the call; automation = deliver through the bound automation.","enum":["none","custom","automation"]},{"name":"automation_id","required":false,"type":"string","description":"Bound automation when webhook delivery is automation.","format":"uuid"},{"name":"notification_settings","required":false,"type":"object","description":"Activity notifications for this assistant, keyed by History channel (`call`, `avatar`, `live_chat`, `whatsapp_voice`, `whatsapp`, `telegram`, `slack`, `messenger`, `teams`, `discord`, `gchat`, `x`, `freshdesk`, `gmail`, `outlook`, `zendesk`, `servicenow`, `intercom`, `zoho_mail`, `agent_mail`, `instagram`, `zulip`, `email`; the legacy key `messaging` applies to every messaging channel). Each channel takes `email` and `push` toggles. A missing channel or toggle stays on; set it to `false` to opt out. Unknown keys are dropped."},{"name":"metadata","required":false,"type":"object"},{"name":"outbound_phone_number_id","required":false,"type":"string","description":"Workspace phone number this assistant calls from on outbound calls (an `id` from `GET /phone-numbers`). Several assistants can share one number. A `phone_number_id` passed when starting a call takes precedence. A number from another workspace or a released number returns HTTP 404. Null clears it.","format":"uuid"},{"name":"background_audio","required":false,"type":"object","description":"BackgroundAudioPlayer config (`ambient`, `ambient_volume`, `thinking`, `thinking_volume`). `{}` = off. Hold music is configured on the warm-transfer tool, not here."},{"name":"adaptive_interruptions","required":false,"type":"boolean"},{"name":"realtime_turn_mode","required":false,"type":"string","description":"Realtime turn handling: robust voice activity, semantic completion, or adaptive barge-in.","enum":["server_vad","semantic","adaptive"]},{"name":"realtime_eagerness","required":false,"type":"string","description":"How quickly the assistant responds when realtime_turn_mode is semantic.","enum":["auto","low","medium","high"]},{"name":"long_call_memory","required":false,"type":"string","description":"Pipeline mode only: context strategy once a call runs long. `full` keeps the whole conversation in context; `recent` keeps the latest part in focus for faster responses on calls of 10+ minutes.","enum":["full","recent"]},{"name":"idle_messages","required":false,"type":"array","description":"Fixed re-engagement phrases on caller inactivity; `[]` = LLM-generated.","items":{"type":"string"}},{"name":"idle_max_rounds","required":false,"type":"integer","description":"Unanswered idle check-ins before the assistant says goodbye and ends the call (1–10, default 2).","minimum":1,"maximum":10},{"name":"fallback_config","required":false,"type":"object","description":"Requires Fallbacks & Guardrails. Saved fallback configuration is omitted from responses without this workspace entitlement."},{"name":"fallbacks_enabled","required":false,"type":"boolean","description":"Turns on platform-managed model fallbacks, so a call continues on a backup model if a speech or language model fails. Must be a boolean. Switching it on requires Fallbacks & Guardrails; otherwise the request fails with HTTP 403."},{"name":"pronunciation_map","required":false,"type":"object"},{"name":"tts_filter_markdown","required":false,"type":"boolean"},{"name":"tts_filter_emoji","required":false,"type":"boolean"},{"name":"consent_enabled","required":false,"type":"boolean"},{"name":"consent_text","required":false,"type":"string"},{"name":"consent_mode","required":false,"type":"string"},{"name":"consent_decline_action","required":false,"type":"string","description":"What happens when the caller declines consent: `no_recording` continues the call without recording, `hangup` says a farewell and ends the call.","enum":["no_recording","hangup"]},{"name":"consent_decline_text","required":false,"type":"string","description":"Custom farewell spoken before the call ends when the caller declines consent and `consent_decline_action` is `hangup`. Null or empty uses the default farewell for the assistant's language."},{"name":"consent_covers_recording","required":false,"type":"boolean"},{"name":"consent_covers_memory","required":false,"type":"boolean"},{"name":"guardrails","required":false,"type":"object"},{"name":"language_voices","required":false,"type":"object","description":"Per-language voice overrides for Pipeline/Half-cascade. Languages without an entry keep the main voice. A private per-language clone is allowed only when the main voice is also a workspace-owned private clone that uses the same provider runtime. Keys must be languages the voice can speak."},{"name":"auto_language_switch","required":false,"type":"boolean","description":"Automatic response-language switching; derived from secondary_languages by the dashboard."},{"name":"output_volume","required":false,"type":"number"},{"name":"speaking_rate","required":false,"type":"number"},{"name":"text_only_enabled","required":false,"type":"boolean"},{"name":"memory_enabled","required":false,"type":"boolean"},{"name":"memory_mode","required":false,"type":"string","description":"`inherit` follows the workspace memory default; `on`/`off` override it.","enum":["inherit","on","off"]},{"name":"memory_scope","required":false,"type":"string","description":"`workspace` = one summary shared across assistants; `assistant` = one summary private to this assistant; `both` = two complete summaries, one shared and one assistant-private.","enum":["workspace","assistant","both"]},{"name":"lead_attribute_mode","required":false,"type":"string","description":"`all` is an immutable compatibility state for an assistant that already had unrestricted contact-field access. Creating with `all` or changing `selected` to `all` returns HTTP 400. `selected` exposes only explicit `source: lead` definitions.","enum":["all","selected"]},{"name":"memory_read_channels","required":false,"type":"array","description":"Per-assistant read allowlist intersected with workspace policy. Send [] to disable reads.","items":{"type":"string","description":"Memory channels. Web Chat and Web Voice require a current verified widget email or phone and memory consent. Web and SMS memory require a root workspace. Legacy web configuration expands to both web channels; anonymous sessions remain excluded.","enum":["voice","sms","whatsapp","email","web","telegram","slack","messenger","teams","discord","gchat","x","freshdesk","gmail","outlook","zendesk","servicenow","intercom","zoho_mail","agent_mail","instagram","zulip","web_chat","web_voice"]}},{"name":"memory_write_channels","required":false,"type":"array","description":"Per-assistant write allowlist intersected with workspace policy. Send [] to disable writes.","items":{"type":"string","description":"Memory channels. Web Chat and Web Voice require a current verified widget email or phone and memory consent. Web and SMS memory require a root workspace. Legacy web configuration expands to both web channels; anonymous sessions remain excluded.","enum":["voice","sms","whatsapp","email","web","telegram","slack","messenger","teams","discord","gchat","x","freshdesk","gmail","outlook","zendesk","servicenow","intercom","zoho_mail","agent_mail","instagram","zulip","web_chat","web_voice"]}},{"name":"memory_categories","required":false,"type":"array","description":"Allowed summary categories. Send [] for metadata-only memory with no new content summary.","items":{"type":"string","enum":["identity","preferences","agreements","open_items"]}},{"name":"redact_pii","required":false,"type":"boolean","description":"When true, apply `pii_redaction` entity filters to stored transcripts."},{"name":"pii_redaction","required":false,"type":"object","description":"PII entity categories + optional custom regexes."},{"name":"analysis_config","required":false,"type":"object","description":"Post-conversation sentiment, success and structured extraction for voice, chat, messaging and email. Results retain native JSON types in History, webhooks, the public API and MCP."},{"name":"qa_scorecard_config","required":false,"type":"json","description":"AI QA scorecard configuration (requires AI QA Scorecards in the workspace plan). `null` or `enabled: false` disables scoring."},{"name":"timezone","required":false,"type":"string","description":"IANA timezone of the assistant (e.g. `Europe/Berlin`, default). Anchors the `get_current_time` system tool, the `{{time}}`/`{{date}}`/`{{datetime}}`/`{{weekday}}` system variables, and the `check_business_hours` built-in tool. On campaign calls the campaign's timezone overrides it per call."},{"name":"primary_language","required":false,"type":"string","description":"Language the assistant answers in by default (ISO 639-1 or ISO 639-3, see `GET /languages`). Pipeline and Half-cascade: must be a language the assistant's voice can speak. If you omit `tts_voice` when creating, a default voice that speaks this language is chosen."},{"name":"secondary_languages","required":false,"type":"array","description":"Languages the assistant may switch to when the caller clearly speaks them (ISO 639-1 or ISO 639-3). Non-empty implies multilingual STT + auto language switch. Each language must be speakable by the assistant's voice (Pipeline and Half-cascade); otherwise the request fails with `invalid_request`.","items":{"type":"string"}},{"name":"variables","required":false,"type":"array","description":"Custom variable definitions, referenced as `{{key}}` and resolved per call (explicit call values > inbound enrichment > current contact values > remembered value > default_value). Each custom definition can be call-only, workspace-shared, or assistant-private.","items":{"type":"object"}},{"name":"variable_webhook_url","required":false,"type":"string","description":"Optional webhook called on inbound calls to enrich variable values before the conversation starts."},{"name":"variable_webhook_secret","required":false,"type":"string","description":"Secret used to sign variable webhook requests (HMAC-SHA256 of the raw body, sent as `X-Famulor-Signature: sha256=<hex>`). Write-only: never returned. Null clears it.","writeOnly":true},{"name":"builtin_tools","required":false,"type":"array","description":"Inline built-in tool configurations (also accepted as `tools` for compatibility). DTMF Input and Collect Keypad Input run as prompt-session tools here; dedicated Flow nodes bind their reusable central-tool equivalents.","items":{"type":"object","description":"One built-in tool configuration. `type` selects the tool; the remaining fields depend on the type. DTMF Input sends keypad tones to an IVR or phone menu; Collect Keypad Input collects keypad or spoken digits from the caller. In an assistant's inline `builtin_tools` they run as prompt-session tools. Reusable copies created through the Tools API can also be assigned to assistants and bound to their dedicated Flow Builder nodes. Calendars use Integrations. All types accept an optional `description` that tells the model when to use the tool. Saved caller-facing announcements, filler phrases and end-call farewells remain editable. With secondary languages configured on the assistant, they guide generated wording in the current supported conversation language without fixed saved audio. Otherwise their existing delivery behavior is preserved. An empty End call farewell adds no speech."}},{"name":"translation_config","required":false,"type":"object"},{"name":"realtime_variant","required":false,"type":"string","description":"Realtime conversation variant. Full Duplex requires workspace Beta features, Realtime plan access and compatible defaults available in the selected workspace region; extra credits may apply. Its reasoning model is managed centrally. Existing assistants use standard.","enum":["standard","full_duplex"]}]}},
  {"id":"updateAssistantTest","method":"PATCH","path":"/assistants/{id}/tests/{testId}","summary":"Update simulation test","description":"**Required scope:** `assistants:write`.","tag":"Simulations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"testId","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":false}},
  {"id":"updateAssistantVariables","method":"PATCH","path":"/assistants/{id}/variables","summary":"Update assistant variables","description":"Replaces the custom variable definitions, contact-field access mode, and/or the inbound variable webhook URL. Send at least one supported field; `variables` always replaces the full list. Legacy `all` contact-field access is read-only and cannot be enabled; attempts return HTTP 400. **Required scope:** `assistants:write`.","tag":"Assistants","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Assistant ID."}],"body":{"required":true}},
  {"id":"updateAutomation","method":"PATCH","path":"/automations/{id}","summary":"Update automation","description":"Update name, status, trigger, graph, or tags (`string[]`). **Required scope:** `automations:write` or `calls:write`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"updateAutomationConnection","method":"PATCH","path":"/automations/connections/{id}","summary":"Update automation connection","description":"Patch a connection. Sending `\"•••\"` for a secret keeps the stored value; omit a field to leave it unchanged. **Required scope:** `automations:write` or `calls:write`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"updateBookingEventType","method":"PATCH","path":"/booking-event-types/{id}","summary":"Update a booking event type","description":"Update an event type; only provided fields change.\n\n**Required scope:** `bookings:write` (keys without scope restrictions have full access).","tag":"Bookings","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Event type ID"}],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","maxLength":128},{"name":"slug","required":true,"type":"string"},{"name":"duration_min","required":true,"type":"integer","minimum":5,"maximum":480},{"name":"timezone","required":true,"type":"string"},{"name":"availability","required":true,"type":"object"},{"name":"description","required":false,"type":"string","maxLength":2000},{"name":"buffer_before_min","required":false,"type":"integer","default":0},{"name":"buffer_after_min","required":false,"type":"integer","default":0},{"name":"min_notice_min","required":false,"type":"integer","default":60},{"name":"max_days_ahead","required":false,"type":"integer","default":30},{"name":"slot_increment_min","required":false,"type":"integer"},{"name":"reminder_hours","required":false,"type":"integer"},{"name":"is_active","required":false,"type":"boolean","default":true},{"name":"booking_fields","required":false,"type":"array","description":"Custom booking questions, in display order. Name is always required; email_required and phone_required control the system contact fields.","items":{"type":"object","description":"A custom booking question asked on the public booking page. Answers are keyed by `id` on a booking's `answers` object and can be prefilled on the public booking page via the matching URL parameter."}},{"name":"phone_required","required":false,"type":"boolean","description":"Require the visitor's phone number (E.164) to book. When false (default), phone is still asked but optional.","default":false},{"name":"email_required","required":false,"type":"boolean","description":"Whether an invitee email is required. Google Meet and Microsoft Teams always require a valid email.","default":true},{"name":"sender_email_address_id","required":false,"type":"string","description":"Active verified email address belonging to this workspace. Null uses automatic workspace or inherited reseller SMTP, then the platform identity for eligible workspaces.","format":"uuid"},{"name":"confirmation_email_subject","required":false,"type":"string","description":"Custom initial confirmation subject; empty uses the standard subject. Supports the same booking variables as the message.","maxLength":200},{"name":"confirmation_email_body","required":false,"type":"string","description":"Custom plain-text confirmation. Supported variables are returned by GET /booking-email-templates. Blank/null restores the localized standard message.","maxLength":10000},{"name":"email_templates","required":false,"type":"object","description":"Complete replacement of the six additional guest/host email templates. Omit to preserve saved values; null or {} restores all six defaults. Confirmation uses the existing confirmation subject/body fields. GET /booking-email-templates returns standard templates and supported variables."},{"name":"email_locale","required":false,"type":"string","description":"Language of the standard booking email texts (guest and host) for this event type. null (default) uses each recipient's language. Custom subject/body text is sent as written.","enum":["en","de","fr","es",null]},{"name":"guest_emails_enabled","required":false,"type":"boolean","description":"Send emails to the invitee. false = no confirmation, cancellation, reschedule or reminder emails to guests and no invitations from the connected calendar (the guest is not added as an attendee); host notifications still send.","default":true},{"name":"hour_cycle","required":false,"type":"string","description":"Time format for the weekly availability editor and host emails. Availability values remain HH:mm. Guest emails follow the guest's saved booking-page preference, falling back to this format for older bookings.","enum":["12h","24h"],"default":"24h"}]}},
  {"id":"updateCallerId","method":"PATCH","path":"/caller-ids/{id}","summary":"Update caller ID","description":"**Required scope:** `phone_numbers:write` or `calls:write`. Updates the display label (`friendly_name`).","tag":"Caller IDs","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"friendly_name","required":false,"type":"string","description":"Display name shown under the number in the UI. Null or empty clears it."},{"name":"label","required":false,"type":"string","description":"Alias for `friendly_name`."}]}},
  {"id":"updateCampaign","method":"PATCH","path":"/campaigns/{id}","summary":"Update a campaign","description":"Updates name, assistant and/or dialer settings. `voicemail_action: \"drop_message\"` requires an effective `voicemail_message`. **Required scope:** `campaigns:write` (keys without scope restrictions have full access).","tag":"Campaigns","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."}],"body":{"required":true,"description":"Partial update — only the provided fields are changed. At least one valid field is required.","fields":[{"name":"name","required":false,"type":"string"},{"name":"assistant_id","required":false,"type":"string","format":"uuid"},{"name":"concurrency","required":false,"type":"integer","description":"Maximum parallel voice calls for this campaign. Must fit the workspace's effective Concurrent Lines allowance, including add-ons. Calls across campaigns share that workspace allowance.","minimum":1,"maximum":2147483647},{"name":"retry_max","required":false,"type":"integer","minimum":0},{"name":"retry_delay_minutes","required":false,"type":"integer","minimum":1},{"name":"calling_windows","required":false,"type":"object","description":"Allowed calling windows per weekday, local to the campaign `timezone`. Keys: `mon`–`sun`; each value is an array of `[\"HH:MM\", \"HH:MM\"]` start/end pairs (24h). An empty array or missing key blocks the whole day."},{"name":"timezone","required":false,"type":"string"},{"name":"amd_enabled","required":false,"type":"boolean"},{"name":"voicemail_action","required":false,"type":"string","enum":["hangup","drop_message"]},{"name":"voicemail_message","required":false,"type":"string"},{"name":"amd_mode","required":false,"type":"string","description":"Answering-machine detection sensitivity when AMD is enabled.","enum":["conservative","aggressive"]},{"name":"ivr_navigation","required":false,"type":"boolean","description":"Allow navigating phone menus. Enabling requires workspace Beta features."}]}},
  {"id":"updateCarrierConnection","method":"PATCH","path":"/carrier-connections/{id}","summary":"Update a carrier connection","description":"Changes the SIP region and repairs the carrier-side inbound route. **Required scope:** `sip_trunks:write`.","tag":"Carrier Connections","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Carrier connection ID."}],"body":{"required":true,"fields":[{"name":"sip_region","required":true,"type":"string","enum":["global","eu","us","uk","india","japan","aus","sa"],"default":"global"}]}},
  {"id":"updateConsentComplianceSettings","method":"PATCH","path":"/settings/consent-compliance","summary":"Update consent compliance mode","description":"Updates marketing opt-out enforcement. Universal mode is always available. Per-channel mode requires the Consent & Compliance plan feature; suppression enforcement itself is never disabled. Existing suppression records retain their original scope and `mode_at_opt_out`. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"mode","required":true,"type":"string","description":"`universal` suppresses all linked marketing channels; `per_channel` suppresses only the originating channel.","enum":["universal","per_channel"]}]}},
  {"id":"updateCrawlSource","method":"PATCH","path":"/knowledge-bases/{id}/crawl-sources/{sourceId}","summary":"Update a crawl source","description":"Update a website crawl source (custom display name, root URL, include paths, page limit, or auto-sync settings). **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"sourceId","in":"path","required":true,"type":"string","format":"uuid","description":"Crawl source ID."}],"body":{"required":true,"description":"Any subset of the create fields. Only provided fields are changed.","fields":[{"name":"name","required":false,"type":"string","description":"Custom display name shown for this source.","minLength":1,"maxLength":128},{"name":"root_url","required":false,"type":"string"},{"name":"include_paths","required":false,"type":"array","description":"Paths to restrict crawling; empty = whole host. End an entry with $ to match only that exact page (for example /impressum$); without $ it is a prefix.","items":{"type":"string"}},{"name":"exclude_paths","required":false,"type":"array","description":"Paths to skip while crawling. Max 200 per source, 500 per knowledge base. End an entry with $ to match only that exact page (for example /impressum$); without $ it is a prefix.","items":{"type":"string"}},{"name":"max_pages","required":false,"type":"integer","minimum":1,"maximum":500},{"name":"auto_sync","required":false,"type":"boolean"},{"name":"sync_interval_hours","required":false,"type":"integer","description":"Hours between auto-sync crawls. Common values: 24 = daily, 168 = weekly, 720 = monthly, 2160 = every 3 months, 4320 = every 6 months.","minimum":1}]}},
  {"id":"updateCreditNotificationPreferences","method":"PATCH","path":"/me/credit-notifications","summary":"Update low-credit warning preferences","description":"Updates the personal low-credit warning threshold and delivery channels for the user associated with this credential. At least one delivery channel must remain enabled while warnings are enabled. This preference follows the user across workspaces. A user-owned API key or OAuth token is required; service-account credentials are rejected. **Required scope:** `settings:write`.","tag":"Account","parameters":[],"body":{"required":true,"fields":[{"name":"enabled","required":true,"type":"boolean","description":"Whether personal low-credit warnings are enabled."},{"name":"threshold_credits","required":true,"type":"integer","description":"Send the warning when the available balance reaches this number of credits.","minimum":1,"maximum":1000000000},{"name":"push_enabled","required":true,"type":"boolean","description":"Deliver the warning through browser push notifications."},{"name":"email_enabled","required":true,"type":"boolean","description":"Deliver the warning to the account email address."}]}},
  {"id":"updateCrmSync","method":"PATCH","path":"/crm-syncs/{id}","summary":"Update CRM sync","description":"Patch source selection, field mapping, interval, direction, outbound create, policies, or active/paused status. Mapping and source changes reset the cursor but keep the existing schedule; use POST /crm-syncs/{id}/runs to sync immediately. Requires `automations:write` or `calls:write`.","tag":"Automations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"CRM sync ID."}],"body":{"required":true,"description":"Partial CRM sync update. All fields are optional; the connection is immutable.","fields":[{"name":"name","required":false,"type":"string","minLength":1,"maxLength":128},{"name":"object_type","required":false,"type":"string","minLength":1,"maxLength":128},{"name":"selection","required":false,"type":"object","description":"Replacement provider-neutral selection. `default_phone_country` accepts a supported ISO-2 country code."},{"name":"field_mapping","required":false,"type":"object","description":"Replacement mapping. Bare source keys stay 1:1; composed values use non-evaluated `{{field}}` tokens and optional literal text. Destinations include channel identities such as `channel.telegram.username` or `channel.whatsapp.user_id`. At least one target must be `phone` or `email`, and each target appears once."},{"name":"interval_minutes","required":false,"type":"integer","minimum":60,"maximum":10080},{"name":"status","required":false,"type":"string","enum":["active","paused"]},{"name":"null_policy","required":false,"type":"string","enum":["ignore","clear"]},{"name":"removal_policy","required":false,"type":"string","enum":["deactivate_membership","keep"]},{"name":"conflict_policy","required":false,"type":"string","enum":["review","skip"]},{"name":"direction","required":false,"type":"string","enum":["inbound","outbound","bidirectional"]},{"name":"outbound_create","required":false,"type":"boolean"}]}},
  {"id":"updateCustomerMemory","method":"PATCH","path":"/contacts/{id}/memory","summary":"Update customer memory","description":"Revision-protected update of either explicit consent or the shared summary/preferences. Read the current workspace-memory `revision` first; consent and content must be changed in separate requests. **Required scope:** `leads:write` or `calls:write`.","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Audience contact ID."}],"body":{"required":true}},
  {"id":"updateDarkWindowSettings","method":"PATCH","path":"/settings/dark-windows","summary":"Update Dark Windows settings","description":"Updates one or more proactive-outbound quiet-hour windows. Omitted channels stay unchanged. Times use 24-hour `HH:MM` format and a start later than the end creates an overnight window. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"settings","required":true,"type":"object","description":"Sparse per-channel quiet-hour update. Omitted channels remain unchanged."}]}},
  {"id":"updateDashboard","method":"PATCH","path":"/dashboards/{id}","summary":"Update a custom dashboard","description":"Rename or reorder a dashboard. **Required scope:** `dashboards:write` or `calls:write`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."}],"body":{"required":true,"description":"Create requires name. PATCH accepts name, sort_order, show_default_sections, and/or hidden_default_sections.","fields":[{"name":"name","required":false,"type":"string","minLength":1,"maxLength":120},{"name":"sort_order","required":false,"type":"integer","minimum":0,"maximum":1000000},{"name":"show_default_sections","required":false,"type":"boolean","description":"Set false for a blank canvas or true to restore the built-in overview."},{"name":"hidden_default_sections","required":false,"type":"array","description":"Complete list of built-in cards to hide individually; send an empty array to restore all.","items":{"type":"string","enum":["filter_bar","kpi_conversations","kpi_completion_rate","kpi_average_duration","kpi_success_rate","kpi_conversation_spend","call_activity","outcome_mix","assistant_performance","post_call_intelligence","campaign_funnel","module_assistants","module_campaigns","module_audience","module_booking","module_knowledge","module_simulations","module_live_monitoring","module_tools","module_phone_numbers","recent_calls"]}}]}},
  {"id":"updateDashboardWidget","method":"PATCH","path":"/dashboards/{id}/widgets/{widgetId}","summary":"Update a dashboard widget","description":"Partial update of widget data, visualization, conditions, order, or grid layout. **Required scope:** `dashboards:write` or `calls:write`.","tag":"Dashboards","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Dashboard ID."},{"name":"widgetId","in":"path","required":true,"type":"string","format":"uuid","description":"Widget ID."}],"body":{"required":true,"description":"POST: provide widget_id to attach an existing reusable widget, or name to create one. PATCH: only provided fields change.","fields":[{"name":"widget_id","required":false,"type":"string","format":"uuid"},{"name":"name","required":false,"type":"string","minLength":1,"maxLength":120},{"name":"widget_type","required":false,"type":"string","enum":["statistic","chart","table"]},{"name":"data_table","required":false,"type":"string","enum":["calls","campaigns","assistants","phone_numbers","conversions","leads","knowledge_bases","bookings","tools","simulations"]},{"name":"aggregation","required":false,"type":"string","enum":["count","sum","avg","max","min"]},{"name":"column_name","required":false,"type":"string"},{"name":"compare_previous_period","required":false,"type":"boolean"},{"name":"rate_range","required":false,"type":"string","enum":["7d","14d","30d","90d"]},{"name":"table_columns","required":false,"type":"array","items":{"type":"string"}},{"name":"assistant_id","required":false,"type":"string"},{"name":"visualization","required":false,"type":"string","enum":["auto","number","line","area","bar","stacked_bar","donut","pie","funnel","heatmap","table","leaderboard"]},{"name":"group_by","required":false,"type":"string"},{"name":"campaign_id","required":false,"type":"string","format":"uuid"},{"name":"show_legend","required":false,"type":"boolean"},{"name":"show_values","required":false,"type":"boolean"},{"name":"description","required":false,"type":"string"},{"name":"conditions","required":false,"type":"array","items":{"type":"object"}},{"name":"sort_order","required":false,"type":"integer","minimum":0},{"name":"grid_w","required":false,"type":"integer","minimum":3,"maximum":12},{"name":"grid_h","required":false,"type":"integer","minimum":1,"maximum":4}]}},
  {"id":"updateDriveSource","method":"PATCH","path":"/knowledge-bases/{id}/drive-sources/{sourceId}","summary":"Update a cloud drive source","description":"Update a cloud drive sync source (custom display name, app connection, folder, subfolder recursion, file limit, or auto-sync settings). **Required scope:** `knowledge:write` (keys without scope restrictions have full access).","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Knowledge base ID."},{"name":"sourceId","in":"path","required":true,"type":"string","format":"uuid","description":"Drive source ID."}],"body":{"required":true,"description":"Any subset of the create fields. Only provided fields are changed.","fields":[{"name":"name","required":false,"type":"string","description":"Custom display name shown for this source.","minLength":1,"maxLength":128},{"name":"provider","required":false,"type":"string","enum":["googledrive","one_drive","box","dropbox","sharepoint_graph"]},{"name":"connection_id","required":false,"type":"string","format":"uuid"},{"name":"folder_id","required":false,"type":"string"},{"name":"folder_name","required":false,"type":"string","description":"Remote folder name captured from the connected drive. This is provider metadata, not the editable source `name`."},{"name":"drive_id","required":false,"type":"string"},{"name":"include_subfolders","required":false,"type":"boolean"},{"name":"max_files","required":false,"type":"integer","minimum":1,"maximum":500},{"name":"auto_sync","required":false,"type":"boolean"},{"name":"sync_interval_hours","required":false,"type":"integer","description":"Hours between auto-sync runs. Common values: 24 = daily, 168 = weekly, 720 = monthly, 2160 = every 3 months, 4320 = every 6 months.","minimum":1}]}},
  {"id":"updateEmailAddress","method":"PATCH","path":"/email/addresses/{id}","summary":"Update an email address","description":"Rename (display name), reassign to a different assistant, or toggle active. There is no single-address GET — read it back via the list. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"assistant_id","required":false,"type":"string","format":"uuid"},{"name":"display_name","required":false,"type":"string","maxLength":128},{"name":"is_active","required":false,"type":"boolean"}]}},
  {"id":"updateEmailSettings","method":"PUT","path":"/email/settings","summary":"Replace email channel defaults","description":"Replaces the workspace's default sender name and signature wholesale — omitted fields reset to an empty string, so send both together if you're changing only one. `\"{agent_name}\"` in the signature is replaced with the assistant's name at send time. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"default_display_name","required":false,"type":"string"},{"name":"default_signature","required":false,"type":"string"}]}},
  {"id":"updateInboxLabelSettings","method":"PATCH","path":"/inbox-labels/settings","summary":"Update message label settings","description":"Requires calls:write and workspace owner/admin permission. Applies to new messages. Existing labels and messages remain visible. Connected mailbox labels are unchanged.","tag":"History","parameters":[],"body":{"required":true,"fields":[{"name":"enabled","required":true,"type":"boolean"}]}},
  {"id":"updateIntegration","method":"PATCH","path":"/integrations/{id}","summary":"Update a calendar integration","description":"Update a calendar integration. `provider` is immutable. Send `•••` for a secret config field to keep the stored value; config changes re-run the connection test and reset `status` to `ok`. Requires a user-owned credential of a workspace owner or admin; workspace service-account credentials get `403`.\n\n**Required scope:** `integrations:write` (keys without scope restrictions have full access).","tag":"Integrations","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Integration ID"}],"body":{"required":true,"fields":[{"name":"name","required":false,"type":"string","maxLength":64},{"name":"config","required":false,"type":"object"},{"name":"is_active","required":false,"type":"boolean"}]}},
  {"id":"updateKnowledgeBaseFaq","method":"PATCH","path":"/knowledge-bases/{id}/faqs/{faqId}","summary":"Review or update an FAQ entry","description":"Approval requires an answer and publishes it to retrieval. **Required scope:** `knowledge:write`.","tag":"Knowledge Bases","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"},{"name":"faqId","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"question","required":false,"type":"string"},{"name":"answer","required":false,"type":"string"},{"name":"proposed_answer","required":false,"type":"string"},{"name":"status","required":false,"type":"string","enum":["needs_answer","needs_review","approved","dismissed"]}]}},
  {"id":"updateLead","method":"PATCH","path":"/campaigns/{id}/leads/{leadId}","summary":"Update a campaign lead","description":"Updates name, phone, email, tags, or user-managed custom fields. System variables and channel identities are read-only. **Required scope:** `leads:write`.","tag":"Leads","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Campaign ID."},{"name":"leadId","in":"path","required":true,"type":"string","format":"uuid","description":"Lead ID."}],"body":{"required":true,"fields":[{"name":"name","required":false,"type":"string"},{"name":"phone","required":false,"type":"string","description":"International E.164 phone number."},{"name":"email","required":false,"type":"string","format":"email"},{"name":"tags","required":false,"type":"array","items":{"type":"string","maxLength":40}},{"name":"custom_fields","required":false,"type":"object","description":"Flat user-managed variables. Null deletes a key; system-managed keys are rejected."}]}},
  {"id":"updateLoopAvailability","method":"PATCH","path":"/loop/availability","summary":"Update personal Loop availability","description":"Replaces the authenticated member's weekly Loop schedule and optionally the Recall appointment calendar. A null timezone inherits the workspace timezone. Omit recall_appointment_calendar_id to keep the saved calendar. Requires a user-owned credential with `loop:write`.","tag":"Famulor Loop","parameters":[],"body":{"required":true,"fields":[{"name":"schedule_enabled","required":true,"type":"boolean"},{"name":"weekly_availability","required":true,"type":"object"},{"name":"timezone","required":true,"type":"string","description":"IANA timezone, or null to inherit the workspace timezone."},{"name":"fallback","required":false,"type":"json"},{"name":"recall_appointment_calendar_id","required":false,"type":"string","description":"Optional. Bookable workspace calendar used when arranging a Recall appointment. Omit to preserve the saved calendar; null clears it.","format":"uuid"}]}},
  {"id":"updateLoopDialingPreferences","method":"PATCH","path":"/loop/preferences","summary":"Update personal Loop dialing preferences","description":"Sets the ISO country used to expand national dial-pad numbers to international E.164 format. Explicit international numbers and internal extensions remain unchanged. Requires a user-owned credential with `loop:write`.","tag":"Famulor Loop","parameters":[],"body":{"required":true,"fields":[{"name":"dialing_country","required":true,"type":"string","description":"ISO-3166-1 alpha-2 default country."}]}},
  {"id":"updateLoopQueue","method":"PATCH","path":"/loop/queues/{id}","summary":"Update a Loop call queue","description":"Replaces a queue's behavior and members. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","minLength":1,"maxLength":120},{"name":"strategy","required":true,"type":"string","enum":["longest_idle","round_robin","sequential"]},{"name":"max_wait_seconds","required":true,"type":"integer","minimum":10,"maximum":3600},{"name":"wrap_up_seconds","required":true,"type":"integer","minimum":0,"maximum":600},{"name":"overflow_rule_id","required":true,"type":"string","format":"uuid"},{"name":"active","required":true,"type":"boolean"},{"name":"member_ids","required":false,"type":"array","description":"Legacy member list. Use members for ordered capacity settings.","items":{"type":"string","format":"uuid"}},{"name":"members","required":false,"type":"array","description":"Members in queue order with concurrent-call capacity.","items":{"type":"object"}}]}},
  {"id":"updateLoopRingGroup","method":"PATCH","path":"/loop/ring-groups/{id}","summary":"Update a Loop ring group","description":"Replaces a ring group's routing behavior and members. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","minLength":1,"maxLength":120},{"name":"strategy","required":true,"type":"string","enum":["simultaneous","sequential","round_robin"]},{"name":"ring_timeout_seconds","required":true,"type":"integer","minimum":5,"maximum":120},{"name":"presence_required","required":true,"type":"boolean"},{"name":"active","required":true,"type":"boolean"},{"name":"member_ids","required":false,"type":"array","description":"Legacy member list. Use members for ordered delay settings.","items":{"type":"string","format":"uuid"}},{"name":"members","required":false,"type":"array","description":"Members in ringing order with an optional pre-ring delay.","items":{"type":"object"}}]}},
  {"id":"updateLoopRoutingRule","method":"PATCH","path":"/loop/routing-rules/{id}","summary":"Update a Loop routing rule","description":"Atomically replaces a routing rule, shared weekly hours, time-conditioned steps, and pre-answer continuation outcomes. Cycles are rejected and the previous rule remains unchanged on failure. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Workspace-scoped Loop resource ID."}],"body":{"required":true,"fields":[{"name":"name","required":true,"type":"string","minLength":1,"maxLength":120},{"name":"active","required":true,"type":"boolean"},{"name":"schedule_enabled","required":false,"type":"boolean","default":false},{"name":"schedule_timezone","required":false,"type":"string","description":"IANA timezone, or null to inherit the workspace timezone."},{"name":"weekly_availability","required":false,"type":"object"},{"name":"steps","required":true,"type":"array","items":{"type":"object"}}]}},
  {"id":"updateLoopSettings","method":"PATCH","path":"/loop","summary":"Update Famulor Loop settings","description":"Updates customer-facing Loop settings. Requires `loop:write` and a workspace owner or admin credential.","tag":"Famulor Loop","parameters":[],"body":{"required":true,"fields":[{"name":"enabled","required":true,"type":"boolean"},{"name":"default_outbound_number_id","required":true,"type":"string","format":"uuid"},{"name":"default_route_id","required":false,"type":"string","format":"uuid"},{"name":"dialing_country","required":true,"type":"string"},{"name":"recording_enabled","required":true,"type":"boolean"},{"name":"voicemail_enabled","required":true,"type":"boolean","description":"Unused. Famulor Loop does not offer mailbox recording. Always false."}]}},
  {"id":"updateMarketingIntegrations","method":"PUT","path":"/settings/marketing","summary":"Update marketing integrations","description":"Merges marketing pixel IDs and optional conversion-API secrets for this white-label domain. Omit a secret to keep the stored value. **Required scope:** `settings:write`. Requires white-label access.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"integrations","required":false,"type":"object","description":"Partial marketing_integrations object. Public IDs only."},{"name":"secrets","required":false,"type":"object"}]}},
  {"id":"updateMemorySettings","method":"PATCH","path":"/settings/memory","summary":"Update memory settings","description":"Updates the workspace defaults for caller memory. Provide at least one field. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"memory_enabled_default","required":false,"type":"boolean","description":"Workspace default for caller memory."},{"name":"memory_staleness_days","required":false,"type":"integer","description":"Days without a successful memory update until content goes stale; `null` = never.","minimum":1,"maximum":3650},{"name":"memory_channels","required":false,"type":"array","description":"Configured memory channels. Web Chat and Web Voice require a current verified widget email or phone and visitor consent. Web and SMS memory require a root workspace. An empty array disables all memory channels.","items":{"type":"string","description":"Memory channels. Web Chat and Web Voice require a current verified widget email or phone and memory consent. Web and SMS memory require a root workspace. Legacy web configuration expands to both web channels; anonymous sessions remain excluded.","enum":["voice","sms","whatsapp","email","web","telegram","slack","messenger","teams","discord","gchat","x","freshdesk","gmail","outlook","zendesk","servicenow","intercom","zoho_mail","agent_mail","instagram","zulip","web_chat","web_voice"]}},{"name":"memory_consent_required","required":false,"type":"boolean","description":"When true, unknown consent blocks memory reads and writes."},{"name":"memory_retention_days","required":false,"type":"integer","description":"Rolling retention in days; `-1` keeps memory until it is manually erased.","minimum":-1,"maximum":3650}]}},
  {"id":"updateMessagingConnector","method":"PATCH","path":"/messaging-connectors/{id}","summary":"Update messaging connector","description":"Patch name, assistant, credentials, or conversation settings. `whatsapp_coexistence` cannot be changed after the connector is created — reconnect instead (400 if included). On a Coexistence sender, voice flags (`whatsapp_voice_enabled`, `whatsapp_outbound_voice_enabled`) and marketplace-number linking are rejected (400) — Coexistence numbers have no Calling API and are never a marketplace/OTP number. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"name","required":false,"type":"string","maxLength":120},{"name":"assistant_id","required":false,"type":"string","format":"uuid"},{"name":"is_active","required":false,"type":"boolean"},{"name":"response_delay_sec","required":false,"type":"integer","minimum":0,"maximum":30},{"name":"inactivity_timeout_min","required":false,"type":"integer","minimum":1,"maximum":1440},{"name":"allow_retrigger","required":false,"type":"boolean"},{"name":"conversation_ended_webhook_url","required":false,"type":"string","format":"uri"},{"name":"reply_mode","required":false,"type":"string","description":"App channels only. `send` (default) or `draft` (Gmail and Outlook only; 400 elsewhere).","enum":["send","draft"]},{"name":"extra_actions_enabled","required":false,"type":"boolean","description":"App channels only. Allow one app-specific action (e.g. label, tag, prioritize) alongside each reply."},{"name":"watch_scope","required":false,"type":"string","description":"Gmail, Outlook, and Zoho Mail only. Which mailbox slice the assistant watches.","enum":["inbox","all","label","folder"]},{"name":"watch_name","required":false,"type":"string","description":"Display name of the selected Gmail label or mail folder."},{"name":"watch_id","required":false,"type":"string","description":"Provider id from GET /messaging-connectors/{id}/watch-options."}]}},
  {"id":"updatePhoneNumber","method":"PATCH","path":"/phone-numbers/{id}","summary":"Update a phone number","description":"Assigns an assistant / SIP trunk and toggles inbound/outbound directions. Changing the assistant, trunk or inbound direction re-creates the inbound SIP dispatch rule. **Required scope:** `phone_numbers:write` (keys without scope restrictions have full access).","tag":"Phone Numbers","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Phone number ID."}],"body":{"required":true,"description":"Partial update. When `assistant_id`, `sip_trunk_id` or `direction_inbound` change, the inbound SIP dispatch rule is re-created (or removed). The display-only `label` can be changed for any phone number owned by the workspace.","fields":[{"name":"assistant_id","required":false,"type":"string","description":"`null` unassigns the assistant.","format":"uuid"},{"name":"sip_trunk_id","required":false,"type":"string","format":"uuid"},{"name":"direction_inbound","required":false,"type":"boolean"},{"name":"direction_outbound","required":false,"type":"boolean"},{"name":"label","required":false,"type":"string","description":"Optional UI display label under the E.164 (not sent to carriers). Null or empty clears it."}]}},
  {"id":"updatePlatformDefaultLimits","method":"PATCH","path":"/platform/default-limits","summary":"Update platform registration and prepaid defaults","description":"Updates one or more registration or prepaid-account settings. Self-service registration controls whether new customers can create an account from your login page. Prepaid access independently controls whether customers without a paid plan can use prepaid credits; when it is disabled, registered customers choose a paid plan before using the platform. **Required scope:** `platform:write`.","tag":"White Label","parameters":[],"body":{"required":true,"fields":[{"name":"self_service_registration_enabled","required":false,"type":"boolean"},{"name":"prepaid_accounts_enabled","required":false,"type":"boolean"},{"name":"prepaid_extra_minute_price_eur","required":false,"type":"number","description":"Customer price per additional minute in EUR major units. When prepaid access is enabled, this price must leave a positive reseller margin.","minimum":0},{"name":"prepaid_default_limits","required":false,"type":"object","description":"Default numeric limits and feature availability for prepaid accounts. Numeric values use -1 for unlimited and 0 for unavailable; boolean values enable or disable the corresponding capability."}]}},
  {"id":"updatePlatformWelcomeCredits","method":"PATCH","path":"/platform/welcome-credits","summary":"Update platform welcome-credit settings","description":"Sets the one-time wallet credits offered to future free customers. Use 0 to disable automatic grants. The setting can exceed the current wallet balance; customer signup still succeeds when the wallet cannot cover a grant, and the credits can be transferred manually later. Available only to API keys belonging to a white-label reseller workspace. **Required scope:** `platform:write`.","tag":"White Label","parameters":[],"body":{"required":true,"fields":[{"name":"welcome_credits","required":true,"type":"number","minimum":0}]}},
  {"id":"updateResellerPlanInclusions","method":"PUT","path":"/reseller/plans/{id}/inclusions","summary":"Update included plan services","description":"Replace the services included in one recurring customer plan price. Requires owner or admin authority, Whitelabel access and settings:write. Only plans without retained subscriptions can change; duplicate a subscribed plan in the dashboard. This configures an offer and never charges a customer or activates a subscription. Empty inclusions remove all configured inclusions.","tag":"White Label","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"inclusions","required":true,"type":"array","items":{"type":"object"}}]}},
  {"id":"updateResellerPlanKnowledgeSources","method":"PATCH","path":"/reseller/plans/{id}/knowledge-sources","summary":"Update plan knowledge source access","description":"Enable or disable knowledge sources on your Whitelabel customer plan. Requires settings:write and owner or admin authority. Changes apply to customers using the plan. Ingestion remains billed in usage credits; prices, included credits and subscriptions are unchanged. Omitted fields keep their current values.","tag":"White Label","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"website_crawling","required":false,"type":"boolean","description":"Allow website crawling; new or changed pages consume credits."},{"name":"cloud_drive","required":false,"type":"boolean","description":"Allow cloud drive sources. The customer workspace must also enable Beta Features."},{"name":"automatic_refresh","required":false,"type":"boolean","description":"Allow scheduled refresh for enabled website and cloud drive sources."}]}},
  {"id":"updateResellerTaxRegistration","method":"PATCH","path":"/reseller/tax/registrations","summary":"Update reseller tax registration","description":"Requires an active Whitelabel payment account, API Access and workspace owner/admin authority. Requires billing:write. Changes affect customer tax calculations. Act only on explicit instructions from the business owner. Registrations describe where to collect tax and do not register a business with tax authorities. Registrations cannot be deleted; end collection with an expiry time.","tag":"White Label","parameters":[],"body":{"required":true,"fields":[{"name":"registration_ref","required":true,"type":"string","description":"Opaque account-bound reference valid for 24 hours. Refresh this view before updating an expired reference."},{"name":"active_from","required":false,"type":"json"},{"name":"expires_at","required":false,"type":"json","description":"now ends tax collection; null removes a scheduled expiry."}]}},
  {"id":"updateResellerTaxSettings","method":"PUT","path":"/reseller/tax/settings","summary":"Update reseller tax settings","description":"Requires an active Whitelabel payment account, API Access and workspace owner/admin authority. Requires billing:write. Changes affect customer tax calculations. Act only on explicit instructions from the business owner. Registrations describe where to collect tax and do not register a business with tax authorities. Registrations cannot be deleted; end collection with an expiry time.","tag":"White Label","parameters":[],"body":{"required":true,"fields":[{"name":"defaults","required":false,"type":"object"},{"name":"head_office","required":false,"type":"object"}]}},
  {"id":"updateRetentionSettings","method":"PATCH","path":"/settings/retention","summary":"Update data retention settings","description":"Updates one or more per-channel retention overrides in months. Set a field to `null` to restore the plan default. Values are clamped to the governing platform or reseller limits. Requires the Data Retention plan feature. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"description":"Per-channel retention overrides in months. `null` clears an override and restores the plan default.","fields":[{"name":"calls_months","required":false,"type":"integer"},{"name":"leads_months","required":false,"type":"integer"},{"name":"email_months","required":false,"type":"integer"},{"name":"sms_months","required":false,"type":"integer"},{"name":"telegram_months","required":false,"type":"integer"},{"name":"slack_months","required":false,"type":"integer"},{"name":"messenger_months","required":false,"type":"integer"},{"name":"teams_months","required":false,"type":"integer"},{"name":"discord_months","required":false,"type":"integer"},{"name":"gchat_months","required":false,"type":"integer"},{"name":"x_months","required":false,"type":"integer"},{"name":"whatsapp_months","required":false,"type":"integer"}]}},
  {"id":"updateRoutine","method":"PATCH","path":"/routines/{id}","summary":"Update a mission","description":"Updates name, prompt, schedule, timezone, or enabled state. Changing schedule fields or `enabled` recomputes `next_run_at`. **Required scope:** `routines:write` (keys without scope restrictions have full access).","tag":"Milian Missions","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Mission ID."}],"body":{"required":true,"description":"Only the fields that change need to be sent.","fields":[{"name":"id","required":false,"type":"string","format":"uuid"},{"name":"name","required":false,"type":"string"},{"name":"prompt","required":false,"type":"string","description":"The instruction the mission runs unattended each time it fires."},{"name":"schedule_type","required":false,"type":"string","description":"manual = only runs via POST /routines/{id}/run. hourly/daily/weekdays/weekly/custom fire on the given schedule.","enum":["manual","hourly","daily","weekdays","weekly","custom"]},{"name":"schedule_minute","required":false,"type":"integer","description":"hourly only — minute of the hour to fire on (0-59), default 0.","minimum":0,"maximum":59},{"name":"schedule_time","required":false,"type":"string","description":"daily/weekdays/weekly only — 24h wall-clock time \"HH:MM\", default \"09:00\"."},{"name":"schedule_weekday","required":false,"type":"integer","description":"weekly only — day of week, 0=Sunday … 6=Saturday.","minimum":0,"maximum":6},{"name":"cron_expression","required":false,"type":"string","description":"custom only — standard 5-field cron (minute hour day-of-month month day-of-week). Occurrences must be at least 10 minutes apart."},{"name":"timezone","required":false,"type":"string","description":"IANA timezone the schedule fields above are evaluated in, e.g. `Europe/Berlin`. Default `UTC`."},{"name":"enabled","required":false,"type":"boolean"},{"name":"required_toolkits","required":false,"type":"array","description":"Replace the connected-app toolkit slugs this mission's prompt depends on. Omit to leave unchanged. The mission refuses to save or run while one of these is not connected.","items":{"type":"string"}}]}},
  {"id":"updateSegment","method":"PATCH","path":"/segments/{id}","summary":"Update a segment","description":"Partial update — only the provided fields change. **Required scope:** `segments:write` (the legacy `calls:write` scope is also accepted; keys without scope restrictions have full access).","tag":"Segments","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Segment ID."}],"body":{"required":true,"description":"Create: `name` is required. Update (PATCH): all fields optional, only provided fields change.","fields":[{"name":"name","required":false,"type":"string","minLength":1},{"name":"description","required":false,"type":"string"},{"name":"filters","required":false,"type":"object","description":"Filter definition. Empty/omitted = \"All Leads\" (no filter). Every field is optional and ANDed together."}]}},
  {"id":"updateSipTrunkIdentity","method":"PATCH","path":"/sip-trunks/{id}","summary":"Update outbound SIP identity","description":"Updates only the outbound identity policy for your own SIP trunk. Incoming routing, phone numbers and provider connections are preserved. Requires sip_trunks:write. Existing configurations keep phone_number until explicitly changed.","tag":"SIP Trunks","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"SIP trunk ID."}],"body":{"required":true,"fields":[{"name":"outbound_from_user_mode","required":false,"type":"string","description":"Outbound From user for your own SIP trunk. Phone number preserves the existing behavior. SIP username uses the authentication username and keeps the primary DID unchanged. Not available on imported carrier connections.","enum":["phone_number","auth_username"],"default":"phone_number"},{"name":"outbound_caller_id_header","required":false,"type":"string","description":"Used with SIP username identity. The primary international DID is sent in the From display name and optionally the selected identity header. Match the carrier caller ID settings.","enum":["from_display","p_asserted_identity","p_preferred_identity"],"default":"from_display"}]}},
  {"id":"updateTeamMemberRole","method":"PATCH","path":"/team-members/{id}","summary":"Change team member role","description":"Change a non-owner member role. Requires owner or admin access and settings:write. Use the ownership transfer operation to appoint a new owner.","tag":"Workspaces","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Membership ID from List team members."}],"body":{"required":true,"fields":[{"name":"role","required":true,"type":"string","enum":["admin","member","viewer","billing"]}]}},
  {"id":"updateTool","method":"PATCH","path":"/tools/{id}","summary":"Update a tool","description":"Revision-protected partial update. `type` is immutable. Sending `•••` for a secret keeps the stored value. A provided `config` replaces the stored configuration: send back every header from the read response (masked values as `•••`); omitted headers are removed. A stale revision returns `409 revision_conflict`. **Required scope:** `assistants:write`.","tag":"Tools","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid","description":"Tool ID."}],"body":{"required":true}},
  {"id":"updateWhatsAppSenderProfile","method":"PATCH","path":"/whatsapp/connectors/{id}/profile","summary":"Update WhatsApp sender profile","description":"Patch local sender settings and business profile fields. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"ai_enabled","required":false,"type":"boolean","description":"Automatically reply to incoming customer messages."},{"name":"ignore_message_reactions","required":false,"type":"boolean","description":"Ignore emoji reactions. When false, new reactions are processed as incoming messages.","default":true},{"name":"keep_conversations_unread","required":false,"type":"boolean","description":"Keep customer messages unread and omit the typing indicator."},{"name":"response_delay_sec","required":false,"type":"integer","description":"Debounce after the latest customer message. Zero means no deliberate delay; AI generation and delivery take additional time.","minimum":0,"maximum":30},{"name":"inactivity_timeout_min","required":false,"type":"integer","description":"Customer inactivity before ending a conversation.","minimum":1,"maximum":1440},{"name":"allow_retrigger","required":false,"type":"boolean","description":"Send the configured conversation-ended webhook again after a customer resumes the same chat and becomes inactive."},{"name":"conversation_ended_webhook_url","required":false,"type":"string","description":"HTTPS destination for the transcript and extracted variables. Null disables this webhook."}]}},
  {"id":"updateWidgetConnector","method":"PATCH","path":"/widget-connectors/{id}","summary":"Update web widget","description":"**Required scope:** `assistants:write`. You can change `assistant_id` to point the widget at another assistant in the same workspace. Phone verification requires explicit acceptance of the current verification SMS credit price. Previously issued browser permissions expire after at most 7 days and are revoked when this widget configuration changes.","tag":"Widgets","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":false,"fields":[{"name":"assistant_id","required":false,"type":"string","description":"Assistant that answers voice and chat from this widget.","format":"uuid"},{"name":"name","required":false,"type":"string"},{"name":"allowed_origins","required":false,"type":"array","description":"Replaces the allowlist. Empty array blocks third-party hosts.","items":{"type":"string"}},{"name":"voice_enabled","required":false,"type":"boolean"},{"name":"chat_enabled","required":false,"type":"boolean"},{"name":"is_active","required":false,"type":"boolean"},{"name":"theme","required":false,"type":"object","description":"Widget appearance. launcher_label_i18n is derived from launcher_label and is read-only — never persist client-supplied maps."},{"name":"phone_verification_enabled","required":false,"type":"boolean","description":"Require the selected email or SMS verification before chat or voice. Available in root workspaces, including a reseller’s own workspace; unavailable to reseller customer workspaces.","default":false},{"name":"phone_verification_accepted_credits","required":false,"type":"number","description":"Explicitly accept the current per-SMS price from the widget list response. Currently 80 credits per accepted send, including resends; code checks and valid remembered visits are free."},{"name":"verification_method","required":false,"type":"string","description":"Verify visitors by SMS or email. Email uses the platform sender without additional credits.","enum":["sms","email"],"default":"sms"}]}},
  {"id":"updateWorkspaceCountry","method":"PATCH","path":"/settings/workspace-country","summary":"Update workspace country","description":"Sets the workspace home country. Pass null to use automatic location detection on the next dashboard or sign-in request. **Required scope:** `settings:write`.","tag":"Settings","parameters":[],"body":{"required":true,"fields":[{"name":"country_code","required":true,"type":"string","description":"Supported ISO-3166-1 alpha-2 country code, or null for automatic detection."}]}},
  {"id":"uploadWhatsAppConnectorAsset","method":"POST","path":"/whatsapp/connectors/{id}/assets","summary":"Upload WhatsApp sender logo / banner","description":"Upload a business profile logo or banner from a URL or inline base64 — exactly one of `url` / `data_base64` is required. `url` is downloaded server-side (private/loopback/link-local/cloud-metadata hosts are blocked) and capped at 8 MB, same as `data_base64`; only PNG/JPEG/WebP are accepted. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"kind","required":true,"type":"string","enum":["logo","banner"]},{"name":"url","required":false,"type":"string","format":"uri"},{"name":"data_base64","required":false,"type":"string"},{"name":"content_type","required":false,"type":"string","description":"Required alongside data_base64."}]}},
  {"id":"uploadWhatsAppTemplateReviewSample","method":"POST","path":"/whatsapp/templates/media","summary":"Upload a WhatsApp template review sample","description":"Upload the review sample required by an IMAGE, VIDEO, or DOCUMENT template header. Send base64-encoded JPEG/PNG, MP4, or PDF data up to 3 MB. The returned handle belongs in HEADER.example.header_handle. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"connector_id","required":true,"type":"string","format":"uuid"},{"name":"format","required":true,"type":"string","enum":["IMAGE","VIDEO","DOCUMENT"]},{"name":"file_name","required":true,"type":"string"},{"name":"content_type","required":true,"type":"string","enum":["image/jpeg","image/png","video/mp4","application/pdf"]},{"name":"data_base64","required":true,"type":"string","format":"byte"}]}},
  {"id":"uploadWidgetConnectorLogo","method":"POST","path":"/widget-connectors/{id}/logo","summary":"Upload widget header logo","description":"Upload a header logo from a URL or inline base64 — exactly one of `url` / `data_base64` is required. `url` is downloaded server-side (private/loopback/link-local/cloud-metadata hosts are blocked) and capped at 10 MB, same as `data_base64`; only PNG/JPEG are accepted (no SVG — stored-XSS risk over the storage origin). This endpoint only uploads the file; write the returned `url` into `theme.logo_url` via `PATCH /widget-connectors/{id}` to actually use it. **Required scope:** `assistants:write`.","tag":"Widgets","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"url","required":false,"type":"string","format":"uri"},{"name":"data_base64","required":false,"type":"string"},{"name":"content_type","required":false,"type":"string","description":"Required alongside data_base64."}]}},
  {"id":"verifyCallInputs","method":"POST","path":"/calls/{id}/verify-inputs","summary":"Verify call inputs","description":"Read-only comparison of explicitly expected inputs with the resolved call-start snapshot. Returns only requested keys and matched, missing, different, or not_available statuses. A queued call or unavailable snapshot is not evidence of successful input delivery; matching inputs do not establish that the scenario succeeded. POST keeps expected values out of URLs. Required scope: calls:read.","tag":"Calls","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"expected_variables","required":true,"type":"json"}]}},
  {"id":"verifyCustomDomain","method":"POST","path":"/custom-domain/verify","summary":"Check custom domain DNS","description":"Rechecks the ownership challenge and reads the current project-specific DNS/TLS configuration. DNS propagation may take time; an incomplete setup returns `200` with `ready: false` and updated `required_records`. **Required scope:** `settings:write` or `assistants:write`. Requires workspace owner/admin role. **Requires the white-label entitlement** (plan add-on `whitelabel`, or a workspace override). Workspaces without it get `403 whitelabel_not_in_plan`, and only workspace owners and admins may call it.","tag":"Settings","parameters":[]},
  {"id":"verifyEmailDomain","method":"POST","path":"/email/domains/{id}/verify","summary":"Verify an email domain","description":"Re-checks the domain's DNS records and flips it to `verified` once every record resolves correctly (also finishing the inbound-receiving setup). Safe to call repeatedly while DNS propagates. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}]},
  {"id":"whatsAppSenderProfileAction","method":"POST","path":"/whatsapp/connectors/{id}/profile","summary":"Run a WhatsApp sender profile action","description":"Actions: `sync` (push the business profile for Cloud senders; local `logo_url` is uploaded when `profile_picture_handle` is omitted), `refresh` (pull the business profile), `test_read_receipts_webhook`, or `rotate_read_receipts_webhook_secret`. Rotation invalidates the previous secret immediately and returns the new `signing_secret` exactly once. Existing secrets cannot be retrieved. Banner stays local-only. Coexistence senders must edit their public profile in the WhatsApp Business app; `sync` returns HTTP 400, while `refresh` and local draft updates remain available. **Required scope:** `assistants:write`.","tag":"Messaging","parameters":[{"name":"id","in":"path","required":true,"type":"string","format":"uuid"}],"body":{"required":true,"fields":[{"name":"action","required":true,"type":"string","enum":["sync","refresh","test_read_receipts_webhook","rotate_read_receipts_webhook_secret"]},{"name":"profile_picture_handle","required":false,"type":"string","description":"Optional Meta resumable upload handle. When omitted on sync, the connector logo_url is uploaded automatically."}]}},
  {"id":"whatsAppTemplatesAction","method":"POST","path":"/whatsapp/templates","summary":"Create / update / submit / sync / send / delete WhatsApp templates","description":"Body.action: `create` | `update` | `submit` | `sync` | `send` | `set_opt_out_buttons` | `delete`. Sync follows all provider pages and imports templates that do not yet exist locally. Draft updates remain local. On editable provider templates, only component or category changes are sent to Meta; parameter mappings and opt-out configuration remain local. Submit returns the provider-controlled review status. Send supports text headers/body plus static quick-reply, URL, phone and call-permission components; templates requiring runtime media, location, dynamic-URL or copy-code values are rejected locally. **Required scope:** `assistants:write`. Requires WhatsApp text in the workspace plan.","tag":"Messaging","parameters":[],"body":{"required":true,"fields":[{"name":"action","required":false,"type":"string","enum":["create","update","submit","sync","send","set_opt_out_buttons","delete"],"default":"create"},{"name":"connector_id","required":false,"type":"string","format":"uuid"},{"name":"id","required":false,"type":"string","format":"uuid"},{"name":"template_id","required":false,"type":"string","format":"uuid"},{"name":"name","required":false,"type":"string"},{"name":"body_text","required":false,"type":"string","description":"Template body. Variables must use positive contiguous numbering: {{1}}, {{2}}, {{3}}."},{"name":"library_template_name","required":false,"type":"string","description":"Official library preset name. When supplied with action=create, the preset is created directly for the sender."},{"name":"library_button_values","required":false,"type":"object","description":"Button index to HTTPS URL or E.164 phone number. Required for official library templates with URL or phone-number buttons."},{"name":"language","required":false,"type":"string"},{"name":"category","required":false,"type":"string","enum":["UTILITY","MARKETING","AUTHENTICATION"]},{"name":"parameter_bindings","required":false,"type":"object","description":"Maps component positions (`1`, `2`, `header.1`) to system, lead, assistant, or custom variable keys."},{"name":"opt_out_buttons","required":false,"type":"array","description":"Canonical QUICK_REPLY labels whose tap suppresses the contact. With action=set_opt_out_buttons this is always a local-only update.","items":{"type":"string"}},{"name":"components","required":false,"type":"array","description":"Ordered template components. The core composer supports HEADER (TEXT, IMAGE, VIDEO, DOCUMENT, LOCATION), BODY, FOOTER, and BUTTONS (QUICK_REPLY, URL, PHONE_NUMBER, COPY_CODE). Media headers require example.header_handle from the provider review upload flow. Updates replace the complete component array. Call-permission templates use a BODY plus a CALL_PERMISSION_REQUEST component.","items":{"type":"object"}},{"name":"to_number","required":false,"type":"string"},{"name":"context","required":false,"type":"object"}]}},
];
